/* =====================================================================
   Base de questions de Wikiguessr
   =====================================================================
   Chaque manche est une entrée de cette liste : le joueur lit l'indice,
   puis place sur le globe le lieu demandé (le lieu lui-même, un lieu de
   naissance, le lieu d'un événement…).

   AJOUTER UNE QUESTION
   Copier une ligne dans le bloc du thème voulu et la modifier :
     n : niveau, selon les connaissances nécessaires pour répondre
         1 = facile (sujet très connu), 2 = moyen, 3 = difficile (sujet
         secondaire, ou lieu peu connu ou surprenant)
     k : type de manche, si différent de celui du bloc (voir TYPES).
         Pour une personne, préférer « vie » (avec q) quand le lieu de
         naissance est anecdotique : lieu de sa mort, de son exploit…
     t : titre affiché (de préférence le titre de l'article Wikipédia)
     w : titre exact de l'article Wikipédia, s'il diffère de t
         (sert à la photo et au lien « Lire l'article »)
     c : sous-catégorie affichée (Peinture, Football, Président…)
     q : ce qu'il faut placer, si différent du libellé du type
     x : indice affiché pendant la manche. Il ne doit jamais contenir
         le nom du lieu à trouver.
     e : courte explication affichée après la réponse (facultatif)
     p : lieu affiché après la réponse
     a, o : latitude et longitude du lieu (degrés décimaux)

   AJOUTER UN THÈME
   Ajouter une ligne dans THEMES (nom, couleur), puis un bloc ajouter().
   Le thème apparaît alors tout seul dans le menu de l'accueil.

   VÉRIFIER
   node outils/verifier-questions.js  (doublons, champs manquants,
   indice qui contient la réponse, répartition par thème et niveau)
   ===================================================================== */

/* Thèmes proposés dans le menu de l'accueil, dans cet ordre. La couleur sert aux points du globe d'accueil. */
const THEMES = {
  lieux:     { nom: 'Lieux',       long: 'Lieux emblématiques',    couleur: '#ffb547' },
  celeb:     { nom: 'Célébrités',  long: 'Célébrités',             couleur: '#ff6f9c' },
  sport:     { nom: 'Sport',       long: 'Sport',                  couleur: '#5ec8ff' },
  politique: { nom: 'Politique',   long: 'Politique',              couleur: '#a99bff' },
  histoire:  { nom: 'Histoire',    long: 'Histoire',               couleur: '#ff8f5a' },
  crime:     { nom: 'Criminels',   long: 'Criminels célèbres',     couleur: '#ff5c6c' },
  culture:   { nom: 'Culture',     long: 'Culture et patrimoine',  couleur: '#f4e06d' },
  evt:       { nom: 'Événements',  long: 'Événements historiques', couleur: '#e9eef2' },
  science:   { nom: 'Sciences',    long: 'Sciences et inventions', couleur: '#4fe0c2' },
  pop:       { nom: 'Pop culture', long: 'Culture populaire',      couleur: '#a8ec5a' }
};

/* Types de manche : ce qu'il faut placer (affiché dans la pastille) et le préfixe de la réponse. */
const TYPES = {
  lieu:   { quoi: '',                                rep: '' },
  perso:  { quoi: 'lieu de naissance',               rep: 'Né(e) à ' },
  evt:    { quoi: 'lieu de l’événement',             rep: '' },
  oeuvre: { quoi: 'lieu où l’œuvre est exposée',     rep: '' },
  recit:  { quoi: 'lieu où se déroule l’histoire',   rep: '' },
  vie:    { quoi: 'lieu lié à sa vie',               rep: '' }  /* une personne, mais un autre lieu que sa naissance : préciser q */
};

const QUESTIONS = [];
function ajouter(h, k, liste) {
  liste.forEach(d => QUESTIONS.push(Object.assign({ h, k }, d)));
}

/* ---- Lieux emblématiques : monuments, sites historiques, lieux religieux, merveilles du patrimoine (on place le lieu) ---- */
ajouter('lieux', 'lieu', [
{n:1,t:"Tour Eiffel",c:"Monument",x:"Tour de fer de 330 mètres construite pour l'Exposition universelle de 1889, longtemps la plus haute construction du monde.",e:"Elle se dresse sur le Champ-de-Mars, au bord de la Seine, dans le 7e arrondissement de Paris, face au palais de Chaillot et aux jardins du Trocadéro.",p:"Paris, France",a:48.8584,o:2.2945},
{n:1,t:"Machu Picchu",c:"Site archéologique",x:"Citadelle inca du XVe siècle perchée à 2 430 mètres d'altitude, révélée au monde occidental en 1911.",e:"Elle domine la vallée de l'Urubamba, dans la région de Cuzco, au Pérou ; on y monte depuis le village d'Aguas Calientes, au pied de la montagne.",p:"Cuzco, Pérou",a:-13.1631,o:-72.545},
{n:1,t:"Grande Barrière de corail",c:"Nature",x:"Plus vaste ensemble corallien de la planète, long d'environ 2 300 kilomètres et visible depuis l'espace.",e:"Elle longe la côte du Queensland, au nord-est de l'Australie, dans la mer de Corail ; les villes de Cairns et de Townsville servent de portes d'entrée.",p:"Queensland, Australie",a:-18.29,o:147.7},
{n:1,t:"Taj Mahal",c:"Monument",x:"Mausolée de marbre blanc élevé au XVIIe siècle par un empereur moghol à la mémoire de son épouse.",e:"Il se dresse au bord de la Yamuna, à Agra, dans l'État de l'Uttar Pradesh, au nord de l'Inde, au sud-est de Delhi.",p:"Agra, Inde",a:27.1751,o:78.0421},
{n:1,t:"Kilimandjaro",c:"Montagne",x:"Plus haut sommet du continent africain avec 5 895 mètres, volcan isolé dont les glaciers reculent.",e:"Il se dresse dans le nord-est de la Tanzanie, près de la frontière kényane et de la ville de Moshi ; son point culminant, Uhuru Peak, couronne le cratère du Kibo.",p:"Tanzanie",a:-3.0674,o:37.3556},
{n:1,t:"Colisée",c:"Monument",x:"Amphithéâtre elliptique inauguré en 80, qui pouvait accueillir plusieurs dizaines de milliers de spectateurs.",e:"Il se trouve au cœur de Rome, à l'est du Forum romain, dans le creux formé entre le Palatin, le Caelius et l'Esquilin, près de l'arc de Constantin.",p:"Rome, Italie",a:41.8902,o:12.4922},
{n:1,t:"Angkor Vat",c:"Site archéologique",x:"Temple du XIIe siècle entouré de douves, plus grand monument religieux du monde, représenté sur un drapeau national.",e:"Il se trouve à quelques kilomètres au nord de la ville de Siem Reap, dans le nord-ouest du Cambodge, non loin du grand lac Tonlé Sap.",p:"Siem Reap, Cambodge",a:13.4125,o:103.867},
{n:1,t:"Pétra",c:"Site archéologique",x:"Cité nabatéenne dont les façades sont taillées directement dans la roche rose d'un défilé.",e:"Elle se trouve dans le sud de la Jordanie, à côté de la petite ville de Wadi Moussa, dans une région montagneuse entre la mer Morte et le golfe d'Aqaba.",p:"Jordanie",a:30.3285,o:35.4444},
{n:1,t:"Chichén Itzá",c:"Site archéologique",x:"Cité maya dominée par une pyramide à degrés, le temple de Kukulcán, alignée sur les équinoxes.",e:"Elle se trouve au cœur de la péninsule du Yucatán, au Mexique, entre Mérida et Cancún, à l'ouest de la ville coloniale de Valladolid.",p:"Yucatán, Mexique",a:20.6843,o:-88.5678},
{n:1,t:"Statue de la Liberté",c:"Monument",x:"Statue de cuivre offerte en 1886 par un pays ami, qui accueille les bateaux à l'entrée d'une grande baie.",e:"Elle se dresse sur Liberty Island, un îlot de la baie de New York situé au sud de Manhattan, tout près des rives du New Jersey.",p:"New York, États-Unis",a:40.6892,o:-74.0445},
{n:1,t:"Christ Rédempteur",c:"Monument",x:"Statue d'Art déco de 30 mètres, bras ouverts, érigée en 1931 au sommet du mont du Corcovado.",e:"Il domine Rio de Janeiro depuis le parc national de la Tijuca, avec vue sur la baie de Guanabara, le Pain de Sucre et la plage de Copacabana.",p:"Rio de Janeiro, Brésil",a:-22.9519,o:-43.2105},
{n:1,t:"Pyramide de Khéops",c:"Site archéologique",x:"Seule des sept merveilles du monde antique encore debout, haute à l'origine de 146 mètres.",e:"Elle se dresse sur le plateau de Gizeh, aux portes du Caire, à côté des pyramides de Khéphren et de Mykérinos et non loin du Sphinx.",p:"Gizeh, Égypte",a:29.9792,o:31.1342},
{n:1,t:"Stonehenge",c:"Site archéologique",x:"Cercle de mégalithes érigé il y a plus de quatre millénaires, dont les pierres bleues venaient de loin.",e:"Il se dresse dans la plaine de Salisbury, dans le Wiltshire, au sud de l'Angleterre ; ses pierres bleues proviennent des collines de Preseli, au pays de Galles.",p:"Wiltshire, Royaume-Uni",a:51.1789,o:-1.8262},
{n:1,t:"Mont Fuji",c:"Montagne",x:"Volcan à cône presque parfait culminant à 3 776 mètres, sujet de nombreuses estampes.",e:"Il se dresse sur l'île de Honshū, entre les préfectures de Shizuoka et de Yamanashi, à une centaine de kilomètres au sud-ouest de Tokyo.",p:"Honshū, Japon",a:35.3606,o:138.7274},
{n:1,t:"Everest",c:"Montagne",x:"Point culminant de la Terre à 8 849 mètres, gravi pour la première fois en 1953.",e:"Il se dresse sur la frontière entre le Népal et le Tibet ; les Népalais l'appellent Sagarmatha et les Tibétains Chomolungma.",p:"Himalaya, Népal et Chine",a:27.9881,o:86.925},
{n:1,t:"Sagrada Família",c:"Monument",x:"Basilique commencée en 1882 par un architecte visionnaire et toujours en chantier au XXIe siècle.",e:"Elle s'élève dans le quartier de l'Eixample, à Barcelone, en Catalogne ; Antoni Gaudí, qui lui consacra la fin de sa vie, repose dans sa crypte.",p:"Barcelone, Espagne",a:41.4036,o:2.1744},
{n:1,t:"Parthénon",c:"Site archéologique",x:"Temple dorique du Ve siècle av. J.-C. dédié à la déesse de la sagesse, érigé sur une acropole.",e:"Il couronne l'Acropole, le rocher qui domine le centre d'Athènes ; à son pied, le musée de l'Acropole, ouvert en 2009, expose une partie de ses sculptures.",p:"Athènes, Grèce",a:37.9715,o:23.7267},
{n:1,t:"Cité interdite",c:"Monument",x:"Ancien palais impérial de près de mille bâtiments, résidence de vingt-quatre empereurs.",e:"Elle occupe le centre de Pékin, juste au nord de la place Tian'anmen ; ses palais abritent aujourd'hui le musée du Palais, l'un des plus visités au monde.",p:"Pékin, Chine",a:39.9163,o:116.3972},
{n:1,t:"Burj Khalifa",c:"Monument",x:"Gratte-ciel de 828 mètres, la plus haute structure jamais construite, inaugurée en 2010.",e:"Il se dresse dans le quartier de Downtown Dubai, à côté du Dubai Mall, dans l'un des sept émirats de la fédération, sur la côte du golfe Persique.",p:"Dubaï, Émirats arabes unis",a:25.1972,o:55.2744},
{n:1,t:"Uluru",c:"Nature",x:"Immense monolithe de grès rouge, lieu sacré pour les Anangu, qui change de couleur au coucher du soleil.",e:"Il se dresse au centre de l'Australie, dans le parc national d'Uluru-Kata Tjuta, à plus de 300 kilomètres au sud-ouest de la ville d'Alice Springs.",p:"Territoire du Nord, Australie",a:-25.3444,o:131.0369},
{n:1,t:"Mont-Saint-Michel",c:"Monument",x:"Abbaye bâtie sur un îlot rocheux que les grandes marées transforment en île plusieurs fois par an.",e:"Il se dresse dans la baie du Mont-Saint-Michel, près de l'embouchure du Couesnon, la rivière qui marque traditionnellement la limite entre la Normandie et la Bretagne.",p:"Manche, France",a:48.6361,o:-1.5115},
{n:1,t:"Grand Canyon",c:"Nature",x:"Gorge de plus de 440 kilomètres de long, creusée par un fleuve dans des strates vieilles de deux milliards d'années.",e:"Il entaille le plateau du Colorado, dans le nord de l'Arizona ; au fond coule le fleuve Colorado, jusqu'à environ 1 800 mètres sous les rebords.",p:"Arizona, États-Unis",a:36.1069,o:-112.1129},
{n:1,t:"Chutes du Niagara",c:"Nature",x:"Trois chutes spectaculaires situées sur la frontière entre deux pays nord-américains.",e:"Elles se trouvent sur la rivière Niagara, qui relie le lac Érié au lac Ontario, entre les deux villes de Niagara Falls, l'une canadienne, l'autre américaine.",p:"Ontario / New York",a:43.0799,o:-79.0747},
{n:1,t:"Mont Blanc",c:"Montagne",x:"Plus haut sommet des Alpes avec 4 805 mètres, dont une partie des versants est disputée entre deux pays.",e:"Il domine la vallée de Chamonix, en Haute-Savoie, côté français, et la vallée d'Aoste côté italien ; un tunnel routier traverse son massif.",p:"Alpes, France et Italie",a:45.8326,o:6.8652},
{n:1,t:"Golden Gate Bridge",c:"Monument",x:"Pont suspendu d'un rouge orangé, long de 2 737 mètres, ouvert en 1937 à l'entrée d'une grande baie.",e:"Il franchit le détroit du Golden Gate, entre la baie et l'océan Pacifique, et relie San Francisco au comté de Marin, au nord, en Californie.",p:"San Francisco, États-Unis",a:37.8199,o:-122.4783},
{n:1,t:"Tour de Pise",c:"Monument",x:"Campanile de marbre commencé en 1173 dont le sol meuble a provoqué une inclinaison célèbre.",e:"Elle se dresse sur la piazza dei Miracoli, à Pise, en Toscane, aux côtés de la cathédrale et du baptistère ; la ville est traversée par l'Arno.",p:"Toscane, Italie",a:43.723,o:10.3966},
{n:1,t:"Grande Muraille de Chine",c:"Monument",x:"Ensemble de fortifications étalé sur des milliers de kilomètres, dont les parties les mieux conservées datent des Ming.",e:"Le tronçon de Badaling, l'un des plus visités et des mieux restaurés, serpente sur les montagnes du district de Yanqing, au nord-ouest de Pékin.",p:"Badaling, Chine",a:40.3597,o:116.02},
{n:1,t:"Notre-Dame de Paris",c:"Lieu religieux",x:"Cathédrale gothique commencée en 1163, dont la flèche s'effondre lors de l'incendie d'avril 2019. Elle rouvre en décembre 2024.",e:"Elle se dresse sur l'île de la Cité, et c'est devant son parvis que se trouve le point zéro des routes de France.",p:"Paris, France",a:48.853,o:2.3499},
{n:1,t:"Big Ben",c:"Monument",x:"Surnom de la grande cloche d'une tour néogothique de 96 mètres achevée en 1859, dont le carillon rythme la vie d'un Parlement.",e:"La tour, rebaptisée tour Élisabeth en 2012, fait partie du palais de Westminster, à Londres.",p:"Londres, Royaume-Uni",a:51.5007,o:-0.1246},
{n:1,t:"Kremlin",w:"Kremlin de Moscou",c:"Monument",x:"Forteresse aux murs de brique rouge et aux tours pointues, siège du pouvoir des tsars puis du gouvernement soviétique et russe.",e:"Il domine la place Rouge, au cœur de Moscou.",p:"Moscou, Russie",a:55.752,o:37.6175},
{n:1,t:"Empire State Building",c:"Gratte-ciel",x:"Gratte-ciel Art déco de 381 mètres (443 avec l'antenne) achevé en 1931 en un peu plus d'un an, plus haut immeuble du monde pendant quarante ans.",e:"Il se trouve sur la Cinquième Avenue, à Manhattan ; King Kong l'escalade dans le film de 1933.",p:"New York, États-Unis",a:40.7484,o:-73.9857},
{n:1,t:"Maison-Blanche",c:"Monument",x:"Résidence et bureau du président des États-Unis depuis 1800, incendiée par les Britanniques en 1814 puis reconstruite.",e:"Elle se trouve au 1600 Pennsylvania Avenue, à Washington.",p:"Washington, États-Unis",a:38.8977,o:-77.0365},
{n:1,t:"Pompéi",c:"Site archéologique",x:"Cité romaine ensevelie sous les cendres d'une éruption en l'an 79, dont les fouilles révèlent la vie quotidienne de l'Antiquité.",e:"Elle se trouve au pied du Vésuve, près de Naples.",p:"Campanie, Italie",a:40.7489,o:14.4848},
{n:1,t:"Porte de Brandebourg",c:"Monument",x:"Porte néoclassique surmontée d'un quadrige, achevée en 1791. Longtemps prise dans le no man's land d'un mur, elle est devenue le symbole de la réunification d'un pays.",e:"Malgré son nom, elle ne se trouve pas à Brandebourg mais à Berlin, au bout de l'avenue Unter den Linden.",p:"Berlin, Allemagne",a:52.5163,o:13.3777},
{n:1,t:"Galerie des Glaces",c:"Château",x:"Galerie de 73 mètres ornée de 357 miroirs, où fut signé le traité qui met fin à la Première Guerre mondiale en 1919.",e:"Elle se trouve au château de Versailles, voulu par Louis XIV.",p:"Versailles, France",a:48.8049,o:2.1204},
{n:1,t:"Auschwitz-Birkenau",w:"Auschwitz",c:"Lieu de mémoire",x:"Le plus grand camp de concentration et d'extermination nazi, où environ 1,1 million de personnes, en grande majorité juives, ont été assassinées. Il est libéré le 27 janvier 1945.",e:"Le site, aujourd'hui musée et mémorial, se trouve près de la ville d'Oświęcim, dans le sud de la Pologne.",p:"Oświęcim, Pologne",a:50.0359,o:19.1783},
{n:2,t:"Cathédrale Saint-Basile-le-Bienheureux",c:"Monument",x:"Église aux bulbes colorés commandée par Ivan le Terrible pour célébrer une conquête, au bord d'une grande place.",e:"Elle se dresse à l'extrémité sud de la place Rouge, à Moscou, au pied des remparts du Kremlin et près des rives de la Moskova.",p:"Moscou, Russie",a:55.7525,o:37.6231},
{n:2,t:"Chutes Victoria",c:"Nature",x:"Rideau d'eau large de plus d'un kilomètre que les habitants appellent « la fumée qui gronde ».",e:"Elles sont formées par le Zambèze, qui marque la frontière entre la Zambie et le Zimbabwe, entre les villes de Livingstone et de Victoria Falls.",p:"Frontière Zambie-Zimbabwe",a:-17.9243,o:25.8572},
{n:2,t:"Alhambra",c:"Monument",x:"Palais-forteresse de la dynastie nasride, chef-d'œuvre de l'art hispano-mauresque avec ses cours à fontaines.",e:"Le palais domine Grenade, en Andalousie, depuis la colline de la Sabika, face au vieux quartier de l'Albaicín, avec les sommets de la Sierra Nevada en toile de fond.",p:"Grenade, Espagne",a:37.176,o:-3.5881},
{n:2,t:"Château de Neuschwanstein",c:"Monument",x:"Château romantique commandé par un roi de Bavière rêveur, qui a inspiré celui d'un célèbre dessin animé.",e:"Il se dresse sur un éperon rocheux au-dessus du village de Schwangau, près de Füssen, au pied des Alpes, non loin de la frontière autrichienne.",p:"Bavière, Allemagne",a:47.5576,o:10.7498},
{n:2,t:"Cappadoce",c:"Région",x:"Région de cheminées de fée et de villes souterraines, survolée chaque matin par des centaines de montgolfières.",e:"Elle s'étend au centre de la Turquie, autour de Göreme, Nevşehir et Ürgüp, sur des plateaux de tuf volcanique sculptés par l'érosion.",p:"Anatolie, Turquie",a:38.6431,o:34.8289},
{n:2,t:"Lac Baïkal",c:"Nature",x:"Plus profond lac du monde (1 642 m), contenant environ un cinquième de l'eau douce liquide de la planète.",e:"Il s'étire sur plus de 600 kilomètres dans le sud de la Sibérie, entre la région d'Irkoutsk et la Bouriatie, non loin de la frontière mongole.",p:"Sibérie, Russie",a:53.5,o:108},
{n:2,t:"Salar d'Uyuni",c:"Nature",x:"Plus grand désert de sel du monde, qui devient un miroir géant à la saison des pluies.",e:"Il s'étend à plus de 3 600 mètres d'altitude sur l'Altiplano, dans le département de Potosí, au sud-ouest de la Bolivie.",p:"Bolivie",a:-20.1338,o:-67.4891},
{n:2,t:"Île de Pâques",c:"Île",x:"Île volcanique isolée au milieu d'un océan, célèbre pour ses près de 900 statues de pierre, les moaï.",e:"Elle se trouve dans le Pacifique sud, à environ 3 500 kilomètres des côtes chiliennes ; le Chili l'a annexée en 1888.",p:"Rapa Nui, Chili",a:-27.1127,o:-109.3497},
{n:2,t:"Îles Galápagos",c:"Île",x:"Archipel volcanique où un naturaliste anglais observa en 1835 des pinsons qui nourrirent sa théorie de l'évolution.",e:"L'archipel se trouve dans l'océan Pacifique, à près de 1 000 kilomètres à l'ouest des côtes de l'Équateur, de part et d'autre de la ligne équatoriale.",p:"Équateur",a:-0.9538,o:-90.9656},
{n:2,t:"Cervin",c:"Montagne",x:"Pyramide rocheuse presque parfaite dont la première ascension, en 1865, s'acheva par un drame.",e:"Il se dresse sur la frontière entre la Suisse et l'Italie, au-dessus de Zermatt, dans le Valais, et de Breuil-Cervinia, dans la vallée d'Aoste.",p:"Alpes, Suisse et Italie",a:45.9763,o:7.6586},
{n:2,t:"Vésuve",c:"Volcan",x:"Volcan dont l'éruption de l'an 79 ensevelit deux cités romaines sous les cendres.",e:"Il domine la baie de Naples, à une dizaine de kilomètres à l'est de la ville ; les ruines de Pompéi et d'Herculanum s'étendent à son pied.",p:"Campanie, Italie",a:40.8224,o:14.4289},
{n:2,t:"Etna",c:"Volcan",x:"Plus haut volcan actif d'Europe, en éruption fréquente, dont les coulées touchent parfois des villages.",e:"Il domine la côte est de la Sicile, au-dessus de la ville de Catane ; culminant à plus de 3 300 mètres, c'est le point le plus haut de l'île.",p:"Sicile, Italie",a:37.751,o:14.9934},
{n:2,t:"Zanzibar",c:"Île",x:"Archipel aux épices et à la vieille ville de pierre, ancien carrefour du commerce swahili et du commerce d'esclaves.",e:"Cet archipel semi-autonome de Tanzanie se trouve dans l'océan Indien, à quelques dizaines de kilomètres de la côte ; son île principale s'appelle Unguja.",p:"Tanzanie",a:-6.1659,o:39.2026},
{n:2,t:"Madagascar",c:"Île",x:"Quatrième plus grande île du monde, où vivent les lémuriens et une flore largement endémique.",e:"Elle est séparée de la côte africaine par le canal du Mozambique ; sa capitale, Antananarivo, se trouve sur les hauts plateaux du centre de l'île.",p:"Océan Indien",a:-18.77,o:46.87},
{n:2,t:"Fosse des Mariannes",c:"Océan",x:"Point le plus profond connu des océans, à près de 11 000 mètres sous la surface.",e:"Elle décrit un arc dans l'ouest du Pacifique, à l'est des îles Mariannes et près de Guam ; son point le plus profond porte le nom de Challenger Deep.",p:"Pacifique occidental",a:11.373,o:142.591},
{n:2,t:"Alcatraz",c:"Histoire",x:"Ancien pénitencier fédéral sur un îlot rocheux, réputé impossible à quitter à la nage dans une baie aux eaux glacées.",e:"L'île se trouve dans la baie de San Francisco, à environ deux kilomètres de la ville ; le pénitencier fédéral y a fonctionné de 1934 à 1963.",p:"Californie, États-Unis",a:37.8267,o:-122.423},
{n:2,t:"Space Needle",c:"Monument",x:"Tour d'observation à la silhouette de soucoupe, bâtie pour l'Exposition universelle de 1962.",e:"Elle se dresse dans le Seattle Center, au nord du centre-ville de Seattle, grande ville portuaire du Puget Sound, dans l'État de Washington.",p:"Seattle, États-Unis",a:47.6205,o:-122.3493},
{n:2,t:"Loch Ness",c:"Nature",x:"Lac d'eau douce long et profond, associé depuis les années 1930 à la légende d'un monstre.",e:"Il s'étire sur plus de 35 kilomètres le long de la grande faille du Great Glen, au sud-ouest d'Inverness, dans les Highlands écossais.",p:"Highlands, Écosse",a:57.3229,o:-4.4244},
{n:2,t:"Falaises de Moher",c:"Nature",x:"Falaises de 214 mètres au plus haut, battues par l'Atlantique sur environ quatorze kilomètres.",e:"Elles bordent la côte atlantique du comté de Clare, dans l'ouest de l'Irlande, entre les villages de Doolin et de Liscannor ; la tour O'Brien se dresse près de leur point le plus haut.",p:"Comté de Clare, Irlande",a:52.9715,o:-9.4265},
{n:2,t:"Sainte-Sophie",c:"Monument",x:"Basilique du VIe siècle à la coupole spectaculaire, devenue mosquée, musée, puis de nouveau mosquée.",e:"Elle se dresse sur la rive européenne d'Istanbul, dans le quartier de Sultanahmet, face à la Mosquée bleue et à deux pas du palais de Topkapı.",p:"Istanbul, Turquie",a:41.0086,o:28.9802},
{n:2,t:"Delphes",c:"Site archéologique",x:"Sanctuaire d'Apollon où la Pythie rendait ses oracles, considéré par les Grecs comme le nombril du monde.",e:"Le site s'accroche aux pentes du mont Parnasse, au-dessus d'une vallée plantée d'oliviers qui descend vers le golfe de Corinthe, au nord-ouest d'Athènes.",p:"Phocide, Grèce",a:38.4824,o:22.501},
{n:2,t:"Cinque Terre",c:"Région",x:"Cinq villages colorés accrochés à des falaises en terrasses, reliés par des sentiers côtiers et un train.",e:"Ces villages, Monterosso, Vernazza, Corniglia, Manarola et Riomaggiore, bordent la Riviera ligure du Levant, au nord-ouest de La Spezia.",p:"Ligurie, Italie",a:44.1461,o:9.6439},
{n:2,t:"Mont Rushmore",c:"Monument",x:"Quatre visages de présidents sculptés dans le granit entre 1927 et 1941.",e:"Il se trouve dans les Black Hills, dans l'ouest du Dakota du Sud, près de la petite ville de Keystone et non loin de Rapid City.",p:"Dakota du Sud, États-Unis",a:43.8791,o:-103.4591},
{n:2,t:"Monument Valley",c:"Nature",x:"Buttes de grès rouge dressées dans le désert, décor récurrent des westerns de John Ford.",e:"Elle chevauche la frontière entre l'Arizona et l'Utah, sur le territoire de la nation navajo, qui l'administre sous forme de parc tribal.",p:"Arizona et Utah, États-Unis",a:36.998,o:-110.0985},
{n:2,t:"Parc national de Yellowstone",c:"Nature",x:"Premier parc national du monde, créé en 1872, posé sur un supervolcan et riche en geysers et en bisons.",e:"Il couvre surtout le nord-ouest du Wyoming et déborde sur le Montana et l'Idaho ; son geyser le plus célèbre se nomme Old Faithful.",p:"Wyoming, États-Unis",a:44.428,o:-110.5885},
{n:2,t:"Tour CN",c:"Monument",x:"Tour de télécommunications de 553 mètres, la plus haute du monde de 1975 à 2007.",e:"Elle se dresse dans le centre-ville de Toronto, en Ontario, au bord du lac Ontario, juste à côté du stade Rogers Centre.",p:"Toronto, Canada",a:43.6426,o:-79.3871},
{n:2,t:"Chutes d'Iguazú",c:"Nature",x:"Environ 275 cascades en fer à cheval dans la forêt, dont la « Gorge du diable », à la frontière de deux pays.",e:"Elles sont formées par la rivière Iguazú, peu avant sa confluence avec le Paraná, près des villes de Puerto Iguazú, en Argentine, et de Foz do Iguaçu, au Brésil.",p:"Argentine et Brésil",a:-25.6953,o:-54.4367},
{n:2,t:"Lac Titicaca",c:"Nature",x:"Plus haut grand lac navigable du monde, à 3 800 mètres, bordé d'îles de roseaux flottantes.",e:"Il s'étend sur l'Altiplano andin, partagé entre le Pérou et la Bolivie ; la ville de Puno borde sa rive péruvienne et Copacabana sa rive bolivienne.",p:"Pérou et Bolivie",a:-15.9254,o:-69.3354},
{n:2,t:"Ushuaïa",c:"Ville",x:"Ville la plus australe du monde, surnommée « le bout du monde », ouverte sur un canal portant le nom d'un navire.",e:"C'est la capitale de la province argentine de la Terre de Feu ; elle s'adosse aux derniers contreforts des Andes, face au canal Beagle.",p:"Terre de Feu, Argentine",a:-54.8019,o:-68.303},
{n:2,t:"Montagne de la Table",c:"Montagne",x:"Plateau au sommet plat dominant une grande ville portuaire, souvent coiffé d'un nuage appelé la nappe.",e:"Elle domine la ville du Cap et la baie de la Table, en Afrique du Sud ; un téléphérique permet de gagner son sommet, à plus de 1 000 mètres.",p:"Le Cap, Afrique du Sud",a:-33.9628,o:18.4098},
{n:2,t:"Serengeti",c:"Nature",x:"Vaste plaine herbeuse où plus d'un million de gnous migrent chaque année en suivant la pluie.",e:"Ce parc s'étend dans le nord de la Tanzanie, entre le lac Victoria et le cratère du Ngorongoro, et se prolonge au Kenya par la réserve du Masai Mara.",p:"Tanzanie",a:-2.3333,o:34.8333},
{n:2,t:"Borobudur",c:"Monument",x:"Plus grand temple bouddhiste du monde, stupa à neuf terrasses du IXe siècle orné de 2 672 reliefs.",e:"Il se trouve dans le centre de l'île de Java, au nord-ouest de la ville de Yogyakarta, dans une plaine entourée de volcans, dont le Merapi.",p:"Java, Indonésie",a:-7.6079,o:110.2038},
{n:2,t:"Baie d'Hạ Long",c:"Nature",x:"Environ 1 600 îlots calcaires qui émergent d'une baie d'émeraude, selon la légende crachés par un dragon.",e:"Elle s'ouvre sur le golfe du Tonkin, dans la province de Quảng Ninh, au nord-est du Vietnam, à quelques heures de route de Hanoï.",p:"Vietnam",a:20.9101,o:107.1839},
{n:2,t:"Armée de terre cuite",c:"Site archéologique",x:"Plus de 8 000 soldats de terre cuite, tous différents, enterrés pour garder le tombeau d'un premier empereur.",e:"Elle se trouve dans le district de Lintong, à l'est de Xi'an, dans la province du Shaanxi, tout près du mausolée de l'empereur Qin Shi Huang.",p:"Xi'an, Chine",a:34.3847,o:109.2785},
{n:2,t:"Palais du Potala",c:"Monument",x:"Forteresse-palais blanc et rouge de 13 étages, résidence hivernale des dalaï-lamas, à 3 700 mètres d'altitude.",e:"Il domine Lhassa depuis la colline Marpo Ri, au cœur de la région autonome du Tibet, dans le sud-ouest de la Chine.",p:"Lhassa, Tibet",a:29.6578,o:91.1175},
{n:2,t:"Tahiti",c:"Île",x:"Plus grande île d'un archipel du Pacifique sud, où Gauguin s'installa et peignit ses toiles les plus célèbres.",e:"Elle appartient aux îles du Vent, dans l'archipel de la Société ; Papeete, chef-lieu de la Polynésie française, se trouve sur sa côte nord-ouest.",p:"Polynésie française",a:-17.6509,o:-149.426},
{n:2,t:"Abou Simbel",c:"Site archéologique",x:"Temples rupestres de Ramsès II déplacés pierre par pierre dans les années 1960 pour échapper à un barrage.",e:"Les temples se dressent au bord du lac Nasser, dans le sud de l'Égypte, à plus de 200 kilomètres au sud-ouest d'Assouan, près de la frontière soudanaise.",p:"Égypte",a:22.3372,o:31.6258},
{n:2,t:"Vallée des Rois",c:"Site archéologique",x:"Nécropole où reposent des pharaons, dont Toutânkhamon, dont la tombe fut découverte en 1922.",e:"Elle se trouve sur la rive ouest du Nil, face à Louxor, l'antique Thèbes, dans un vallon désertique dominé par le pic pyramidal d'al-Qurn.",p:"Louxor, Égypte",a:25.7402,o:32.6014},
{n:2,t:"Mer Morte",c:"Nature",x:"Lac salé à 430 mètres sous le niveau de la mer, où l'on flotte sans effort, et dont le niveau baisse chaque année.",e:"Elle occupe le fond de la vallée du Jourdain, fleuve qui s'y jette, entre la Jordanie à l'est, Israël et la Cisjordanie à l'ouest.",p:"Israël, Jordanie et Palestine",a:31.5,o:35.5},
{n:2,t:"Mur des Lamentations",c:"Monument",x:"Vestige du soutènement d'un temple antique, lieu de prière majeur du judaïsme.",e:"Il se trouve dans la vieille ville de Jérusalem, au pied de l'esplanade des Mosquées, appelée mont du Temple, où s'élèvent le dôme du Rocher et la mosquée al-Aqsa.",p:"Jérusalem",a:31.7767,o:35.2345},
{n:2,t:"Maldives",c:"Archipel",x:"Archipel de plus de 1 000 îlots coralliens, qui forme le pays le plus plat du monde, à peine au-dessus de la mer.",e:"L'archipel s'étire du nord au sud dans l'océan Indien, au sud-ouest de l'Inde et du Sri Lanka ; sa capitale, Malé, compte parmi les villes les plus densément peuplées du monde.",p:"Océan Indien",a:3.2028,o:73.2207},
{n:2,t:"Mosquée Cheikh Zayed",c:"Lieu religieux",x:"Grande mosquée de marbre blanc inaugurée en 2007, aux 82 coupoles, qui abrite l'un des plus grands tapis noués à la main du monde.",e:"Elle se trouve à Abou Dabi, la capitale des Émirats arabes unis.",p:"Abou Dabi, Émirats arabes unis",a:24.4128,o:54.475},
{n:2,t:"Dôme du Rocher",c:"Lieu religieux",x:"Sanctuaire octogonal à coupole dorée achevé à la fin du VIIe siècle, l'un des plus anciens monuments de l'islam.",e:"Il se dresse sur l'esplanade des Mosquées, dans la vieille ville de Jérusalem.",p:"Jérusalem",a:31.778,o:35.2354},
{n:2,t:"Tours Petronas",c:"Gratte-ciel",x:"Tours jumelles de 452 mètres reliées par une passerelle, plus hautes tours du monde de 1998 à 2004.",e:"Elles se trouvent à Kuala Lumpur, capitale de la Malaisie.",p:"Kuala Lumpur, Malaisie",a:3.1579,o:101.7116},
{n:2,t:"Marina Bay Sands",c:"Architecture",x:"Complexe hôtelier de trois tours de 55 étages coiffées d'un immense toit en forme de navire, avec une piscine à débordement.",e:"Il a été ouvert en 2010 sur un terrain gagné sur la mer, à Singapour.",p:"Singapour",a:1.2834,o:103.8607},
{n:2,t:"Temple d'or",c:"Lieu religieux",x:"Lieu le plus sacré du sikhisme, recouvert d'or et entouré d'un bassin ; sa cuisine sert gratuitement des repas à des dizaines de milliers de personnes chaque jour.",e:"Il se trouve à Amritsar, dans le Pendjab indien.",p:"Amritsar, Inde",a:31.62,o:74.8765},
{n:2,t:"Fushimi Inari-taisha",c:"Lieu religieux",x:"Sanctuaire shinto dédié à la divinité du riz, célèbre pour ses milliers de portiques torii vermillon qui serpentent dans la montagne.",e:"Il se trouve dans le sud de Kyoto, au Japon.",p:"Kyoto, Japon",a:34.9671,o:135.7727},
{n:2,t:"Mosquée de Djenné",c:"Lieu religieux",x:"Plus grand édifice en terre crue du monde, reconstruit en 1907, dont les murs sont recrépis chaque année lors d'une grande fête collective.",e:"Elle se trouve dans une ville du delta intérieur du Niger, au Mali.",p:"Djenné, Mali",a:13.9053,o:-4.5556},
{n:2,t:"Grand Zimbabwe",c:"Site archéologique",x:"Ruines d'une cité de pierres sèches construite entre le XIe et le XVe siècle, capitale d'un royaume qui commerçait avec l'océan Indien.",e:"Le pays a pris son nom en 1980 ; « zimbabwe » signifierait « maisons de pierre » en shona.",p:"Près de Masvingo, Zimbabwe",a:-20.2675,o:30.9338},
{n:2,t:"Île de Gorée",c:"Lieu de mémoire",x:"Petite île face à une capitale africaine, devenue symbole de la traite négrière, avec sa Maison des esclaves et sa « porte du voyage sans retour ».",e:"Elle se trouve au large de Dakar, au Sénégal, et est classée au patrimoine mondial depuis 1978.",p:"Dakar, Sénégal",a:14.6672,o:-17.3983},
{n:2,t:"Persépolis",c:"Site archéologique",x:"Capitale cérémonielle de l'Empire perse achéménide fondée par Darius Ier vers 518 av. J.-C., incendiée par Alexandre le Grand.",e:"Ses ruines se trouvent dans le sud de l'Iran, près de Chiraz.",p:"Près de Chiraz, Iran",a:29.9356,o:52.8916},
{n:2,t:"Palmyre",c:"Site archéologique",x:"Cité caravanière d'une oasis, à son apogée sous la reine Zénobie au IIIe siècle, dont plusieurs temples ont été détruits par l'État islamique en 2015.",e:"Elle se trouve dans le désert de Syrie, à mi-chemin entre la Méditerranée et l'Euphrate.",p:"Tadmor, Syrie",a:34.5503,o:38.269},
{n:2,t:"Teotihuacan",c:"Site archéologique",x:"Immense cité précolombienne dont les pyramides du Soleil et de la Lune bordent une allée des Morts. Les Aztèques la découvrirent déjà en ruines.",e:"Elle se trouve à une cinquantaine de kilomètres au nord-est de Mexico.",p:"Près de Mexico, Mexique",a:19.6925,o:-98.8438},
{n:2,t:"Lignes de Nazca",c:"Site archéologique",x:"Immenses figures tracées dans le sol du désert il y a environ 2 000 ans, dont un colibri et un singe visibles seulement d'avion.",e:"Elles se trouvent dans le désert côtier du sud du Pérou.",p:"Nazca, Pérou",a:-14.739,o:-75.13},
{n:2,t:"Atomium",c:"Monument",x:"Structure d'acier de 102 mètres représentant un cristal de fer agrandi 165 milliards de fois, construite pour l'Exposition universelle de 1958.",e:"Il se trouve sur le plateau du Heysel, à Bruxelles.",p:"Bruxelles, Belgique",a:50.8949,o:4.3415},
{n:2,t:"Pont du Gard",c:"Monument",x:"Pont-aqueduc romain à trois niveaux d'arches, haut de 48 mètres, construit au Ier siècle pour alimenter Nîmes en eau.",e:"Il enjambe le Gardon, près de la commune de Vers-Pont-du-Gard.",p:"Vers-Pont-du-Gard, France",a:43.9475,o:4.5353},
{n:2,t:"Ellis Island",c:"Lieu de mémoire",x:"Îlot par lequel environ 12 millions d'immigrants sont entrés aux États-Unis entre 1892 et 1954.",e:"Il se trouve dans la baie de New York, près de la statue de la Liberté.",p:"Baie de New York, États-Unis",a:40.6995,o:-74.0396},
{n:2,t:"Robben Island",c:"Lieu de mémoire",x:"Île-prison où Nelson Mandela passe 18 de ses 27 années de détention, aujourd'hui classée au patrimoine mondial.",e:"Elle se trouve dans la baie de la Table, au large du Cap.",p:"Au large du Cap, Afrique du Sud",a:-33.8076,o:18.3712},
{n:3,t:"Tombouctou",c:"Ville",x:"Cité caravanière aux manuscrits anciens et aux mosquées de banco, surnommée « la cité des 333 saints ».",e:"Elle se trouve dans le nord du Mali, aux portes du Sahara, près de la grande boucle du fleuve Niger ; sa mosquée Djingareyber date du XIVe siècle.",p:"Mali",a:16.7666,o:-3.0026},
{n:3,t:"Désert d'Atacama",c:"Nature",x:"Désert parmi les plus arides de la planète, où certaines stations n'ont jamais enregistré de pluie.",e:"Il s'étend dans le nord du Chili, entre l'océan Pacifique et la cordillère des Andes ; la petite ville de San Pedro de Atacama sert de base aux visiteurs.",p:"Chili",a:-24.5,o:-69.25},
{n:3,t:"Chaussée des Géants",c:"Nature",x:"Quelque 40 000 colonnes de basalte, selon la légende bâties par un géant pour traverser la mer.",e:"Elle borde la côte nord de l'Irlande du Nord, dans le comté d'Antrim, près de la ville de Bushmills, sur un littoral classé au patrimoine mondial de l'UNESCO.",p:"Antrim, Irlande du Nord",a:55.2408,o:-6.5116},
{n:3,t:"Geirangerfjord",c:"Nature",x:"Fjord étroit de 15 kilomètres bordé de cascades, classé à l'UNESCO, que parcourent de grands paquebots.",e:"Ce bras du réseau du Storfjord se trouve dans le comté de Møre og Romsdal, dans l'ouest de la Norvège ; le village de Geiranger est niché à son extrémité.",p:"Norvège",a:62.1049,o:7.2059},
{n:3,t:"Geysir",c:"Nature",x:"Source d'eau chaude jaillissante qui a donné son nom à tous les phénomènes du même type.",e:"Il se trouve dans le sud-ouest de l'Islande, sur le circuit touristique du Cercle d'or ; son voisin Strokkur jaillit toutes les quelques minutes.",p:"Haukadalur, Islande",a:64.3104,o:-20.3024},
{n:3,t:"Mont Athos",c:"Montagne",x:"Presqu'île montagneuse peuplée de monastères orthodoxes, interdite aux femmes depuis plus de mille ans.",e:"Il occupe la plus orientale des trois presqu'îles de la Chalcidique, dans le nord de la Grèce, au bord de la mer Égée ; c'est une république monastique autonome.",p:"Chalcidique, Grèce",a:40.1575,o:24.3267},
{n:3,t:"Lac Louise",c:"Nature",x:"Lac glaciaire aux eaux turquoise dominé par un glacier, au cœur des Rocheuses.",e:"Il se trouve dans le parc national de Banff, en Alberta, près de la frontière avec la Colombie-Britannique ; le glacier Victoria le domine.",p:"Alberta, Canada",a:51.4254,o:-116.1773},
{n:3,t:"Parc national Kruger",c:"Nature",x:"Réserve de près de 20 000 km² où l'on peut croiser les « Big Five » : lion, léopard, éléphant, buffle, rhinocéros.",e:"Il s'étend dans le nord-est de l'Afrique du Sud, dans les provinces du Limpopo et du Mpumalanga, le long de la frontière avec le Mozambique.",p:"Afrique du Sud",a:-23.9884,o:31.5547},
{n:3,t:"Lac Rose",c:"Nature",x:"Lac salé dont l'eau prend une teinte rose à cause d'une algue, proche de l'arrivée d'un célèbre rallye.",e:"Appelé aussi lac Retba, il se trouve à une trentaine de kilomètres au nord-est de Dakar, séparé de l'océan Atlantique par un cordon de dunes.",p:"Sénégal",a:14.8386,o:-17.2358},
{n:3,t:"Bagan",c:"Site archéologique",x:"Plaine semée de plus de 2 000 temples et pagodes de brique bâtis entre le XIe et le XIIIe siècle.",e:"Le site s'étend sur la rive est de l'Irrawaddy, dans la région de Mandalay, au centre de la Birmanie ; Bagan fut la capitale du premier royaume birman unifié.",p:"Birmanie",a:21.1717,o:94.8585},
{n:3,t:"Île de Komodo",w:"Komodo (île)",c:"Île",x:"Île où vit le plus grand lézard du monde, long de trois mètres et capable de tuer un buffle.",e:"Elle fait partie des petites îles de la Sonde, entre Sumbawa et Florès, et forme avec ses voisines le parc national de Komodo, classé à l'UNESCO.",p:"Indonésie",a:-8.55,o:119.49},
{n:3,t:"Dôme de Genbaku",c:"Histoire",x:"Ruine d'un bâtiment à armature de métal, l'un des rares à avoir tenu debout après l'explosion du 6 août 1945.",e:"Il se dresse au bord de la rivière Motoyasu, à Hiroshima, face au parc du Mémorial de la paix ; il est inscrit au patrimoine mondial de l'UNESCO depuis 1996.",p:"Hiroshima, Japon",a:34.3955,o:132.4536},
{n:3,t:"Sigiriya",c:"Site archéologique",x:"Forteresse du Ve siècle sur un rocher de 200 mètres, dont l'entrée est gardée par des pattes de lion.",e:"Ce rocher se dresse au centre du Sri Lanka, près de Dambulla ; la forteresse fut bâtie par le roi Kassapa Ier et est classée au patrimoine mondial de l'Unesco.",p:"Sri Lanka",a:7.957,o:80.7603},
{n:3,t:"Aoraki / Mont Cook",c:"Montagne",x:"Plus haut sommet de son pays avec 3 724 mètres, nommé d'après un explorateur britannique et sacré pour les Māori.",e:"Il domine les Alpes du Sud, la grande chaîne qui court le long de l'île du Sud de la Nouvelle-Zélande, au cœur du parc national Aoraki/Mount Cook.",p:"Nouvelle-Zélande",a:-43.595,o:170.1418},
{n:3,t:"Fjord de Milford Sound",w:"Milford Sound",c:"Nature",x:"Fjord bordé de parois de 1 200 mètres, l'un des endroits les plus pluvieux de la planète.",e:"Il s'ouvre sur la mer de Tasman, au sud-ouest de l'île du Sud de la Nouvelle-Zélande, dans le parc national de Fiordland, dominé par le pic Mitre.",p:"Nouvelle-Zélande",a:-44.6414,o:167.8974},
{n:3,t:"Lalibela",c:"Site archéologique",x:"Onze églises monolithiques du XIIIe siècle creusées dans le roc, surnommées la « Jérusalem noire ».",e:"Cette ville sainte des hauts plateaux du nord de l'Éthiopie, dans la région Amhara, porte le nom du roi qui fit creuser ses églises ; elle reste un grand lieu de pèlerinage.",p:"Éthiopie",a:12.0319,o:39.0475},
{n:3,t:"Temple du Ciel",c:"Lieu religieux",x:"Ensemble de temples du XVe siècle où l'empereur venait prier pour de bonnes récoltes, avec une salle ronde à triple toit bleu.",e:"Il se trouve dans le sud de Pékin, en Chine.",p:"Pékin, Chine",a:39.8822,o:116.4066},
{n:3,t:"Pagode Shwedagon",c:"Lieu religieux",x:"Stupa doré de près de 100 mètres, le plus sacré de son pays, censé abriter des cheveux du Bouddha.",e:"Elle domine Rangoun, l'ancienne capitale de la Birmanie.",p:"Rangoun, Birmanie",a:16.7983,o:96.1497},
{n:3,t:"Prambanan",c:"Lieu religieux",x:"Grand ensemble de temples hindous du IXe siècle dédiés à la Trimurti, aux tours élancées.",e:"Il se trouve sur l'île de Java, près de Yogyakarta, en Indonésie.",p:"Près de Yogyakarta, Indonésie",a:-7.752,o:110.4915},
{n:3,t:"Mosquée Oqba Ibn Nafi",w:"Grande Mosquée de Kairouan",c:"Lieu religieux",x:"L'une des plus anciennes mosquées d'Afrique du Nord, fondée en 670, dont le minaret carré a servi de modèle à de nombreux autres.",e:"Elle se trouve à Kairouan, quatrième ville sainte de l'islam selon certains, en Tunisie.",p:"Kairouan, Tunisie",a:35.6812,o:10.1036},
{n:3,t:"Place Naghsh-e Jahan",c:"Monument",x:"Immense place royale du début du XVIIe siècle bordée de mosquées à coupoles bleues, d'un palais et d'un bazar, voulue par le shah Abbas Ier.",e:"Elle se trouve à Ispahan, ancienne capitale de la Perse safavide.",p:"Ispahan, Iran",a:32.6575,o:51.6773},
{n:3,t:"Tikal",c:"Site archéologique",x:"Grande cité maya de la période classique, dont les temples-pyramides émergent de la forêt tropicale.",e:"Elle se trouve dans le nord du Guatemala, dans la région du Petén.",p:"Petén, Guatemala",a:17.222,o:-89.6237},
{n:3,t:"Chan Chan",c:"Site archéologique",x:"Plus grande cité en terre crue d'Amérique précolombienne, capitale du royaume Chimú avant sa conquête par les Incas.",e:"Elle se trouve sur la côte nord du Pérou, près de Trujillo.",p:"Près de Trujillo, Pérou",a:-8.1059,o:-79.0747},
{n:3,t:"Cathédrale métropolitaine Nossa Senhora Aparecida",w:"Cathédrale de Brasília",c:"Lieu religieux",x:"Cathédrale moderniste d'Oscar Niemeyer formée de seize colonnes de béton courbes, comme des mains tendues vers le ciel, inaugurée en 1970.",e:"Elle se trouve à Brasília, la capitale construite de toutes pièces à la fin des années 1950.",p:"Brasília, Brésil",a:-15.7983,o:-47.8755},
{n:3,t:"Qutb Minar",c:"Monument",x:"Minaret de briques rouges de 73 mètres commencé vers 1199, l'un des plus hauts minarets en briques du monde.",e:"Il se trouve dans le sud de Delhi, en Inde.",p:"Delhi, Inde",a:28.5245,o:77.1855},
{n:3,t:"Hampi",c:"Site archéologique",x:"Ruines de la capitale de l'empire de Vijayanagara, l'une des plus grandes villes du monde vers 1500, au milieu de rochers de granit.",e:"Elles se trouvent dans l'État du Karnataka, dans le sud de l'Inde.",p:"Karnataka, Inde",a:15.335,o:76.46},
{n:3,t:"Sanctuaire d'Itsukushima",c:"Lieu religieux",x:"Sanctuaire shinto dont le grand portique torii semble flotter sur l'eau à marée haute.",e:"Il se trouve sur l'île de Miyajima, dans la baie d'Hiroshima, au Japon.",p:"Miyajima, Japon",a:34.2959,o:132.3197},
{n:3,t:"Ksar d'Aït-Ben-Haddou",c:"Site historique",x:"Village fortifié en terre crue sur une ancienne route caravanière, décor de nombreux films comme Gladiator et Lawrence d'Arabie.",e:"Il se trouve au pied du Haut Atlas, près de Ouarzazate, au Maroc.",p:"Près de Ouarzazate, Maroc",a:31.047,o:-7.1319},
{n:3,t:"Pyramides de Méroé",c:"Site archéologique",x:"Près de 200 pyramides aux pentes raides, nécropole des rois et reines du royaume de Koush, plus nombreuses que celles d'Égypte.",e:"Elles se trouvent dans le désert, au nord-est de Khartoum, au Soudan.",p:"Méroé, Soudan",a:16.9383,o:33.7489},
{n:3,t:"Leptis Magna",c:"Site archéologique",x:"Cité romaine parmi les mieux conservées, embellie par l'empereur Septime Sévère, qui y était né.",e:"Ses ruines se trouvent au bord de la Méditerranée, près de Khoms, en Libye.",p:"Khoms, Libye",a:32.6386,o:14.2908}
]);

/* ---- Célébrités : acteurs, chanteurs, artistes, écrivains ---- */
ajouter('celeb', 'perso', [
{n:1,t:"Wolfgang Amadeus Mozart",c:"Musique",x:"Compositeur prodige, il se produit devant les cours européennes dès l'âge de six ans et laisse plus de 600 œuvres avant sa mort à 35 ans.",e:"Il est né au 9 de la Getreidegasse, dans la vieille ville de Salzbourg, au bord de la Salzach ; sa maison natale est aujourd'hui un musée.",p:"Salzbourg, Autriche",a:47.8095,o:13.055},
{n:1,t:"Frida Kahlo",c:"Art",x:"Peintre connue pour ses autoportraits, elle a vécu et est morte dans la « maison bleue » d'un quartier de la capitale de son pays, où elle est née.",e:"Coyoacán est un quartier historique du sud de Mexico, aux rues pavées et aux places coloniales ; sa maison natale y est devenue le musée Frida Kahlo en 1958.",p:"Coyoacán, Mexique",a:19.3467,o:-99.1617},
{n:1,k:"vie",t:"Pablo Picasso",c:"Art",q:"atelier où naît le cubisme",x:"Peintre et sculpteur, auteur de Guernica. Arrivé d'Espagne au début du XXe siècle, il s'installe dans un immeuble d'ateliers délabré sur une butte de la capitale française, où il peint Les Demoiselles d'Avignon en 1907.",e:"Le Bateau-Lavoir, sur la butte Montmartre, était un immeuble d'ateliers d'artistes ; Picasso y vit de 1904 à 1909 et y peint le tableau considéré comme l'acte de naissance du cubisme.",p:"Bateau-Lavoir, Paris, France",a:48.8866,o:2.3377},
{n:1,t:"Salvador Dalí",c:"Art",x:"Peintre surréaliste à la moustache relevée, auteur de La Persistance de la mémoire et de ses montres molles.",e:"Il est né à Figueres, en Catalogne, près de la frontière française ; il y a créé son propre Théâtre-Musée, dans la crypte duquel il est enterré.",p:"Figueres, Espagne",a:42.2666,o:2.9617},
{n:1,k:"vie",t:"Ludwig van Beethoven",c:"Musique",q:"ville où il a vécu",x:"Compositeur de la Neuvième Symphonie. Parti de sa Rhénanie natale à 21 ans pour étudier auprès de Haydn, il passe le reste de sa vie dans la capitale des Habsbourg, où il meurt en 1827.",e:"Il vit 35 ans à Vienne, où il déménage des dizaines de fois ; sa tombe se trouve au cimetière central de la ville, près de celles de Schubert et de Brahms.",p:"Vienne, Autriche",a:48.2082,o:16.3738},
{n:1,t:"Édith Piaf",c:"Musique",x:"Chanteuse surnommée « la Môme », interprète de La Vie en rose et de Non, je ne regrette rien.",e:"Elle est née à Paris, dans le quartier populaire de Belleville, dans l'est de la ville ; elle repose tout près, au cimetière du Père-Lachaise.",p:"Paris, France",a:48.8566,o:2.3522},
{n:1,k:"vie",t:"Charlie Chaplin",c:"Cinéma",q:"maison où il passe ses dernières années",x:"Créateur de Charlot, vagabond au chapeau melon. Interdit de retour aux États-Unis en 1952 pour ses supposées sympathies communistes, il s'installe avec sa famille dans une grande demeure au-dessus du lac Léman, où il vit jusqu'à sa mort en 1977.",e:"Le Manoir de Ban, à Corsier-sur-Vevey, est devenu en 2016 le musée Chaplin's World ; l'acteur repose dans le cimetière du village.",p:"Manoir de Ban, Corsier-sur-Vevey, Suisse",a:46.474,o:6.848},
{n:1,t:"Jackie Chan",c:"Cinéma",x:"Acteur et cascadeur, héros de Rush Hour et du film Drunken Master, connu pour réaliser lui-même ses cascades.",e:"Il est né sur l'île de Hong Kong, alors colonie britannique, et y a été formé enfant à l'opéra de Pékin, avec ses acrobaties et ses arts martiaux.",p:"Hong Kong",a:22.3193,o:114.1694},
{n:1,t:"William Shakespeare",c:"Littérature",x:"Dramaturge, auteur de Hamlet, Macbeth et Roméo et Juliette. Il est né dans une petite ville au bord d'une rivière, loin de la capitale.",e:"Stratford-upon-Avon, dans le Warwickshire, au cœur de l'Angleterre, conserve sa maison natale et l'église de la Sainte-Trinité, où il est enterré.",p:"Stratford-upon-Avon, Royaume-Uni",a:52.1917,o:-1.7083},
{n:1,t:"Marilyn Monroe",c:"Cinéma",x:"Actrice et icône des années 1950, née Norma Jeane, star de Certains l'aiment chaud. Elle meurt en 1962 à 36 ans.",e:"Elle est née et morte dans la même ville, la capitale du cinéma américain.",p:"Los Angeles, Californie, États-Unis",a:34.0522,o:-118.2437},
{n:1,t:"John Lennon",c:"Musique",x:"Cofondateur des Beatles, auteur de « Imagine », assassiné devant son immeuble de New York en 1980.",e:"Il est né en 1940 dans le grand port de la Mersey, pendant un bombardement allemand selon la légende familiale.",p:"Liverpool, Royaume-Uni",a:53.4106,o:-2.9779},
{n:1,t:"Beyoncé",c:"Musique",x:"Chanteuse révélée avec le groupe Destiny's Child, devenue l'artiste la plus récompensée de l'histoire des Grammy Awards.",e:"Elle est née et a grandi dans la plus grande ville du Texas.",p:"Houston, Texas, États-Unis",a:29.7633,o:-95.3633},
{n:1,k:"vie",t:"Michel-Ange",c:"Art",q:"lieu où il est enterré",x:"Sculpteur du David et peintre du plafond de la chapelle Sixtine. Mort à Rome à 88 ans en 1564, son corps est ramené en secret dans la grande ville toscane de sa jeunesse et inhumé dans une église franciscaine.",e:"Il repose dans la basilique Santa Croce de Florence, dans un tombeau dessiné par Giorgio Vasari, face à celui de Galilée.",p:"Basilique Santa Croce, Florence, Italie",a:43.7686,o:11.2621},
{n:1,t:"Andy Warhol",c:"Art",x:"Figure du pop art, célèbre pour ses boîtes de soupe Campbell et ses portraits colorés de Marilyn Monroe.",e:"Il est né dans une ville industrielle de Pennsylvanie, où un musée lui est consacré.",p:"Pittsburgh, Pennsylvanie, États-Unis",a:40.4406,o:-79.9959},
{n:1,t:"Molière",c:"Théâtre",x:"Auteur et comédien du XVIIe siècle, il écrit Le Misanthrope, Le Bourgeois gentilhomme et Le Malade imaginaire. Le français est parfois appelé « la langue de Molière ».",e:"Né Jean-Baptiste Poquelin, il est né dans la capitale, fils d'un tapissier du roi.",p:"Paris, France",a:48.8534,o:2.3488},
{n:2,k:"vie",t:"Vincent van Gogh",w:"Vincent van Gogh",c:"Art",q:"lieu de sa mort",x:"Peintre de La Nuit étoilée et des Tournesols. Il passe les soixante-dix derniers jours de sa vie dans un village d'Île-de-France, au nord-ouest de la capitale, où il peint presque un tableau par jour avant de mourir en juillet 1890.",e:"Il meurt à l'auberge Ravoux d'Auvers-sur-Oise, deux jours après s'être blessé par balle ; il repose dans le cimetière du village, aux côtés de son frère Théo.",p:"Auvers-sur-Oise, France",a:49.0715,o:2.1697},
{n:2,k:"vie",t:"Jean-Sébastien Bach",c:"Musique",q:"lieu où il est cantor",x:"Maître du baroque, auteur des Concertos brandebourgeois. Il passe les 27 dernières années de sa vie comme cantor d'un grand sanctuaire luthérien d'une ville commerçante de Saxe, pour lequel il compose une grande partie de ses cantates.",e:"Il est cantor de l'église Saint-Thomas de Leipzig de 1723 à sa mort en 1750 ; ses restes y reposent depuis 1950, devant le chœur.",p:"Église Saint-Thomas, Leipzig, Allemagne",a:51.3394,o:12.3726},
{n:2,t:"Shakira",c:"Musique",x:"Chanteuse de Hips Don't Lie et de Waka Waka, née dans une ville portuaire des Caraïbes.",e:"Barranquilla est un grand port colombien près de l'embouchure du fleuve Magdalena, célèbre pour son carnaval, l'un des plus grands d'Amérique latine.",p:"Barranquilla, Colombie",a:10.9685,o:-74.7813},
{n:2,t:"Rihanna",c:"Musique",x:"Chanteuse de Umbrella et de Diamonds, devenue aussi femme d'affaires. Elle est née sur une île des Caraïbes.",e:"Bridgetown, capitale de la Barbade, se trouve sur la côte sud-ouest de l'île ; en 2021, Rihanna a été proclamée héroïne nationale du pays.",p:"Bridgetown, Barbade",a:13.1132,o:-59.5998},
{n:2,t:"Akira Kurosawa",c:"Cinéma",x:"Réalisateur des Sept Samouraïs et de Rashōmon, qui a fait connaître le cinéma de son pays au monde entier.",e:"Il est né en 1910 à Tokyo, dans l'actuel arrondissement de Shinagawa ; adolescent, il a parcouru la ville dévastée par le grand séisme du Kantō de 1923.",p:"Tokyo, Japon",a:35.6762,o:139.6503},
{n:2,k:"vie",t:"Victor Hugo",c:"Littérature",q:"maison de son exil",x:"Auteur des Misérables. Opposant à Napoléon III, il passe quinze ans sur une île anglo-normande, dans une maison qu'il décore lui-même et où il achève son grand roman, publié en 1862.",e:"Hauteville House, à Saint-Pierre-Port sur l'île de Guernesey, où Hugo vit de 1856 à 1870, appartient aujourd'hui à la Ville de Paris et se visite.",p:"Hauteville House, Saint-Pierre-Port, Guernesey",a:49.4537,o:-2.5368},
{n:2,k:"vie",t:"Jules Verne",c:"Littérature",q:"ville où il vit et est enterré",x:"Romancier de Vingt mille lieues sous les mers. Marié à une jeune veuve de la région, il s'installe au début des années 1870 dans une ville picarde dont il devient conseiller municipal, et y reste jusqu'à sa mort en 1905.",e:"Il vit plus de trente ans à Amiens, où l'on visite sa maison à la tour, et repose au cimetière de la Madeleine sous une sculpture qui le montre sortant de son tombeau.",p:"Amiens, France",a:49.8942,o:2.2958},
{n:2,k:"vie",t:"Coco Chanel",c:"Mode",q:"lieu de sa mort",x:"Couturière de la petite robe noire et du parfum N°5. Elle vit plus de trente ans dans un palace voisin de sa maison de couture de la rue Cambon, et y meurt en janvier 1971.",e:"Elle meurt le 10 janvier 1971 dans sa suite de l'hôtel Ritz, place Vendôme, dont l'arrière donne sur la rue Cambon où se trouve toujours la maison Chanel.",p:"Hôtel Ritz, Paris, France",a:48.8682,o:2.3288},
{n:2,t:"Audrey Hepburn",c:"Cinéma",x:"Actrice de Vacances romaines et Diamants sur canapé, puis ambassadrice de l'UNICEF.",e:"Cette icône britannique est née en Belgique, à Ixelles, une commune de Bruxelles.",p:"Ixelles, Bruxelles, Belgique",a:50.8275,o:4.3697},
{n:2,t:"Omar Sy",c:"Cinéma",x:"Acteur révélé par un duo comique à la télévision, premier acteur noir à recevoir le César du meilleur acteur, en 2012, pour Intouchables.",e:"Il est né et a grandi dans une ville des Yvelines, où ont aussi grandi d'autres humoristes célèbres.",p:"Trappes, France",a:48.7741,o:2.0178},
{n:2,t:"Shah Rukh Khan",c:"Cinéma",x:"Surnommé « le roi de Bollywood », star de plus de quatre-vingts films, dont Devdas et My Name Is Khan.",e:"Il est né dans la capitale de l'Inde avant de faire carrière à Mumbai.",p:"New Delhi, Inde",a:28.6519,o:77.2315},
{n:2,t:"Madonna",c:"Musique",x:"Surnommée « la reine de la pop », elle est l'artiste féminine ayant vendu le plus de disques au monde, avec des tubes comme « Like a Virgin ».",e:"Elle est née dans une petite ville du Michigan, au bord du lac Huron.",p:"Bay City, Michigan, États-Unis",a:43.5945,o:-83.8889},
{n:2,k:"vie",t:"Taylor Swift",c:"Musique",q:"ville où elle lance sa carrière",x:"Autrice-compositrice de l'Eras Tour. À 14 ans, elle convainc ses parents de déménager dans le Tennessee pour se rapprocher de la capitale de la musique country, où elle signe son premier contrat.",e:"Sa famille s'installe à Hendersonville, dans la banlieue de Nashville, surnommée Music City, où elle enregistre ses premiers albums country.",p:"Nashville, Tennessee, États-Unis",a:36.1627,o:-86.7816},
{n:2,t:"Adele",c:"Musique",x:"Chanteuse à la voix soul, dont les albums portent l'âge auquel elle les a écrits (19, 21, 25, 30). Elle a chanté le générique de Skyfall.",e:"Elle est née dans le quartier de Tottenham, au nord de Londres.",p:"Tottenham, Londres, Royaume-Uni",a:51.588,o:-0.072},
{n:2,t:"Youssou N'Dour",c:"Musique",x:"Chanteur à la voix exceptionnelle, roi du mbalax, connu pour son duo « 7 Seconds » avec Neneh Cherry. Il a aussi été ministre.",e:"Il est né dans le quartier de la Médina, dans la capitale de son pays.",p:"Dakar, Sénégal",a:14.6937,o:-17.4441},
{n:2,t:"Louis Armstrong",c:"Musique",x:"Trompettiste et chanteur à la voix rocailleuse, pionnier du jazz, interprète de « What a Wonderful World ».",e:"Il est né dans la ville considérée comme le berceau du jazz.",p:"La Nouvelle-Orléans, Louisiane, États-Unis",a:29.9547,o:-90.0751},
{n:2,t:"Frank Sinatra",c:"Musique",x:"Crooner surnommé « The Voice », interprète de « My Way » et de « New York, New York ».",e:"Il est né dans une ville du New Jersey, sur l'autre rive de l'Hudson face à Manhattan.",p:"Hoboken, New Jersey, États-Unis",a:40.744,o:-74.0324},
{n:2,t:"Stromae",c:"Musique",x:"Auteur-compositeur-interprète révélé par « Alors on danse » en 2009, puis « Papaoutai » et « Formidable ».",e:"Il est né d'une mère belge et d'un père rwandais, à Etterbeek, en région bruxelloise.",p:"Etterbeek, Bruxelles, Belgique",a:50.8333,o:4.3833},
{n:2,t:"Dalida",c:"Musique",x:"Chanteuse aux plus de 500 chansons, dont « Paroles, paroles » et « Gigi l'amoroso », d'origine italienne.",e:"Elle est née en Égypte, dans le quartier de Choubra, et a été élue Miss Égypte en 1954.",p:"Le Caire, Égypte",a:30.0626,o:31.2497},
{n:2,k:"vie",t:"Rembrandt",c:"Art",q:"maison où il a vécu",x:"Peintre du Siècle d'or, maître du clair-obscur, auteur de La Ronde de nuit. Au sommet de sa gloire, il achète une grande maison dans le quartier juif de la plus grande ville des Pays-Bas, qu'il doit revendre après sa faillite.",e:"La maison de la Jodenbreestraat, où il vit et peint de 1639 à 1658, est aujourd'hui le musée Rembrandthuis, à Amsterdam.",p:"Rembrandthuis, Amsterdam, Pays-Bas",a:52.3694,o:4.9012},
{n:2,t:"Gabriel García Márquez",c:"Littérature",x:"Romancier du réalisme magique, auteur de Cent ans de solitude, prix Nobel de littérature 1982.",e:"Il est né dans un village des Caraïbes colombiennes qui a inspiré Macondo.",p:"Aracataca, Colombie",a:10.5917,o:-74.1897},
{n:2,k:"vie",t:"Rabindranath Tagore",c:"Littérature",q:"lieu de l'université qu'il fonde",x:"Poète, premier non-Européen prix Nobel de littérature, en 1913. Il fonde à la campagne, à environ 150 km au nord-ouest de la grande ville du Bengale, une école en plein air devenue l'université Visva-Bharati.",e:"Santiniketan (« demeure de la paix »), dans le Bengale-Occidental, est inscrite au patrimoine mondial de l'UNESCO depuis 2023.",p:"Santiniketan, Inde",a:23.679,o:87.685},
{n:2,t:"Haruki Murakami",c:"Littérature",x:"Romancier de Kafka sur le rivage et 1Q84, traduit dans plus de cinquante langues, souvent cité pour le prix Nobel.",e:"Il est né dans l'ancienne capitale impériale, mais a grandi près de Kobe.",p:"Kyoto, Japon",a:35.0211,o:135.7538},
{n:2,t:"Agatha Christie",c:"Littérature",x:"Romancière la plus vendue de l'histoire, créatrice d'Hercule Poirot et de Miss Marple.",e:"Elle est née dans une station balnéaire du Devon, sur la « Riviera anglaise ».",p:"Torquay, Royaume-Uni",a:50.462,o:-3.5252},
{n:2,k:"vie",t:"J. K. Rowling",c:"Littérature",q:"ville où elle écrit le premier tome",x:"Autrice de Harry Potter. Mère célibataire, elle écrit le premier tome dans les cafés de la capitale écossaise, ville dominée par un château perché sur un ancien volcan.",e:"Elle écrit dans des cafés d'Édimbourg comme l'Elephant House, et y achève en 2007 le dernier tome dans une chambre de l'hôtel Balmoral.",p:"Édimbourg, Royaume-Uni",a:55.9473,o:-3.1917},
{n:2,k:"vie",t:"Ernest Hemingway",c:"Littérature",q:"maison où il a vécu",x:"Romancier de L'adieu aux armes, prix Nobel 1954. Dans les années 1930, il vit dans une maison de pierre sur une île au bout de la Floride, à environ 150 km des côtes de Cuba, où vivent encore les descendants de ses chats à six doigts.",e:"Sa maison de Whitehead Street, à Key West, où il écrit notamment En avoir ou pas, est devenue un musée peuplé de dizaines de chats.",p:"Key West, Floride, États-Unis",a:24.5513,o:-81.8007},
{n:2,t:"Franz Kafka",c:"Littérature",x:"Écrivain de langue allemande, auteur de La Métamorphose et du Procès ; son nom a donné l'adjectif « kafkaïen ».",e:"Il est né, a vécu et a travaillé comme employé d'assurances dans la capitale de la Bohême.",p:"Prague, Tchéquie",a:50.088,o:14.4208},
{n:2,k:"vie",t:"Antoine de Saint-Exupéry",c:"Littérature",q:"escale qu'il dirige dans le désert",x:"Aviateur et auteur du Petit Prince. À la fin des années 1920, il dirige une escale de l'Aéropostale en plein désert, au bord de l'Atlantique face aux îles Canaries, où il écrit son premier roman, Courrier sud.",e:"Cap Juby est l'ancien nom de Tarfaya, dans le sud du Maroc, alors sous protectorat espagnol ; les pilotes de la ligne Toulouse-Dakar y faisaient escale.",p:"Tarfaya (Cap Juby), Maroc",a:27.9392,o:-12.9253},
{n:2,t:"Miguel de Cervantes",c:"Littérature",x:"Ancien soldat blessé à la bataille de Lépante et captif à Alger, il écrit Don Quichotte, considéré comme le premier roman moderne.",e:"Il est né dans une ville universitaire proche de Madrid.",p:"Alcalá de Henares, Espagne",a:40.4821,o:-3.36},
{n:2,k:"vie",t:"Dante Alighieri",c:"Littérature",q:"lieu où il est enterré",x:"Auteur de La Divine Comédie. Banni de sa ville natale en 1302, il erre en exil et meurt en 1321 dans une ville proche de l'Adriatique, célèbre pour ses mosaïques byzantines, qui a toujours refusé de rendre ses restes.",e:"Son tombeau néoclassique se trouve à Ravenne, près de la basilique Saint-François ; une lampe y brûle avec de l'huile offerte chaque année par Florence.",p:"Tombeau de Dante, Ravenne, Italie",a:44.4163,o:12.1986},
{n:2,k:"vie",t:"Johann Wolfgang von Goethe",c:"Littérature",q:"maison où il a vécu",x:"Auteur de Faust et de Werther. Invité à 26 ans par le jeune duc d'une petite capitale de Thuringe, il y passe le reste de sa vie, comme ministre puis directeur du théâtre, aux côtés de Schiller.",e:"Sa maison du Frauenplan, à Weimar, où il vit cinquante ans et meurt en 1832, est aujourd'hui un musée.",p:"Maison de Goethe, Weimar, Allemagne",a:50.9775,o:11.3292},
{n:2,t:"Alexandre Dumas",c:"Littérature",x:"Romancier des Trois Mousquetaires et du Comte de Monte-Cristo, petit-fils d'une esclave de Saint-Domingue.",e:"Il est né dans une petite ville de l'Aisne, connue aussi pour une ordonnance royale de 1539 sur l'usage du français.",p:"Villers-Cotterêts, France",a:49.2533,o:3.0903},
{n:2,t:"Paulo Coelho",c:"Littérature",x:"Romancier de L'Alchimiste, l'un des livres les plus traduits au monde.",e:"Il est né dans l'ancienne capitale de son pays, au bord de la baie de Guanabara.",p:"Rio de Janeiro, Brésil",a:-22.9064,o:-43.1822},
{n:3,k:"vie",t:"Frédéric Chopin",c:"Musique",q:"lieu où repose son cœur",x:"Compositeur romantique mort à Paris en 1849. Selon sa volonté, sa sœur rapporte son cœur, conservé dans un bocal d'alcool, dans la capitale de son pays natal, où il est scellé dans un pilier d'un sanctuaire.",e:"Son cœur repose dans un pilier de l'église Sainte-Croix de Varsovie, tandis que son corps est enterré au cimetière du Père-Lachaise, à Paris.",p:"Église Sainte-Croix, Varsovie, Pologne",a:52.2389,o:21.0174},
{n:3,k:"vie",t:"Jacques Brel",c:"Musique",q:"lieu où il est enterré",x:"Auteur de Ne me quitte pas. Après avoir quitté la scène, il part en voilier autour du monde et s'installe en 1975 sur une île de l'archipel des Marquises, où il est enterré en 1978 près d'un peintre français célèbre.",e:"Il repose au cimetière du Calvaire d'Atuona, sur l'île de Hiva Oa, à quelques mètres de la tombe de Paul Gauguin.",p:"Atuona, Hiva Oa, Polynésie française",a:-9.8,o:-139.03},
{n:3,t:"Michael Jackson",c:"Musique",x:"« Roi de la pop », auteur de Thriller, l'album le plus vendu de l'histoire. Il est né dans une ville industrielle près d'un grand lac.",e:"Gary, dans l'Indiana, a été fondée en 1906 par l'entreprise sidérurgique U.S. Steel sur la rive sud du lac Michigan, non loin de Chicago.",p:"Gary, Indiana, États-Unis",a:41.5934,o:-87.3464},
{n:3,k:"vie",t:"Elvis Presley",c:"Musique",q:"maison où il a vécu",x:"« Roi du rock'n'roll ». Il achète en 1957, à 22 ans, une demeure à colonnes dans une grande ville du Tennessee au bord du Mississippi, où il vit vingt ans et meurt en 1977.",e:"Graceland, à Memphis, est aujourd'hui l'une des maisons les plus visitées des États-Unis ; Elvis est enterré dans son jardin de méditation.",p:"Graceland, Memphis, Tennessee, États-Unis",a:35.0477,o:-90.026},
{n:3,t:"Bob Marley",c:"Musique",x:"Chanteur de reggae, auteur de One Love et de Redemption Song, né dans un village de la campagne d'une île des Caraïbes.",e:"Nine Mile est un village des collines de la paroisse de Saint Ann, au centre de la Jamaïque ; il y repose dans un mausolée près de sa maison natale.",p:"Nine Mile, Jamaïque",a:18.37,o:-77.1},
{n:3,t:"Bob Dylan",c:"Musique",x:"Auteur-compositeur de Like a Rolling Stone, prix Nobel de littérature 2016. Il est né dans une ville au bord du lac Supérieur.",e:"Duluth est un grand port du Minnesota relié à l'Atlantique par la voie maritime du Saint-Laurent ; Dylan a ensuite grandi à Hibbing, ville minière plus au nord.",p:"Duluth, Minnesota, États-Unis",a:46.7867,o:-92.1005},
{n:3,t:"Freddie Mercury",c:"Musique",x:"Chanteur du groupe Queen et de Bohemian Rhapsody. Il est né sur une île de l'océan Indien, qui fait aujourd'hui partie d'un pays d'Afrique de l'Est.",e:"Stone Town est la vieille ville de Zanzibar, en Tanzanie, classée au patrimoine mondial de l'Unesco ; il y est né sous le nom de Farrokh Bulsara.",p:"Stone Town, Zanzibar",a:-6.1659,o:39.2026},
{n:3,k:"vie",t:"Céline Dion",c:"Musique",q:"salle de sa résidence",x:"Chanteuse de My Heart Will Go On. De 2003 à 2019, elle chante plus de mille soirs dans une salle construite pour son spectacle, au cœur d'un casino d'une ville du désert du Nevada.",e:"Le Colosseum du Caesars Palace, à Las Vegas, a été bâti pour son spectacle A New Day ; elle y donne ensuite une seconde résidence de 2011 à 2019.",p:"Caesars Palace, Las Vegas, Nevada, États-Unis",a:36.1162,o:-115.1745},
{n:3,t:"Miriam Makeba",c:"Musique",x:"Chanteuse surnommée « Mama Africa », interprète de Pata Pata. Elle a vécu l'exil pendant plus de trente ans à cause de l'apartheid.",e:"Johannesburg, plus grande ville d'Afrique du Sud, est née en 1886 de la ruée vers l'or du Witwatersrand, sur le haut plateau du Highveld.",p:"Johannesburg, Afrique du Sud",a:-26.2041,o:28.0473},
{n:3,t:"Bruce Lee",c:"Cinéma",x:"Acteur et maître d'arts martiaux, star de Opération Dragon. Il a grandi à Hong Kong mais n'y est pas né.",e:"Il est né en 1940 à l'hôpital chinois du quartier de Chinatown, à San Francisco, pendant une tournée de son père, chanteur d'opéra cantonais.",p:"San Francisco, États-Unis",a:37.7749,o:-122.4194},
{n:3,t:"Léon Tolstoï",w:"Léon Tolstoï",c:"Littérature",x:"Auteur de Guerre et Paix et d'Anna Karénine. Il est né sur le domaine familial où il est aussi enterré.",e:"Iasnaïa Poliana est un domaine situé à une douzaine de kilomètres de Toula, à environ 200 kilomètres au sud de Moscou ; c'est aujourd'hui un musée.",p:"Iasnaïa Poliana, Russie",a:54.0733,o:37.5239},
{n:3,t:"Amitabh Bachchan",c:"Cinéma",x:"Acteur surnommé le « jeune homme en colère » du cinéma hindi des années 1970, star du film Sholay.",e:"Il est né dans la même ville que Nehru, au confluent du Gange et de la Yamuna.",p:"Allahabad (Prayagraj), Inde",a:25.4448,o:81.8432},
{n:3,t:"Gong Li",c:"Cinéma",x:"Actrice révélée par Le Sorgho rouge et Épouses et Concubines de Zhang Yimou.",e:"Elle est née dans une grande ville du nord-est de la Chine, l'ancienne Moukden.",p:"Shenyang, Chine",a:41.7922,o:123.4328},
{n:3,t:"Toshirō Mifune",c:"Cinéma",x:"Acteur fétiche d'Akira Kurosawa, inoubliable dans Les Sept Samouraïs et Rashōmon.",e:"Ce symbole du Japon est né en Chine, dans un port du Shandong où son père était photographe.",p:"Qingdao, Chine",a:36.0649,o:120.3804},
{n:3,t:"Ousmane Sembène",c:"Cinéma",x:"Écrivain et cinéaste surnommé le père du cinéma africain, auteur de La Noire de... et Moolaadé.",e:"Il est né en Casamance, dans le sud de son pays.",p:"Ziguinchor, Sénégal",a:12.568,o:-16.2733},
{n:3,t:"Fela Kuti",c:"Musique",x:"Musicien créateur de l'afrobeat et militant contre la dictature militaire de son pays.",e:"Il est né dans une ville du sud-ouest de son pays, dans une famille de militants ; sa mère était une figure du féminisme.",p:"Abeokuta, Nigeria",a:7.1557,o:3.3451},
{n:3,t:"Cesária Évora",c:"Musique",x:"Chanteuse surnommée « la diva aux pieds nus », reine de la morna, révélée internationalement à plus de 45 ans.",e:"Elle est née dans un port de l'île de São Vicente, dans un archipel de l'Atlantique.",p:"Mindelo, Cap-Vert",a:16.8901,o:-24.9804},
{n:3,t:"Ravi Shankar",c:"Musique",x:"Virtuose du sitar qui a fait connaître la musique classique indienne en Occident, notamment auprès de George Harrison.",e:"Il est né dans la ville sainte au bord du Gange.",p:"Varanasi, Inde",a:25.3167,o:83.0104},
{n:3,t:"Celia Cruz",c:"Musique",x:"Chanteuse surnommée « la reine de la salsa », célèbre pour son cri « ¡Azúcar! ». Exilée après la révolution, elle ne revit jamais son île.",e:"Elle est née dans le quartier de Santos Suárez, dans la capitale de son pays.",p:"La Havane, Cuba",a:23.133,o:-82.383},
{n:3,t:"Ed Sheeran",c:"Musique",x:"Auteur-compositeur à la guitare, interprète de « Shape of You » et « Perfect ».",e:"Il est né dans le Yorkshire de l'Ouest, puis a grandi dans le Suffolk.",p:"Halifax, Royaume-Uni",a:53.7167,o:-1.85},
{n:3,t:"Whitney Houston",c:"Musique",x:"Chanteuse à la voix puissante, interprète de « I Will Always Love You » pour le film Bodyguard.",e:"Elle est née dans la plus grande ville du New Jersey, où sa mère était chanteuse de gospel.",p:"Newark, New Jersey, États-Unis",a:40.7357,o:-74.1724},
{n:3,k:"vie",t:"Diego Rivera",c:"Art",q:"bâtiment couvert de ses fresques",x:"Peintre muraliste, époux de Frida Kahlo. De 1929 à 1935, il couvre l'escalier d'honneur du siège du gouvernement de son pays, sur la grande place de la capitale, d'une fresque géante de l'histoire nationale.",e:"Les fresques du Palais national, sur le Zócalo de Mexico, racontent l'histoire du pays des Aztèques jusqu'à la révolution.",p:"Palais national, Mexico, Mexique",a:19.4324,o:-99.131},
{n:3,t:"Yayoi Kusama",c:"Art",x:"Artiste aux pois et aux salles de miroirs « infinies », l'une des artistes vivantes les plus cotées au monde.",e:"Elle est née dans une ville des Alpes japonaises, où un musée présente ses œuvres.",p:"Matsumoto, Japon",a:36.2333,o:137.9667},
{n:3,k:"vie",t:"Le Corbusier",c:"Architecture",q:"maison emblématique de son œuvre",x:"Architecte de la Cité radieuse, pionnier du béton. En 1931, il achève près d'une ville des Yvelines une maison blanche sur pilotis, manifeste de ses « cinq points de l'architecture moderne ».",e:"La villa Savoye, à Poissy, fait partie des dix-sept œuvres de l'architecte inscrites en 2016 au patrimoine mondial de l'UNESCO.",p:"Villa Savoye, Poissy, France",a:48.9245,o:2.0283},
{n:3,t:"Zaha Hadid",c:"Architecture",x:"Architecte aux formes courbes, première femme lauréate du prix Pritzker, en 2004.",e:"Elle est née dans la capitale de l'Irak, puis a fait carrière à Londres.",p:"Bagdad, Irak",a:33.3406,o:44.4009},
{n:3,k:"vie",t:"Oscar Niemeyer",c:"Architecture",q:"bâtiment emblématique de son œuvre",x:"Architecte aux formes courbes, mort à 104 ans. À la fin des années 1950, il dessine les palais d'une capitale nouvelle bâtie sur le plateau central de son pays, dont le parlement à deux coupoles, l'une à l'endroit, l'autre renversée.",e:"Le Congrès national, à Brasília, réunit le Sénat (sous la coupole) et la Chambre des députés (dans la coupe) au pied de deux tours jumelles de bureaux.",p:"Congrès national, Brasília, Brésil",a:-15.7997,o:-47.8641},
{n:3,k:"vie",t:"Pablo Neruda",c:"Littérature",q:"maison où il est enterré",x:"Poète du Chant général, prix Nobel 1971. Il repose avec son épouse face au Pacifique, devant sa maison remplie d'objets marins, sur la côte, à une centaine de kilomètres à l'ouest de la capitale de son pays.",e:"Sa maison d'Isla Negra, remplie de figures de proue et de coquillages, est devenue un musée ; il en possédait deux autres, à Santiago et à Valparaíso.",p:"Isla Negra, Chili",a:-33.4425,o:-71.6853},
{n:3,t:"Jorge Luis Borges",c:"Littérature",x:"Écrivain des labyrinthes et des bibliothèques infinies, auteur de Fictions et de L'Aleph, devenu aveugle à 55 ans.",e:"Il est né dans la capitale de son pays et mort à Genève.",p:"Buenos Aires, Argentine",a:-34.6131,o:-58.3772},
{n:3,t:"Chinua Achebe",c:"Littérature",x:"Romancier de Tout s'effondre (1958), l'un des livres africains les plus lus au monde.",e:"Il est né dans un village igbo du sud-est de son pays.",p:"Ogidi, Nigeria",a:6.16,o:6.87},
{n:3,t:"Wole Soyinka",c:"Littérature",x:"Dramaturge et poète, premier Africain prix Nobel de littérature, en 1986.",e:"Il est né dans la même ville que le musicien Fela Kuti, qui était son cousin.",p:"Abeokuta, Nigeria",a:7.1557,o:3.3451},
{n:3,t:"Albert Camus",c:"Littérature",x:"Écrivain de L'Étranger et La Peste, prix Nobel de littérature 1957, mort dans un accident de voiture en 1960.",e:"Il est né en Algérie, alors française, dans le village de Mondovi, aujourd'hui Dréan.",p:"Dréan (Mondovi), Algérie",a:36.683,o:7.75},
{n:3,t:"Aimé Césaire",c:"Littérature",x:"Poète du Cahier d'un retour au pays natal, cofondateur du mouvement de la négritude et maire de Fort-de-France pendant 56 ans.",e:"Il est né dans une commune du nord de la Martinique, au pied de la montagne Pelée.",p:"Basse-Pointe, Martinique, France",a:14.87,o:-61.117},
{n:3,t:"Fernando Pessoa",c:"Littérature",x:"Poète qui a écrit sous plus de 70 noms différents, ses « hétéronymes ». Il est l'auteur du Livre de l'intranquillité.",e:"Il est né dans la capitale de son pays mais a grandi à Durban, en Afrique du Sud.",p:"Lisbonne, Portugal",a:38.7251,o:-9.1498},
{n:3,t:"Isabel Allende",c:"Littérature",x:"Romancière de La Maison aux esprits, parente d'un président renversé en 1973.",e:"Elle est née au Pérou, où son père était diplomate.",p:"Lima, Pérou",a:-12.0432,o:-77.0282},
{n:3,t:"Mahmoud Darwich",c:"Littérature",x:"Poète considéré comme la voix de la Palestine, auteur de Pourquoi as-tu laissé le cheval à sa solitude ?",e:"Il est né dans le village d'al-Birwa, en Galilée, détruit en 1948.",p:"Al-Birwa, Galilée (actuel Israël)",a:32.92,o:35.18},
{n:3,t:"Orhan Pamuk",c:"Littérature",x:"Romancier de Mon nom est Rouge et du Musée de l'Innocence, prix Nobel de littérature 2006.",e:"Il est né dans la plus grande ville de son pays, où il a ouvert un vrai musée de l'Innocence.",p:"Istanbul, Turquie",a:41.0138,o:28.9497},
{n:3,t:"Lu Xun",c:"Littérature",x:"Écrivain considéré comme le père de la littérature chinoise moderne, auteur de La Véridique Histoire d'Ah Q.",e:"Il est né dans une ville du Zhejiang réputée pour son vin de riz.",p:"Shaoxing, Chine",a:30.0024,o:120.5786}
]);

/* ---- Sport : sportifs, stades et grands moments ---- */
ajouter('sport', 'perso', [
{n:1,k:"lieu",t:"Stade Maracanã",c:"Stade",x:"Stade de football géant inauguré pour la Coupe du monde 1950, où l'équipe locale perdit la finale devant près de 200 000 spectateurs. Il a aussi accueilli la finale de 2014.",e:"Officiellement nommé stade Jornalista Mário Filho, il se trouve dans la zone nord de Rio de Janeiro, dans le quartier qui lui a donné son nom.",p:"Rio de Janeiro, Brésil",a:-22.9122,o:-43.2303},
{n:1,k:"lieu",t:"Camp Nou",c:"Stade",x:"Plus grand stade d'Europe par sa capacité, d'environ 100 000 places, ouvert en 1957 et domicile d'un club aux couleurs bleu et grenat.",e:"Il se trouve dans le quartier des Corts, dans l'ouest de Barcelone, près de l'avenue Diagonale ; il abrite aussi le musée du FC Barcelone.",p:"Barcelone, Espagne",a:41.3808,o:2.1228},
{n:1,k:"lieu",t:"Stade de Wembley",c:"Stade",x:"Stade national de football de son pays, doté d'une arche d'acier de 133 mètres, reconstruit en 2007 à l'emplacement de l'ancien stade aux deux tours.",e:"Il se trouve dans le borough de Brent, dans le nord-ouest de Londres ; c'est là que se jouent les finales de la Coupe d'Angleterre.",p:"Londres, Royaume-Uni",a:51.5556,o:-0.2794},
{n:1,k:"lieu",t:"Allianz Arena",c:"Stade",x:"Stade à la façade gonflable en coussins translucides qui change de couleur, ouvert en 2005 pour deux clubs de la ville.",e:"Elle se trouve à Fröttmaning, dans le nord de Munich, en Bavière, le long de l'autoroute A9 ; c'est le stade du Bayern Munich.",p:"Munich, Allemagne",a:48.2188,o:11.6248},
{n:1,k:"lieu",t:"Stade de France",c:"Stade",x:"Stade national de 80 000 places inauguré en 1998 pour la Coupe du monde, avec un toit elliptique suspendu. Il a accueilli la finale de cette édition.",e:"Il se trouve dans le quartier de la Plaine, à Saint-Denis, au nord de Paris, au bord du canal Saint-Denis ; il a accueilli l'athlétisme des Jeux de 2024.",p:"Saint-Denis, France",a:48.9244,o:2.36},
{n:1,k:"lieu",t:"Stade Santiago-Bernabéu",c:"Stade",x:"Stade de football à toit rétractable, nommé d'après un ancien président du club blanc qui y joue, dont les joueurs sont surnommés « les Merengues ».",e:"Il se dresse sur le paseo de la Castellana, la grande avenue nord-sud de Madrid, dans le quartier de Chamartín ; c'est le stade du Real Madrid.",p:"Madrid, Espagne",a:40.4531,o:-3.6884},
{n:1,k:"lieu",t:"Old Trafford",c:"Stade",x:"Surnommé « le Théâtre des rêves », plus grand stade de club de football de son pays, domicile d'un club aux maillots rouges.",e:"Il se trouve dans le borough de Trafford, au sud-ouest du centre de Manchester, près du canal maritime ; le terrain de cricket du même nom est tout proche.",p:"Manchester, Royaume-Uni",a:53.4631,o:-2.2914},
{n:1,k:"lieu",t:"Anfield",c:"Stade",x:"Stade de football dont la tribune du fond est célèbre pour son chant « You'll Never Walk Alone », domicile d'un club aux maillots rouges d'un grand port.",e:"Il se trouve dans le quartier d'Anfield, au nord de Liverpool ; seul le parc Stanley le sépare de Goodison Park, le stade historique du club rival d'Everton.",p:"Liverpool, Royaume-Uni",a:53.4308,o:-2.9608},
{n:1,k:"lieu",t:"Stade Giuseppe-Meazza",c:"Stade",x:"Stade de football partagé par deux clubs rivaux, connu pour ses tours cylindriques en béton et nommé d'après un ancien joueur.",e:"Surnommé San Siro, du nom de son quartier, il se trouve dans l'ouest de Milan, en Lombardie ; il accueille les matchs de l'AC Milan et de l'Inter.",p:"Milan, Italie",a:45.4781,o:9.1239},
{n:1,k:"lieu",t:"Stade Azteca",c:"Stade",x:"Premier stade à avoir accueilli deux finales de Coupe du monde (1970 et 1986), théâtre de la « main de Dieu » de Maradona, à plus de 2 200 mètres d'altitude.",e:"Il se trouve dans le sud de Mexico, le long de la grande avenue de la Calzada de Tlalpan, et a été choisi pour le match d'ouverture du Mondial 2026.",p:"Mexico, Mexique",a:19.3031,o:-99.1506},
{n:1,k:"lieu",t:"Stade Roland-Garros",c:"Stade",x:"Stade de tennis où se joue chaque printemps un tournoi du Grand Chelem sur terre battue, nommé d'après un aviateur pionnier.",e:"Il se trouve dans le 16e arrondissement de Paris, porte d'Auteuil, en bordure du bois de Boulogne, à deux pas du Parc des Princes.",p:"Paris, France",a:48.8463,o:2.2494},
{n:1,k:"lieu",t:"Yankee Stadium",c:"Stade",x:"Stade de baseball surnommé « la maison que Ruth a bâtie », domicile d'un club aux rayures bleues, ouvert en 1923 puis reconstruit en 2009.",e:"Il se trouve dans le Bronx, au nord de Manhattan, juste à côté de l'emplacement de l'ancien stade, aujourd'hui transformé en parc.",p:"New York, États-Unis",a:40.8296,o:-73.9264},
{n:1,k:"lieu",t:"Stade Vélodrome",c:"Stade",x:"Stade de football d'un grand port méditerranéen, rénové pour l'Euro 2016, domicile d'un club bleu ciel et blanc.",e:"Il se trouve sur le boulevard Michelet, dans le 8e arrondissement, au sud de Marseille ; c'est le stade de l'Olympique de Marseille, l'OM.",p:"Marseille, France",a:43.2692,o:5.3949},
{n:1,k:"lieu",t:"Parc des Princes",c:"Stade",x:"Stade en béton à l'architecture en anneau ouvert sur la ville, au pied du périphérique, domicile d'un club rouge et bleu.",e:"Il se trouve dans le 16e arrondissement de Paris, à la porte de Saint-Cloud, tout près de Boulogne-Billancourt ; c'est le stade du Paris Saint-Germain.",p:"Paris, France",a:48.8414,o:2.253},
{n:1,k:"lieu",t:"Madison Square Garden",c:"Stade",x:"Salle omnisports surnommée « la Mecque du basket », célèbre pour ses combats de boxe, dont celui de 1971 entre Ali et Frazier.",e:"Il se trouve au cœur de Manhattan, à New York, entre la 7e et la 8e Avenue, juste au-dessus de la gare de Pennsylvania Station.",p:"New York, États-Unis",a:40.7505,o:-73.9935},
{n:1,t:"Lionel Messi",c:"Football",x:"Attaquant gaucher, plusieurs fois Ballon d'or, champion du monde 2022 avec son pays. Il a quitté son pays à 13 ans pour rejoindre un club européen.",e:"Rosario est un grand port fluvial sur le Paraná, dans la province de Santa Fe ; c'est aussi la ville natale de Che Guevara.",p:"Rosario, Argentine",a:-32.9442,o:-60.6505},
{n:1,t:"Cristiano Ronaldo",c:"Football",x:"Attaquant plusieurs fois Ballon d'or et meilleur buteur de l'histoire des sélections. Il est né sur une île de l'Atlantique.",e:"Funchal est la capitale de Madère, archipel portugais au large du Maroc ; depuis 2017, l'aéroport de l'île porte le nom de Cristiano Ronaldo.",p:"Funchal, Madère, Portugal",a:32.6669,o:-16.9241},
{n:1,t:"Zinédine Zidane",c:"Football",x:"Milieu de terrain, champion du monde 1998 après deux buts de la tête en finale. Il a grandi dans un quartier populaire d'une grande ville portuaire.",e:"Il est né à Marseille et a appris le football dans la cité de la Castellane, dans les quartiers nord de la ville.",p:"Marseille, France",a:43.2965,o:5.3698},
{n:1,k:"vie",t:"Michael Jordan",c:"Basket",q:"salle où se dresse sa statue",x:"Basketteur six fois champion NBA avec les Bulls. À l'entrée de la salle où joue son équipe depuis 1994, une statue de bronze le montre en plein vol, au-dessus d'un socle qui proclame qu'il est le meilleur joueur de tous les temps.",e:"Sa statue « The Spirit », dévoilée en 1994, accueille les visiteurs du United Center de Chicago, la salle des Bulls.",p:"United Center, Chicago, États-Unis",a:41.8807,o:-87.6742},
{n:1,t:"Novak Djokovic",c:"Tennis",x:"Joueur de tennis recordman de titres du Grand Chelem chez les hommes, dix fois vainqueur de l'Open d'Australie. Il est né dans la capitale de son pays.",e:"Belgrade, capitale de la Serbie, est située au confluent de la Save et du Danube, sous la forteresse de Kalemegdan.",p:"Belgrade, Serbie",a:44.8178,o:20.4569},
{n:1,t:"Johan Cruyff",c:"Football",x:"Meneur de jeu au numéro 14 et symbole du « football total », triple Ballon d'or, puis entraîneur d'un grand club catalan.",e:"Il est né à Betondorp, dans l'est d'Amsterdam, tout près de l'ancien stade De Meer de l'Ajax ; le grand stade de la ville porte aujourd'hui son nom.",p:"Amsterdam, Pays-Bas",a:52.3403,o:4.9433},
{n:1,t:"Kylian Mbappé",c:"Football",x:"Attaquant champion du monde à 19 ans en 2018, auteur d'un triplé en finale en 2022. Il a grandi en banlieue.",e:"Il est né dans le 19e arrondissement de Paris et a grandi à Bondy, en Seine-Saint-Denis, où il a débuté au club de l'AS Bondy.",p:"Paris, France",a:48.8567,o:2.3522},
{n:1,k:"vie",t:"Pierre de Coubertin",c:"Olympisme",q:"lieu où repose son cœur",x:"Rénovateur des Jeux olympiques modernes et fondateur du CIO. Mort en Suisse en 1937, il est enterré à Lausanne, mais son cœur est déposé selon son souhait dans une stèle sur le site des Jeux antiques, dans le Péloponnèse.",e:"Son cœur repose dans une stèle de marbre à Olympie, près des ruines du sanctuaire où la flamme des Jeux est allumée avant chaque édition.",p:"Olympie, Grèce",a:37.6384,o:21.6297},
{n:1,t:"Zlatan Ibrahimović",c:"Football",x:"Attaquant à la carrière internationale (Ajax, Barcelone, Milan, PSG, Manchester United), connu pour ses buts acrobatiques et sa confiance en lui.",e:"Il a grandi dans le quartier de Rosengård, à Malmö, grand port du sud de la Suède relié à Copenhague par le pont de l'Øresund.",p:"Malmö, Suède",a:55.5783,o:13.0542},
{n:1,t:"Franz Beckenbauer",c:"Football",x:"Défenseur surnommé « Der Kaiser », champion du monde comme joueur (1974) puis comme sélectionneur (1990).",e:"Il est né dans le quartier populaire de Giesing, à Munich, capitale de la Bavière, avant de devenir la légende du Bayern.",p:"Munich, Allemagne",a:48.1375,o:11.575},
{n:1,k:"vie",t:"Björn Borg",c:"Tennis",q:"lieu de ses cinq victoires consécutives",x:"Joueur de tennis suédois au bandeau, célèbre pour son calme. De 1976 à 1980, il remporte cinq fois de suite le plus ancien tournoi du Grand Chelem, sur le gazon de la banlieue sud-ouest de la capitale anglaise.",e:"Il gagne Wimbledon cinq années de suite, dont la finale de 1980 contre John McEnroe, avec un jeu décisif de 34 points resté légendaire.",p:"All England Club, Wimbledon, Londres, Royaume-Uni",a:51.434,o:-0.2143},
{n:1,t:"Sachin Tendulkar",c:"Cricket",x:"Batteur de cricket surnommé « le Dieu du cricket », premier à marquer 100 centuries internationaux, retraité en 2013.",e:"Mumbai, capitale économique de l'Inde, borde la mer d'Arabie ; Tendulkar y a disputé son dernier match international, au stade Wankhede, en 2013.",p:"Bombay (Mumbai), Inde",a:19.0758,o:72.8775},
{n:1,t:"Yao Ming",c:"Basket",x:"Pivot de 2,29 m qui a joué huit saisons en NBA aux Rockets de Houston et fait connaître la ligue dans son pays.",e:"Shanghai, immense métropole à l'embouchure du Yangzi, l'a vu débuter chez les Shanghai Sharks, club dont il est ensuite devenu propriétaire.",p:"Shanghai, Chine",a:31.2325,o:121.4692},
{n:1,t:"Didier Drogba",c:"Football",x:"Attaquant de Chelsea, vainqueur de la Ligue des champions 2012 grâce à un but de la tête et au tir au but décisif.",e:"Abidjan, capitale économique de la Côte d'Ivoire, s'étend autour de la lagune Ébrié, au bord du golfe de Guinée.",p:"Abidjan, Côte d'Ivoire",a:5.3364,o:-4.0267},
{n:1,t:"Roger Milla",c:"Football",x:"Attaquant qui dansait au drapeau de corner en 1990 et devint à 42 ans le plus vieux buteur de l'histoire de la Coupe du monde, en 1994.",e:"Yaoundé, capitale politique du Cameroun, est bâtie sur plusieurs collines du centre-sud du pays, loin de la côte atlantique.",p:"Yaoundé, Cameroun",a:3.8578,o:11.5181},
{n:1,t:"George Weah",c:"Football",x:"Seul Africain Ballon d'or (1995), devenu ensuite président de son pays.",e:"Monrovia, capitale du Liberia, doit son nom au président américain James Monroe ; Weah a grandi dans le bidonville de Clara Town.",p:"Monrovia, Liberia",a:6.3106,o:-10.8047},
{n:1,t:"Martina Navrátilová",c:"Tennis",x:"Joueuse de tennis aux 18 titres du Grand Chelem en simple, qui a quitté son pays natal en 1975 et obtenu la nationalité américaine.",e:"Prague, capitale de la Tchéquie, est traversée par la Vltava ; elle a grandi non loin de là, à Řevnice, où elle a appris le tennis.",p:"Prague, Tchéquie",a:50.0875,o:14.4214},
{n:1,k:"evt",t:"La « Main de Dieu »",w:"Main de Dieu",c:"Football",q:"lieu du but",x:"En quart de finale de la Coupe du monde 1986 contre l'Angleterre, Diego Maradona marque un but de la main, puis un autre après avoir dribblé la moitié de l'équipe adverse.",e:"Le match s'est joué au stade Azteca de Mexico, devant plus de 100 000 spectateurs.",p:"Stade Azteca, Mexico, Mexique",a:19.3029,o:-99.1505},
{n:2,k:"lieu",t:"La Bombonera",c:"Stade",x:"Stade en forme de boîte de chocolats aux tribunes très raides, domicile d'un club bleu et or où a joué Maradona.",e:"Elle se trouve dans le quartier populaire de La Boca, au sud de Buenos Aires, près du port et des maisons colorées du Caminito.",p:"Buenos Aires, Argentine",a:-34.6356,o:-58.3646},
{n:2,k:"lieu",t:"Stade olympique de 1936",w:"Olympiastadion (Berlin)",c:"Stade",x:"Stade monumental inauguré pour les Jeux de 1936, où Jesse Owens remporta quatre médailles d'or. La finale du Mondial 2006 s'y est aussi jouée.",e:"Il se trouve dans le quartier de Westend, dans l'ouest de Berlin ; il accueille chaque année la finale de la Coupe d'Allemagne et les matchs du Hertha.",p:"Berlin, Allemagne",a:52.5147,o:13.2394},
{n:2,k:"lieu",t:"Nid d'oiseau",w:"Stade national de Pékin",c:"Stade",x:"Stade de 91 000 places à l'armature d'acier entrelacée, conçu par deux architectes suisses pour les Jeux olympiques de 2008.",e:"Il se dresse dans le parc olympique, au nord du centre de Pékin, à côté du « Cube d'eau » ; il a aussi accueilli les cérémonies des Jeux d'hiver de 2022.",p:"Pékin, Chine",a:39.9915,o:116.3905},
{n:2,k:"lieu",t:"Stade panathénaïque",c:"Stade",x:"Stade entièrement en marbre blanc, en forme de fer à cheval, où se tinrent les premiers Jeux olympiques modernes en 1896.",e:"Il se trouve au cœur d'Athènes, au pied de la colline d'Ardettos, près du Jardin national ; c'est là qu'arrive chaque année le marathon d'Athènes.",p:"Athènes, Grèce",a:37.9683,o:23.7411},
{n:2,k:"lieu",t:"Soccer City",c:"Stade",x:"Stade en forme de calebasse africaine, qui accueillit l'ouverture et la finale du Mondial 2010.",e:"Appelé aujourd'hui FNB Stadium, il se trouve près de Soweto, au sud-ouest de Johannesburg ; on y a rendu hommage à Nelson Mandela après sa mort en 2013.",p:"Johannesburg, Afrique du Sud",a:-26.2348,o:27.9824},
{n:2,k:"lieu",t:"Stade de Lusail",c:"Stade",x:"Stade doré de 80 000 places, théâtre de la finale du Mondial 2022, remportée aux tirs au but par Messi et ses coéquipiers.",e:"Lusail est une ville nouvelle bâtie sur la côte du golfe Persique, à une vingtaine de kilomètres au nord de Doha, la capitale du Qatar.",p:"Lusail, Qatar",a:25.4209,o:51.4904},
{n:2,k:"lieu",t:"Millennium Stadium",c:"Stade",x:"Stade de rugby à toit rétractable ouvert en 1999, installé en plein centre-ville au bord d'une rivière, dans la capitale d'une nation du Royaume-Uni.",e:"Aujourd'hui appelé Principality Stadium, il est le stade de l'équipe galloise de rugby, au cœur de Cardiff, à deux pas de la gare centrale.",p:"Cardiff, Pays de Galles",a:51.4781,o:-3.1825},
{n:2,k:"lieu",t:"Signal Iduna Park",c:"Stade",x:"Stade qui abrite la plus grande tribune de supporters debout d'Europe, le « Mur jaune », pour environ 25 000 fans.",e:"Ancien Westfalenstadion, il se trouve à Dortmund, dans la Ruhr, en Rhénanie-du-Nord-Westphalie ; c'est le stade du Borussia Dortmund.",p:"Dortmund, Allemagne",a:51.4925,o:7.4517},
{n:2,k:"lieu",t:"Stade olympique de 2012",w:"Stade olympique de Londres",c:"Stade",x:"Stade de 80 000 places bâti pour les Jeux de 2012 dans un ancien quartier industriel, où Usain Bolt a gagné trois médailles d'or.",e:"Il se trouve dans le parc olympique Reine-Élisabeth, à Stratford, dans l'est de Londres ; c'est aujourd'hui le stade du club de football de West Ham.",p:"Londres, Royaume-Uni",a:51.5386,o:-0.0164},
{n:2,k:"vie",t:"Pelé",c:"Football",q:"club de sa carrière",x:"Seul joueur triple champion du monde. Recruté à 15 ans, il joue près de vingt ans pour le club d'un grand port de l'État de São Paulo, dont il porte le maillot blanc jusqu'en 1974, et y est enterré en 2023.",e:"Il marque plus de 600 buts officiels pour le Santos FC, au stade Vila Belmiro, et repose dans un cimetière vertical de la ville.",p:"Vila Belmiro, Santos, Brésil",a:-23.9512,o:-46.3389},
{n:2,k:"vie",t:"Diego Maradona",c:"Football",q:"stade qui porte son nom",x:"Meneur de jeu argentin, auteur de la « main de Dieu ». En 1984, il rejoint le club d'un grand port du sud de l'Italie, qu'il mène à ses deux premiers titres de champion ; le stade du club porte son nom depuis sa mort en 2020.",e:"Le stade San Paolo de Naples, dans le quartier de Fuorigrotta, a été rebaptisé stade Diego-Armando-Maradona quelques jours après sa mort.",p:"Stade Diego-Armando-Maradona, Naples, Italie",a:40.8279,o:14.1931},
{n:2,k:"vie",t:"Ayrton Senna",c:"Sport automobile",q:"circuit de son accident mortel",x:"Pilote brésilien triple champion du monde de Formule 1. Le 1er mai 1994, sa Williams quitte la piste dans le virage de Tamburello, sur une piste d'Émilie-Romagne qui porte le nom d'Enzo Ferrari et de son fils.",e:"Le circuit d'Imola accueillait alors le Grand Prix de Saint-Marin ; la veille, le pilote autrichien Roland Ratzenberger s'y était tué aux essais.",p:"Circuit d'Imola, Italie",a:44.3439,o:11.7167},
{n:2,t:"Muhammad Ali",c:"Boxe",x:"Boxeur, trois fois champion du monde des poids lourds, célèbre pour sa formule « Float like a butterfly, sting like a bee ». Il est né sous un autre nom.",e:"Louisville, plus grande ville du Kentucky, au bord de la rivière Ohio, abrite le Muhammad Ali Center ; son aéroport porte aussi son nom depuis 2019.",p:"Louisville, États-Unis",a:38.2527,o:-85.7585},
{n:2,t:"Usain Bolt",c:"Athlétisme",x:"Sprinteur, détenteur des records du monde du 100 m (9 s 58) et du 200 m (19 s 19), établis à Berlin en 2009.",e:"Il est né à Sherwood Content, un village de la paroisse rurale de Trelawny, dans le nord de la Jamaïque, et a étudié au lycée William Knibb de Falmouth.",p:"Trelawny, Jamaïque",a:18.33,o:-77.75},
{n:2,t:"Rafael Nadal",c:"Tennis",x:"Surnommé « le roi de la terre battue », il a remporté 14 fois Roland-Garros. Il est né sur une île de la Méditerranée.",e:"Manacor, dans l'est de Majorque, aux Baléares, est connue pour ses perles artificielles ; Nadal y a ouvert son académie de tennis en 2016.",p:"Manacor, Majorque, Espagne",a:39.5696,o:3.2085},
{n:2,t:"Roger Federer",c:"Tennis",x:"Vainqueur de 20 tournois du Grand Chelem, dont huit fois Wimbledon. Il est né dans une ville frontalière de trois pays.",e:"Bâle, troisième ville de Suisse, est traversée par le Rhin ; Federer y a remporté dix fois son tournoi en salle, les Swiss Indoors.",p:"Bâle, Suisse",a:47.5596,o:7.5886},
{n:2,t:"Michael Phelps",c:"Natation",x:"Nageur aux 23 médailles d'or olympiques, record absolu, dont huit en une seule édition, à Pékin en 2008.",e:"Il est né à Baltimore, grand port du Maryland sur la baie de Chesapeake, où il s'est entraîné au North Baltimore Aquatic Club avec Bob Bowman.",p:"Baltimore, Maryland, États-Unis",a:39.2864,o:-76.615},
{n:2,t:"Serena Williams",c:"Tennis",x:"Joueuse de tennis aux 23 titres du Grand Chelem en simple, qui a grandi en Californie. Elle est née dans une ville industrielle du Midwest.",e:"Elle est née à Saginaw, dans le Michigan, mais sa famille s'est installée à Compton, près de Los Angeles, quand elle était toute petite.",p:"Saginaw, Michigan, États-Unis",a:43.4199,o:-83.95},
{n:2,t:"Marie-José Pérec",c:"Athlétisme",x:"Sprinteuse, championne olympique du 400 m en 1992 et en 1996, et du 200 m en 1996.",e:"Elle est née à Basse-Terre, chef-lieu de la Guadeloupe, sur la côte sud-ouest de l'île de Basse-Terre, au pied du volcan de la Soufrière.",p:"Basse-Terre, Guadeloupe",a:15.9969,o:-61.7328},
{n:2,k:"vie",t:"Kobe Bryant",c:"Basket",q:"salle où il joue de 1999 à 2016",x:"Arrière surnommé « Black Mamba », cinq fois champion NBA avec les Lakers. À partir de 1999, son équipe joue dans une salle du centre-ville, où il marque 81 points en un match en 2006 et fait ses adieux en 2016 avec 60 points.",e:"La Crypto.com Arena (ex-Staples Center) de Los Angeles a retiré ses deux numéros, le 8 et le 24.",p:"Crypto.com Arena, Los Angeles, États-Unis",a:34.043,o:-118.2673},
{n:2,t:"LeBron James",c:"Basket",x:"Basketteur quadruple champion NBA avec trois équipes différentes, meilleur marqueur de l'histoire de la ligue.",e:"Il est né à Akron, dans l'Ohio, ancienne capitale mondiale du caoutchouc, à une soixantaine de kilomètres de Cleveland, où il a joué pour les Cavaliers.",p:"Akron, Ohio, États-Unis",a:41.0731,o:-81.5178},
{n:2,t:"Simone Biles",c:"Gymnastique",x:"Gymnaste la plus titrée de l'histoire des championnats du monde, dont plusieurs mouvements portent le nom.",e:"Elle est née à Columbus, capitale de l'Ohio, puis a grandi près de Houston, au Texas, chez ses grands-parents qui l'ont adoptée.",p:"Columbus, Ohio, États-Unis",a:39.9622,o:-83.0006},
{n:2,t:"Ronaldinho",c:"Football",x:"Meneur de jeu aux dribbles chantants, Ballon d'or 2005 et champion du monde 2002, au sourire légendaire.",e:"Il est né à Porto Alegre, capitale de l'État du Rio Grande do Sul, dans le sud du Brésil, et a été formé au Grêmio, l'un des grands clubs de la ville.",p:"Porto Alegre, Brésil",a:-30.0328,o:-51.23},
{n:2,k:"vie",t:"Michael Johnson",w:"Michael Johnson (athlète)",c:"Athlétisme",q:"stade de son doublé olympique",x:"Sprinteur aux chaussures dorées. En 1996, il remporte le 200 m et le 400 m, et bat le record du monde du 200 m en 19 s 32, dans le stade des Jeux du centenaire, dans la capitale de la Géorgie américaine.",e:"Le stade olympique d'Atlanta, transformé ensuite en terrain de baseball pour les Braves, sert aujourd'hui au football américain de l'université d'État de Géorgie.",p:"Centennial Olympic Stadium, Atlanta, États-Unis",a:33.7353,o:-84.3894},
{n:2,t:"Laure Manaudou",c:"Natation",x:"Nageuse championne olympique du 400 m nage libre en 2004, à Athènes, puis recordwoman du monde en dos.",e:"Elle est née à Villeurbanne, ville voisine de Lyon, et a grandi dans l'Ain, à Ambérieu-en-Bugey, où elle a fait ses débuts en club.",p:"Villeurbanne, France",a:45.7661,o:4.8794},
{n:2,t:"Babe Ruth",c:"Baseball",x:"Joueur de baseball surnommé « le Bambino », qui a transformé son sport par ses coups de circuit dans les années 1920.",e:"Il est né à Baltimore, dans le Maryland ; sa maison natale, devenue musée, se trouve à quelques rues du stade des Orioles, Camden Yards.",p:"Baltimore, Maryland, États-Unis",a:39.2864,o:-76.615},
{n:2,k:"vie",t:"Dirk Nowitzki",c:"Basket",q:"salle de toute sa carrière NBA",x:"Basketteur allemand au fadeaway, champion NBA en 2011. Il passe 21 saisons dans la même équipe, record de la ligue, dans une grande ville du Texas, devant la salle de laquelle se dresse sa statue.",e:"L'American Airlines Center de Dallas, salle des Mavericks depuis 2001, accueille depuis 2022 une statue de Nowitzki réalisant son tir sur une jambe.",p:"American Airlines Center, Dallas, Texas, États-Unis",a:32.7905,o:-96.8103},
{n:2,t:"Samuel Eto'o",c:"Football",x:"Attaquant quatre fois Ballon d'or africain et triple vainqueur de la Ligue des champions (2006, 2009, 2010).",e:"Il a grandi à Douala, capitale économique et premier port du Cameroun, sur l'estuaire du Wouri, avant de partir très jeune tenter sa chance en Europe.",p:"Douala, Cameroun",a:4.05,o:9.7},
{n:2,t:"Steffi Graf",c:"Tennis",x:"Joueuse de tennis, seule à avoir réalisé le « Grand Chelem doré » en 1988 : les quatre tournois majeurs et les Jeux olympiques la même année.",e:"Elle est née à Mannheim, au confluent du Rhin et du Neckar, dans le Bade-Wurtemberg, et a grandi tout près, à Brühl.",p:"Mannheim, Allemagne",a:49.4878,o:8.4661},
{n:2,t:"Erling Haaland",c:"Football",x:"Attaquant norvégien qui bat dès sa première saison en Angleterre, en 2022-2023, le record de buts sur une saison de Premier League.",e:"Il est né en Angleterre, où son père jouait alors pour le club de la ville.",p:"Leeds, Royaume-Uni",a:53.7965,o:-1.5478},
{n:2,t:"Luka Modrić",c:"Football",x:"Milieu de terrain longtemps au Real Madrid, Ballon d'or 2018 l'année où il mène son pays en finale de la Coupe du monde.",e:"Il a grandi comme réfugié pendant la guerre, dans un hôtel de sa ville natale, sur la côte dalmate.",p:"Zadar, Croatie",a:44.1158,o:15.2251},
{n:2,t:"Eusébio",c:"Football",x:"Attaquant surnommé « la Panthère noire », star du Benfica Lisbonne et meilleur buteur de la Coupe du monde 1966.",e:"Il est né en Afrique, dans la capitale de l'actuel Mozambique, alors appelée Lourenço Marques.",p:"Maputo, Mozambique",a:-25.9655,o:32.5832},
{n:2,k:"vie",t:"Magic Johnson",c:"Basket",q:"salle de ses titres NBA",x:"Meneur de jeu des Lakers, cinq fois champion NBA dans les années 1980. Son équipe joue alors dans une salle ronde aux allures de temple romain, dans une ville de la banlieue sud-ouest de Los Angeles.",e:"Le Forum d'Inglewood, salle des Lakers de 1967 à 1999, accueille aujourd'hui des concerts.",p:"The Forum, Inglewood, Californie, États-Unis",a:33.9583,o:-118.3419},
{n:2,t:"Stephen Curry",c:"Basket",x:"Meneur des Golden State Warriors qui a révolutionné le basket par ses tirs à trois points, quadruple champion NBA.",e:"Il est né dans la même ville de l'Ohio que LeBron James, dans le même hôpital, à quatre ans d'écart.",p:"Akron, Ohio, États-Unis",a:41.0814,o:-81.519},
{n:2,t:"Giannis Antetokounmpo",c:"Basket",x:"Ailier surnommé « Greek Freak », double MVP de la NBA et champion avec les Milwaukee Bucks en 2021.",e:"Fils d'immigrés nigérians, il est né et a grandi dans un quartier de la capitale grecque, où il vendait des lunettes dans la rue.",p:"Athènes, Grèce",a:37.9838,o:23.7278},
{n:2,t:"Victor Wembanyama",c:"Basket",x:"Pivot de plus de 2,20 m choisi en premier lors de la draft NBA 2023 par les San Antonio Spurs, rookie de l'année 2024.",e:"Il est né dans les Yvelines, près de Versailles, et a fait ses débuts au Nanterre 92.",p:"Le Chesnay, France",a:48.8222,o:2.1221},
{n:2,t:"Carlos Alcaraz",c:"Tennis",x:"Joueur de tennis devenu en 2022, à 19 ans, le plus jeune numéro un mondial de l'histoire du classement ATP.",e:"Il est né dans un village de la région de Murcie, où son père dirigeait une académie de tennis.",p:"El Palmar, Murcie, Espagne",a:37.94,o:-1.16},
{n:2,t:"Andre Agassi",c:"Tennis",x:"Joueur de tennis vainqueur des quatre tournois du Grand Chelem, connu pour son style flamboyant et son retour au sommet à la fin des années 1990.",e:"Il est né dans la ville des casinos, dans le désert du Nevada.",p:"Las Vegas, Nevada, États-Unis",a:36.175,o:-115.1372},
{n:2,t:"Max Verstappen",c:"Sport automobile",x:"Pilote néerlandais quadruple champion du monde de Formule 1, devenu à 17 ans le plus jeune pilote à disputer un Grand Prix.",e:"Il est né en Belgique, pays de sa mère, elle-même ancienne pilote de karting.",p:"Hasselt, Belgique",a:50.9311,o:5.3378},
{n:2,t:"Armand Duplantis",c:"Athlétisme",x:"Perchiste suédois, champion olympique en 2021 et 2024, qui ne cesse de battre le record du monde centimètre par centimètre.",e:"Il est né aux États-Unis, dans la ville de son père, ancien perchiste américain.",p:"Lafayette, Louisiane, États-Unis",a:30.2241,o:-92.0198},
{n:2,t:"Mike Tyson",c:"Boxe",x:"Boxeur devenu en 1986, à 20 ans, le plus jeune champion du monde des poids lourds de l'histoire.",e:"Il est né à Brooklyn et a grandi dans le quartier difficile de Brownsville.",p:"Brooklyn, New York, États-Unis",a:40.6782,o:-73.9442},
{n:2,k:"vie",t:"Léon Marchand",c:"Natation",q:"salle de ses titres olympiques",x:"Nageur toulousain. En 2024, il remporte quatre médailles d'or individuelles dans une piscine temporaire installée dans une grande salle de spectacle de la banlieue ouest de la capitale, près du quartier d'affaires.",e:"La natation des Jeux de 2024 se déroule à Paris La Défense Arena, à Nanterre, d'habitude salle de concerts et stade de rugby du Racing 92.",p:"Paris La Défense Arena, Nanterre, France",a:48.8957,o:2.2296},
{n:2,k:"evt",t:"Rumble in the Jungle",c:"Boxe",q:"lieu du combat",x:"Le 30 octobre 1974, Mohamed Ali reprend le titre mondial des poids lourds à George Foreman en le mettant K.-O. au 8e round.",e:"Le combat a eu lieu à Kinshasa, alors au Zaïre, devant environ 60 000 spectateurs.",p:"Kinshasa, République démocratique du Congo",a:-4.3317,o:15.3139},
{n:2,k:"evt",t:"Finale de la Coupe du monde de rugby 1995",c:"Rugby",q:"lieu de la finale",x:"Les Springboks battent les All Blacks en prolongation ; Nelson Mandela remet le trophée au capitaine François Pienaar en portant son maillot.",e:"La finale a eu lieu à l'Ellis Park, à Johannesburg ; elle a inspiré le film Invictus.",p:"Ellis Park, Johannesburg, Afrique du Sud",a:-26.1975,o:28.0606},
{n:2,k:"evt",t:"Poings levés de Tommie Smith et John Carlos",w:"Salut du Black Power aux Jeux olympiques de 1968",c:"Olympisme",q:"lieu de la cérémonie",x:"Après le 200 m des Jeux de 1968, deux sprinteurs américains lèvent un poing ganté de noir sur le podium pour dénoncer le racisme.",e:"La scène s'est déroulée au stade olympique universitaire de Mexico.",p:"Stade olympique universitaire, Mexico, Mexique",a:19.3317,o:-99.1922},
{n:3,k:"lieu",t:"Stade olympique de 1972",w:"Stade olympique de Munich",c:"Stade",x:"Stade au toit de toile tendue suspendu à des mâts, construit pour les Jeux de 1972, marqués par un attentat, et théâtre de la finale du Mondial 1974.",e:"Il se trouve dans l'Olympiapark, au nord de Munich, sur l'ancien aérodrome d'Oberwiesenfeld ; le Bayern y a joué ses matchs jusqu'en 2005.",p:"Munich, Allemagne",a:48.1731,o:11.5467},
{n:3,k:"lieu",t:"Stade olympique de 1960",w:"Stade olympique de Rome",c:"Stade",x:"Stade principal des Jeux de 1960, partagé par deux clubs de football de la ville, dans un grand complexe sportif du bord du fleuve.",e:"Il se trouve au Foro Italico, au pied du Monte Mario, dans le nord de Rome ; l'AS Roma et la Lazio y disputent leurs matchs à domicile.",p:"Rome, Italie",a:41.9339,o:12.4547},
{n:3,k:"lieu",t:"Stade olympique de 1976",w:"Stade olympique de Montréal",c:"Stade",x:"Stade des Jeux de 1976 surnommé « le Big O », surmonté d'une tour inclinée de 165 mètres, la plus haute du monde pour une tour de ce type.",e:"Conçu par l'architecte français Roger Taillibert, il se trouve dans le parc olympique, dans le quartier Hochelaga-Maisonneuve, à l'est de Montréal, au Québec.",p:"Montréal, Canada",a:45.5578,o:-73.5516},
{n:3,k:"lieu",t:"Stade Loujniki",c:"Stade",x:"Stade de la finale de la Coupe du monde 2018, situé dans un méandre d'un fleuve, ancien stade des Jeux de 1980.",e:"Il se trouve dans le district de Khamovniki, au sud-ouest du centre de Moscou, au bord de la Moskova, face aux monts des Moineaux.",p:"Moscou, Russie",a:55.7158,o:37.5536},
{n:3,k:"lieu",t:"MCG",w:"Melbourne Cricket Ground",c:"Stade",x:"Stade de cricket de plus de 90 000 places, ouvert en 1853, stade principal des Jeux olympiques de 1956.",e:"Il se trouve dans le Yarra Park, tout près du centre de Melbourne, dans l'État de Victoria ; il accueille aussi chaque année la grande finale du football australien.",p:"Melbourne, Australie",a:-37.8199,o:144.9834},
{n:3,k:"lieu",t:"Eden Gardens",c:"Stade",x:"Stade de cricket mythique de plus de 60 000 places, l'un des plus grands du monde, ouvert en 1864 au bord d'un fleuve.",e:"Il se trouve à Calcutta (Kolkata), capitale du Bengale-Occidental, près de la rivière Hooghly et du fort William, dans le centre de la ville.",p:"Calcutta, Inde",a:22.5644,o:88.3433},
{n:3,k:"lieu",t:"Twickenham Stadium",c:"Stade",x:"Stade de plus de 80 000 places consacré au rugby à XV, dans la banlieue sud-ouest d'une capitale.",e:"Il se trouve à Twickenham, dans le borough de Richmond upon Thames ; c'est le stade de l'équipe d'Angleterre de rugby et le siège de sa fédération.",p:"Londres, Royaume-Uni",a:51.4561,o:-0.3417},
{n:3,k:"lieu",t:"Ernst-Happel-Stadion",c:"Stade",x:"Stade national de football nommé d'après un entraîneur, qui a accueilli la finale de l'Euro 2008.",e:"Il se trouve dans le parc du Prater, dans le quartier de Leopoldstadt à Vienne, non loin de la célèbre grande roue du parc d'attractions.",p:"Vienne, Autriche",a:48.2072,o:16.4208},
{n:3,k:"lieu",t:"Estadio Centenario",c:"Stade",x:"Stade ouvert en 1930 pour la première finale de Coupe du monde de football, remportée par le pays hôte.",e:"Il se trouve dans le parc Batlle, à Montevideo ; son nom célèbre le centenaire de la première Constitution de l'Uruguay, adoptée en 1830.",p:"Montevideo, Uruguay",a:-34.8944,o:-56.1528},
{n:3,k:"lieu",t:"Stade olympique Atatürk",c:"Stade",x:"Stade de la finale de la Ligue des champions 2005, où un club anglais remonta trois buts de retard contre un club italien avant de gagner aux tirs au but.",e:"Il se trouve dans le district de Başakşehir, sur la rive européenne d'Istanbul, loin à l'ouest du centre historique ; il a aussi accueilli la finale de 2023.",p:"Istanbul, Turquie",a:41.0745,o:28.7657},
{n:3,k:"vie",t:"Tiger Woods",c:"Golf",q:"parcours de son premier titre majeur",x:"Golfeur aux 15 tournois majeurs. En 1997, à 21 ans, il remporte avec douze coups d'avance le Masters, joué chaque printemps sur un parcours privé de Géorgie bordé d'azalées, où il gagne cinq fois la veste verte.",e:"L'Augusta National Golf Club accueille le Masters depuis 1934 ; la victoire de Tiger Woods en 2019, après des années de blessures, est l'un des grands retours de l'histoire du sport.",p:"Augusta National Golf Club, Géorgie, États-Unis",a:33.5027,o:-82.0224},
{n:3,k:"vie",t:"Carl Lewis",c:"Athlétisme",q:"stade de ses quatre titres de 1984",x:"Athlète aux neuf médailles d'or olympiques. En 1984, il égale l'exploit de Jesse Owens avec quatre titres (100 m, 200 m, longueur, relais), devant son public, dans un vieux stade qui avait déjà accueilli les Jeux de 1932.",e:"Le Memorial Coliseum de Los Angeles a accueilli les Jeux de 1932 et de 1984, et doit de nouveau servir en 2028.",p:"Memorial Coliseum, Los Angeles, États-Unis",a:34.0141,o:-118.2879},
{n:3,k:"vie",t:"Nadia Comăneci",c:"Gymnastique",q:"salle de son 10 parfait",x:"Gymnaste roumaine de 14 ans, première à obtenir la note de 10 aux Jeux de 1976. Les épreuves de gymnastique se déroulent dans une salle de hockey sur glace mythique de la plus grande ville du Québec.",e:"Au Forum de Montréal, antre des Canadiens, le tableau d'affichage, prévu pour trois chiffres, affiche « 1.00 » pour sa note parfaite.",p:"Forum de Montréal, Montréal, Canada",a:45.4898,o:-73.586},
{n:3,t:"Jesse Owens",c:"Athlétisme",x:"Athlète noir américain, quadruple médaillé d'or aux Jeux de 1936, organisés sous le régime nazi.",e:"Il est né à Oakville, hameau rural du nord de l'Alabama, dans une famille de métayers qui s'installa ensuite à Cleveland, dans l'Ohio.",p:"Oakville, Alabama, États-Unis",a:34.445,o:-87.161},
{n:3,t:"Michel Platini",c:"Football",x:"Milieu de terrain, triple Ballon d'or (1983-1985), meilleur buteur de l'Euro 1984, puis président de l'UEFA. Il a grandi dans une ville sidérurgique.",e:"Il est né à Jœuf, en Meurthe-et-Moselle, dans la vallée de l'Orne, en Lorraine, avant de débuter sa carrière professionnelle à l'AS Nancy-Lorraine.",p:"Jœuf, France",a:49.2297,o:6.0089},
{n:3,k:"vie",t:"Lewis Hamilton",c:"Sport automobile",q:"circuit de son Grand Prix national",x:"Pilote sept fois champion du monde de Formule 1. Il remporte neuf fois, record absolu, le Grand Prix de son pays, disputé sur un ancien aérodrome militaire à la limite du Northamptonshire et du Buckinghamshire.",e:"Le circuit de Silverstone, ancienne base de la Royal Air Force, a accueilli le tout premier Grand Prix du championnat du monde de Formule 1, en 1950.",p:"Circuit de Silverstone, Royaume-Uni",a:52.0786,o:-1.0169},
{n:3,k:"vie",t:"Michael Schumacher",c:"Sport automobile",q:"siège de l'écurie de ses titres",x:"Pilote sept fois champion du monde de Formule 1. Il remporte cinq titres de suite pour une écurie italienne dont l'usine et la piste d'essais se trouvent dans une petite ville d'Émilie-Romagne, près de Modène.",e:"Maranello abrite depuis 1943 l'usine Ferrari, sa piste privée de Fiorano et un musée de la marque.",p:"Maranello, Italie",a:44.532,o:10.864},
{n:3,t:"Eddy Merckx",c:"Cyclisme",x:"Cycliste surnommé « le Cannibale », cinq victoires au Tour de France et 34 victoires d'étapes.",e:"Il est né à Meensel-Kiezegem, village du Brabant flamand, mais a grandi à Woluwe-Saint-Pierre, dans la région de Bruxelles-Capitale.",p:"Meensel-Kiezegem, Belgique",a:50.8961,o:4.9244},
{n:3,t:"Bernard Hinault",c:"Cyclisme",x:"Cycliste surnommé « le Blaireau », cinq victoires au Tour de France, dernier Français à l'avoir gagné, en 1985.",e:"Il est né à Yffiniac, dans les Côtes-d'Armor, au fond de la baie de Saint-Brieuc, sur la côte nord de la Bretagne.",p:"Yffiniac, France",a:48.485,o:-2.6775},
{n:3,t:"Teddy Riner",c:"Judo",x:"Judoka multiple champion olympique et recordman de titres de champion du monde, chez les plus de 100 kg.",e:"Il est né aux Abymes, commune la plus peuplée de la Guadeloupe, sur Grande-Terre, qui accueille l'aéroport Pôle Caraïbes ; il a grandi à Paris.",p:"Les Abymes, Guadeloupe",a:16.2706,o:-61.5047},
{n:3,t:"Tony Parker",c:"Basket",x:"Meneur de jeu quatre fois champion NBA avec les Spurs, MVP des Finales 2007, devenu ensuite président d'un club.",e:"Il est né à Bruges, ville flamande célèbre pour ses canaux, d'un père basketteur américain et d'une mère néerlandaise, avant de grandir en Normandie.",p:"Bruges, Belgique",a:51.2089,o:3.2242},
{n:3,t:"Haile Gebrselassie",c:"Athlétisme",x:"Coureur de fond, deux fois champion olympique du 10 000 m, qui a battu plus de vingt records du monde.",e:"Il est né près d'Assella, dans la région Oromia, sur les hauts plateaux éthiopiens à plus de 2 000 mètres d'altitude, au sud-est d'Addis-Abeba.",p:"Assella, Éthiopie",a:7.95,o:39.1167},
{n:3,t:"Eliud Kipchoge",c:"Athlétisme",x:"Marathonien double champion olympique, premier à courir un marathon en moins de deux heures (1 h 59 min 40 s) en 2019, lors d'un essai hors compétition.",e:"Il est né à Kapsisiywa, dans le comté de Nandi, sur les hautes terres de l'ouest du Kenya, terre de nombreux coureurs de fond.",p:"Kapsisiywa, Kenya",a:0.3275,o:35.0544},
{n:3,k:"vie",t:"Jean-Claude Killy",c:"Ski",q:"station où il a grandi",x:"Skieur triple champion olympique en 1968. Né en région parisienne, il grandit dans une station de Haute-Tarentaise, en Savoie, qui accueille chaque hiver des épreuves de Coupe du monde, le Critérium de la première neige.",e:"Il apprend à skier à Val-d'Isère, qui accueille les épreuves de descente hommes des Jeux d'Albertville en 1992, dont il copréside le comité d'organisation.",p:"Val-d'Isère, France",a:45.4481,o:6.98},
{n:3,t:"Yannick Noah",c:"Tennis",x:"Joueur de tennis vainqueur de Roland-Garros en 1983, puis capitaine de l'équipe de France de Coupe Davis. Il a passé son enfance en Afrique, où vivait son père footballeur.",e:"Il est né à Sedan, dans les Ardennes, où son père jouait au CS Sedan ; la ville est connue pour son château fort, l'un des plus vastes d'Europe.",p:"Sedan, France",a:49.7019,o:4.9403},
{n:3,t:"Ronaldo",w:"Ronaldo (football)",c:"Football",x:"Attaquant surnommé « le Phénomène », double champion du monde (1994 et 2002) avec son pays, longtemps meilleur buteur de l'histoire de la Coupe du monde.",e:"Itaguaí est une ville de l'État de Rio de Janeiro, au bord de la baie de Sepetiba ; il a grandi à Bento Ribeiro, quartier de la zone nord de Rio.",p:"Itaguaí, Brésil",a:-22.8519,o:-43.775},
{n:3,t:"Neymar",c:"Football",x:"Attaquant transféré pour 222 millions d'euros en 2017 au PSG, champion olympique en 2016 avec son pays.",e:"Il est né à Mogi das Cruzes, dans l'agglomération de São Paulo, puis a grandi près de Santos, le club où il a été révélé.",p:"Mogi das Cruzes, Brésil",a:-23.5228,o:-46.1931},
{n:3,t:"Mohamed Salah",c:"Football",x:"Attaquant de Liverpool, plusieurs fois meilleur buteur de Premier League, très populaire dans son pays natal, un village du nord.",e:"Nagrig est un village du gouvernorat de Gharbiya, au cœur du delta du Nil, à une centaine de kilomètres au nord-ouest du Caire ; Salah y finance de nombreux projets.",p:"Nagrig, Égypte",a:30.9725,o:30.8669},
{n:3,t:"Sadio Mané",c:"Football",x:"Attaquant vainqueur de la Ligue des champions 2019 avec Liverpool et de la CAN 2022 avec son pays. Il a grandi dans un village.",e:"Bambali est un village de la région de Sédhiou, en Casamance, dans le sud du Sénégal ; Mané y a financé la construction d'un hôpital et d'une école.",p:"Bambali, Sénégal",a:12.6042,o:-15.6614},
{n:3,t:"Sébastien Loeb",c:"Sport automobile",x:"Pilote de rallye neuf fois champion du monde consécutif entre 2004 et 2012.",e:"Il est né à Haguenau, dans le Bas-Rhin, au nord de Strasbourg, et a grandi tout près, à Oberhoffen-sur-Moder, en Alsace.",p:"Haguenau, France",a:48.8167,o:7.7878},
{n:3,t:"Wayne Gretzky",c:"Hockey sur glace",x:"Joueur de hockey sur glace surnommé « La Merveille », meilleur marqueur de l'histoire de la LNH avec le numéro 99.",e:"Il est né à Brantford, en Ontario, surnommée « la ville du téléphone » car Alexander Graham Bell y conçut son invention en 1874.",p:"Brantford, Ontario, Canada",a:43.1408,o:-80.2631},
{n:3,t:"Jacques Anquetil",c:"Cyclisme",x:"Cycliste premier vainqueur de cinq Tours de France (1957, 1961-1964), spécialiste du contre-la-montre.",e:"Il est né à Mont-Saint-Aignan, commune perchée sur les hauteurs au nord de Rouen, en Seine-Maritime, et a grandi dans la campagne normande.",p:"Mont-Saint-Aignan, France",a:49.4625,o:1.0872},
{n:3,k:"vie",t:"Cathy Freeman",c:"Athlétisme",q:"stade de sa victoire olympique",x:"Athlète aborigène, elle allume la vasque des Jeux de 2000 puis remporte le 400 m dix jours plus tard, devant plus de 110 000 spectateurs, dans le grand stade de la plus grande ville de son pays.",e:"Le stade olympique de Sydney, à Homebush Bay, a depuis été réduit à environ 80 000 places.",p:"Stadium Australia, Sydney, Australie",a:-33.8474,o:151.0634},
{n:3,t:"Son Heung-min",c:"Football",x:"Attaquant longtemps à Tottenham, premier Asiatique meilleur buteur de Premier League en 2022 et vainqueur de la Ligue Europa en 2025.",e:"Il est né dans une ville de la province de Gangwon, au nord-est de Séoul.",p:"Chuncheon, Corée du Sud",a:37.8747,o:127.7342},
{n:3,t:"Marta",w:"Marta (football)",c:"Football",x:"Attaquante brésilienne six fois élue meilleure joueuse du monde, meilleure buteuse de l'histoire des Coupes du monde, hommes et femmes confondus.",e:"Elle est née dans une petite ville de l'Alagoas, dans le Nordeste.",p:"Dois Riachos, Alagoas, Brésil",a:-9.39,o:-37.1},
{n:3,t:"Megan Rapinoe",c:"Football",x:"Milieu offensive américaine, double championne du monde, Ballon d'or et meilleure joueuse de la Coupe du monde 2019.",e:"Elle est née dans une ville du nord de la Californie.",p:"Redding, Californie, États-Unis",a:40.5865,o:-122.3917},
{n:3,t:"George Best",c:"Football",x:"Ailier de Manchester United, Ballon d'or 1968, considéré comme l'un des plus grands dribbleurs de l'histoire.",e:"Il est né en Irlande du Nord ; l'aéroport de sa ville natale porte son nom.",p:"Belfast, Royaume-Uni",a:54.5968,o:-5.9254},
{n:3,t:"Ferenc Puskás",c:"Football",x:"Attaquant de la grande équipe nationale des années 1950 puis du Real Madrid ; un prix de la FIFA pour le plus beau but porte son nom.",e:"Il est né dans la capitale de son pays, dont le stade national porte son nom.",p:"Budapest, Hongrie",a:47.4984,o:19.0404},
{n:3,t:"Lev Yachine",c:"Football",x:"Gardien surnommé « l'Araignée noire », seul gardien de but lauréat du Ballon d'or, en 1963.",e:"Il est né, a joué toute sa carrière au Dynamo et est mort dans la capitale de son pays.",p:"Moscou, Russie",a:55.752,o:37.6178},
{n:3,t:"Alfredo Di Stéfano",c:"Football",x:"Attaquant vedette du Real Madrid qui remporte les cinq premières Coupes des clubs champions européens, de 1956 à 1960.",e:"Il est né dans le quartier de Barracas, dans une capitale d'Amérique du Sud.",p:"Buenos Aires, Argentine",a:-34.6131,o:-58.3772},
{n:3,t:"Jay-Jay Okocha",c:"Football",x:"Milieu de terrain réputé pour ses gestes techniques, passé par le PSG et Bolton, champion olympique en 1996.",e:"Il est né dans une grande ville du sud-est de son pays.",p:"Enugu, Nigeria",a:6.4413,o:7.4988},
{n:3,t:"Hakeem Olajuwon",c:"Basket",x:"Pivot des Houston Rockets, double champion NBA en 1994 et 1995, célèbre pour son « Dream Shake ».",e:"Il est né dans la plus grande ville de son pays, où il jouait au handball et au football avant le basket.",p:"Lagos, Nigeria",a:6.4541,o:3.3947},
{n:3,k:"vie",t:"Arthur Ashe",c:"Tennis",q:"stade qui porte son nom",x:"Premier joueur noir vainqueur de l'US Open (1968) et de Wimbledon (1975), militant contre l'apartheid. Le plus grand stade de tennis du monde, ouvert en 1997 dans un parc du Queens, porte son nom.",e:"Le stade Arthur-Ashe se trouve dans le parc de Flushing Meadows, à New York, sur le site de deux Expositions universelles, en 1939 et 1964.",p:"Flushing Meadows, New York, États-Unis",a:40.75,o:-73.8467},
{n:3,t:"Li Na",w:"Li Na (tennis)",c:"Tennis",x:"Première joueuse asiatique à remporter un tournoi du Grand Chelem en simple, à Roland-Garros en 2011.",e:"Elle est née dans une grande ville au bord du Yangzi, dans le Hubei.",p:"Wuhan, Chine",a:30.5833,o:114.2667},
{n:3,k:"vie",t:"Rod Laver",c:"Tennis",q:"court qui porte son nom",x:"Seul joueur à avoir réussi deux fois le Grand Chelem calendaire, en 1962 et 1969. Le court central de l'Open d'Australie, au cœur d'un complexe de tennis au bord de la Yarra, porte son nom depuis 2000.",e:"La Rod Laver Arena, à Melbourne Park, possède un toit rétractable ; Laver est né à Rockhampton, dans le Queensland.",p:"Rod Laver Arena, Melbourne, Australie",a:-37.8216,o:144.9785},
{n:3,t:"Juan Manuel Fangio",c:"Sport automobile",x:"Cinq fois champion du monde de Formule 1 dans les années 1950, avec quatre écuries différentes.",e:"Il est né dans une petite ville de la province de Buenos Aires, où un musée de l'automobile porte son nom.",p:"Balcarce, Argentine",a:-37.8464,o:-58.2555},
{n:3,k:"vie",t:"Niki Lauda",c:"Sport automobile",q:"circuit de son accident",x:"Pilote autrichien triple champion du monde de Formule 1. Le 1er août 1976, sa Ferrari s'embrase lors du Grand Prix d'Allemagne, sur une boucle de 22 km du massif de l'Eifel surnommée « l'Enfer vert ».",e:"Sorti des flammes par d'autres pilotes, il revient en course six semaines plus tard ; la Formule 1 ne retourne plus jamais sur la Nordschleife du Nürburgring, jugée trop dangereuse.",p:"Nürburgring, Allemagne",a:50.3356,o:6.9475},
{n:3,t:"Alain Prost",c:"Sport automobile",x:"Pilote surnommé « le Professeur », quatre fois champion du monde de Formule 1, rival légendaire d'Ayrton Senna.",e:"Il est né dans la Loire, près de Saint-Étienne.",p:"Lorette, France",a:45.51,o:4.58},
{n:3,t:"Paavo Nurmi",c:"Athlétisme",x:"Coureur de fond surnommé le « Finlandais volant », neuf fois champion olympique dans les années 1920.",e:"Il est né dans l'ancienne capitale de son pays, sur la côte sud-ouest.",p:"Turku, Finlande",a:60.4515,o:22.2687},
{n:3,t:"Sergueï Bubka",c:"Athlétisme",x:"Perchiste qui a battu 35 fois le record du monde et a été le premier à franchir six mètres, en 1985.",e:"Il est né dans une ville industrielle du Donbass, dans l'est de l'Ukraine actuelle.",p:"Louhansk, Ukraine",a:48.5681,o:39.3055},
{n:3,k:"vie",t:"Florence Griffith-Joyner",c:"Athlétisme",q:"ville de son record du 100 m",x:"Sprinteuse surnommée « Flo-Jo ». Le 16 juillet 1988, lors des sélections américaines pour les Jeux de Séoul, elle court le 100 m en 10 s 49 dans la capitale de l'Indiana, un record du monde jamais battu.",e:"Son record est établi à Indianapolis, ville surtout connue pour sa course automobile des 500 miles ; elle bat ensuite celui du 200 m aux Jeux de Séoul.",p:"Indianapolis, Indiana, États-Unis",a:39.7684,o:-86.1581},
{n:3,t:"Shelly-Ann Fraser-Pryce",c:"Athlétisme",x:"Sprinteuse surnommée « Pocket Rocket », double championne olympique du 100 m (2008, 2012) et cinq fois championne du monde de la distance.",e:"Elle a grandi dans le quartier de Waterhouse, dans la capitale de son île.",p:"Kingston, Jamaïque",a:17.997,o:-76.7936},
{n:3,t:"Manny Pacquiao",c:"Boxe",x:"Seul boxeur champion du monde dans huit catégories de poids différentes, devenu sénateur de son pays.",e:"Il est né dans une petite ville de Mindanao, dans une famille très pauvre.",p:"Kibawe, Bukidnon, Philippines",a:7.57,o:124.99},
{n:3,t:"Tadej Pogačar",c:"Cyclisme",x:"Coureur slovène plusieurs fois vainqueur du Tour de France, dont le premier en 2020 à 21 ans.",e:"Il est né dans un village de Haute-Carniole, au nord de Ljubljana.",p:"Komenda, Slovénie",a:46.205,o:14.54},
{n:3,t:"Fausto Coppi",c:"Cyclisme",x:"Surnommé le « Campionissimo », premier coureur à réaliser le doublé Giro-Tour de France la même année, en 1949.",e:"Il est né dans un petit village du Piémont, rebaptisé depuis Castellania Coppi.",p:"Castellania, Italie",a:44.798,o:8.931},
{n:3,t:"Severiano Ballesteros",c:"Golf",x:"Golfeur vainqueur de cinq tournois majeurs, dont trois British Open, figure de la Ryder Cup européenne.",e:"Il est né dans un village de Cantabrie, au bord de la baie de Santander, où il a appris le golf sur la plage.",p:"Pedreña, Espagne",a:43.446,o:-3.752},
{n:3,t:"Brian Lara",c:"Cricket",x:"Batteur auteur du record de 400 points dans une manche de test-match, en 2004.",e:"Il est né dans un village de l'île de Trinité, dans les Antilles.",p:"Santa Cruz, Trinité-et-Tobago",a:10.71,o:-61.46},
{n:3,t:"Don Bradman",c:"Cricket",x:"Batteur à la moyenne de 99,94 en test-match, considéré comme le plus grand joueur de cricket de l'histoire.",e:"Il est né dans une petite ville de Nouvelle-Galles du Sud.",p:"Cootamundra, Australie",a:-34.6411,o:148.0284},
{n:3,t:"Jonah Lomu",c:"Rugby",x:"Ailier des All Blacks qui écrase les défenses lors de la Coupe du monde 1995, devenu la première star mondiale du rugby.",e:"Il est né dans la plus grande ville de son pays, de parents tongiens.",p:"Auckland, Nouvelle-Zélande",a:-36.8485,o:174.7635},
{n:3,t:"Antoine Dupont",c:"Rugby",x:"Demi de mêlée du Stade toulousain, élu meilleur joueur du monde en 2021, puis champion olympique de rugby à sept en 2024.",e:"Il est né dans une ville des Hautes-Pyrénées, sur le plateau du même nom.",p:"Lannemezan, France",a:43.1253,o:0.3842},
{n:3,t:"Magnus Carlsen",c:"Échecs",x:"Champion du monde d'échecs de 2013 à 2023, détenteur du classement Elo le plus élevé de l'histoire.",e:"Il est né dans une ville côtière au sud d'Oslo.",p:"Tønsberg, Norvège",a:59.2675,o:10.4076},
{n:3,t:"Garry Kasparov",c:"Échecs",x:"Champion du monde d'échecs de 1985 à 2000, célèbre pour ses matchs contre l'ordinateur Deep Blue.",e:"Il est né dans la capitale de l'Azerbaïdjan, au bord de la Caspienne.",p:"Bakou, Azerbaïdjan",a:40.3777,o:49.892},
{n:3,k:"evt",t:"Miracle sur glace",c:"Hockey sur glace",q:"lieu du match",x:"Aux Jeux d'hiver de 1980, une équipe d'étudiants américains bat la grande équipe soviétique en pleine guerre froide.",e:"Le match a eu lieu à Lake Placid, dans l'État de New York, qui avait déjà accueilli les Jeux en 1932.",p:"Lake Placid, New York, États-Unis",a:44.2795,o:-73.9799},
{n:3,k:"evt",t:"Tour de France 1903",c:"Cyclisme",q:"lieu du départ",x:"Le 1er juillet 1903, 60 coureurs prennent le départ de la première course cycliste par étapes autour d'un pays, imaginée par un journal sportif.",e:"Le départ a été donné devant l'auberge du Réveil-Matin, à Montgeron, au sud de Paris.",p:"Montgeron, France",a:48.7036,o:2.4597},
{n:3,k:"evt",t:"Premier match international de football",w:"Écosse-Angleterre (1872)",c:"Football",q:"lieu du match",x:"Le 30 novembre 1872, deux nations britanniques disputent le premier match officiel entre équipes nationales. Il se termine sur un score nul et vierge.",e:"Le match a eu lieu à Hamilton Crescent, un terrain de cricket de Partick, à Glasgow.",p:"Partick, Glasgow, Royaume-Uni",a:55.8717,o:-4.3069}
]);

/* ---- Politique : présidents, Premiers ministres, chefs d'État, militants ---- */
ajouter('politique', 'perso', [
{n:1,t:"Simón Bolívar",c:"Politique",x:"Surnommé le Libertador, il a mené l'indépendance de plusieurs pays d'Amérique du Sud. L'un d'eux porte son nom.",e:"Il est né à Caracas, dans une maison du centre historique devenue musée ; ses restes reposent au Panthéon national de la ville.",p:"Caracas, Venezuela",a:10.4806,o:-66.9036},
{n:1,k:"vie",t:"Abraham Lincoln",c:"Président",q:"lieu de son assassinat",x:"16e président des États-Unis, vainqueur de la guerre de Sécession. Le 14 avril 1865, cinq jours après la reddition du Sud, il est abattu par un acteur pendant une comédie, dans un théâtre de la capitale fédérale.",e:"Lincoln meurt le lendemain matin dans une maison située en face du Ford's Theatre, qui fonctionne toujours comme théâtre et musée.",p:"Ford's Theatre, Washington, États-Unis",a:38.8967,o:-77.0257},
{n:1,k:"vie",t:"George Washington",c:"Président",q:"domaine où il a vécu",x:"Premier président des États-Unis. Planteur de Virginie, il vit et meurt en 1799 dans son domaine au bord du Potomac, à une vingtaine de kilomètres de la future capitale qui porte son nom.",e:"Mount Vernon, sa plantation où travaillaient plus de 300 esclaves, abrite aussi sa tombe.",p:"Mount Vernon, Virginie, États-Unis",a:38.7293,o:-77.1074},
{n:1,k:"vie",t:"John F. Kennedy",c:"Président",q:"lieu où il est enterré",x:"35e président des États-Unis, assassiné en novembre 1963. Il repose sous une flamme éternelle allumée par sa veuve, dans une nécropole militaire qui fait face à la capitale fédérale, de l'autre côté du Potomac.",e:"Il est enterré au cimetière national d'Arlington, en Virginie, sur une colline tournée vers le Lincoln Memorial ; ses frères Robert et Ted reposent près de lui.",p:"Cimetière national d'Arlington, Virginie, États-Unis",a:38.8818,o:-77.0716},
{n:1,t:"Winston Churchill",c:"Premier ministre",x:"Premier ministre britannique pendant la Seconde Guerre mondiale, célèbre pour ses discours et son signe de la victoire. Prix Nobel de littérature en 1953.",e:"Il est né au palais de Blenheim, demeure de sa famille, les ducs de Marlborough.",p:"Palais de Blenheim, Woodstock, Royaume-Uni",a:51.8413,o:-1.3611},
{n:1,k:"vie",t:"Lénine",w:"Lénine",c:"Révolutionnaire",q:"lieu où il repose",x:"Chef des bolcheviks et fondateur de l'État soviétique, mort en 1924. Son corps embaumé est exposé depuis un siècle dans un tombeau de granit, au pied des murailles de la forteresse du pouvoir russe.",e:"Le mausolée de Lénine se dresse sur la place Rouge de Moscou, contre le mur du Kremlin ; Staline y a été exposé à ses côtés de 1953 à 1961.",p:"Mausolée de Lénine, Moscou, Russie",a:55.7537,o:37.6198},
{n:1,t:"Joseph Staline",c:"Dirigeant",x:"Dirigeant de l'Union soviétique de la fin des années 1920 à 1953, responsable de répressions de masse qui ont fait des millions de victimes.",e:"Il n'était pas russe mais géorgien : son vrai nom était Iossif Djougachvili.",p:"Gori, Géorgie",a:41.9853,o:44.1129},
{n:1,t:"Adolf Hitler",c:"Dictateur",x:"Dictateur à la tête de l'Allemagne nazie de 1933 à 1945, responsable de la Seconde Guerre mondiale en Europe et de la Shoah.",e:"Il est né dans l'Empire austro-hongrois, dans une petite ville à la frontière avec la Bavière.",p:"Braunau am Inn, Autriche",a:48.2583,o:13.0347},
{n:1,k:"vie",t:"Martin Luther King",c:"Droits civiques",q:"lieu de son assassinat",x:"Pasteur, prix Nobel de la paix 1964, auteur du discours « I have a dream ». Venu soutenir une grève des éboueurs noirs dans une grande ville du Tennessee, il est abattu le 4 avril 1968 sur le balcon de son hôtel.",e:"Le Lorraine Motel de Memphis abrite aujourd'hui le Musée national des droits civiques ; sa chambre, la 306, est restée en l'état.",p:"Lorraine Motel, Memphis, Tennessee, États-Unis",a:35.1345,o:-90.0577},
{n:1,t:"Vladimir Poutine",c:"Président",x:"Ancien officier du KGB, il est élu président de la Russie pour la première fois en 2000.",e:"Il a grandi dans un appartement communautaire de sa ville natale, alors appelée Leningrad.",p:"Saint-Pétersbourg, Russie",a:59.9386,o:30.3141},
{n:1,k:"vie",t:"Donald Trump",c:"Président",q:"résidence où il vit",x:"45e et 47e président des États-Unis. Promoteur new-yorkais, il achète en 1985 un palais de style hispano-mauresque sur une île-barrière de Floride, devenu un club privé surnommé sa « Maison-Blanche d'hiver ».",e:"Mar-a-Lago, à Palm Beach, a été construit dans les années 1920 pour l'héritière Marjorie Merriweather Post ; Trump en fait sa résidence principale en 2019.",p:"Mar-a-Lago, Palm Beach, Floride, États-Unis",a:26.677,o:-80.037},
{n:1,t:"Emmanuel Macron",c:"Président",x:"Élu président de la République française en 2017, à 39 ans, devenant le plus jeune chef de l'État de l'histoire du pays.",e:"Il est né dans la préfecture de la Somme, où il a rencontré son épouse au lycée.",p:"Amiens, France",a:49.9,o:2.3},
{n:2,k:"vie",t:"Mahatma Gandhi",c:"Politique",q:"lieu de son assassinat",x:"Guide de l'indépendance indienne par la non-violence. Le 30 janvier 1948, il est abattu par un nationaliste hindou dans le jardin de la demeure de la capitale où il séjournait, alors qu'il se rendait à sa prière du soir.",e:"La Birla House de New Delhi est devenue le mémorial Gandhi Smriti ; des empreintes de pas en pierre retracent ses derniers pas jusqu'au lieu du drame.",p:"Birla House, New Delhi, Inde",a:28.6014,o:77.2144},
{n:2,t:"Barack Obama",c:"Politique",x:"44e président des États-Unis, premier Afro-Américain à ce poste, prix Nobel de la paix 2009. Il est né sur une île du Pacifique.",e:"Il est né à Honolulu, capitale de l'État d'Hawaï, sur l'île d'Oahu, où il a fait ses études secondaires à la Punahou School.",p:"Honolulu, Hawaï",a:21.3099,o:-157.8581},
{n:2,k:"vie",t:"Charles de Gaulle",c:"Politique",q:"maison où il a vécu",x:"Auteur de l'appel du 18 juin 1940, fondateur de la Ve République. Il achète en 1934 une demeure dans un petit village de Haute-Marne, où il écrit ses mémoires, se retire en 1969 et meurt en 1970.",e:"La Boisserie, à Colombey-les-Deux-Églises, se visite ; une immense croix de Lorraine domine le village, où le général est enterré.",p:"La Boisserie, Colombey-les-Deux-Églises, France",a:48.2214,o:4.8858},
{n:2,t:"Angela Merkel",c:"Chancelière",x:"Première femme chancelière de son pays, de 2005 à 2021. Physicienne de formation, elle a grandi en RDA.",e:"Elle est née à l'Ouest, dans une grande ville portuaire, avant que sa famille ne parte s'installer en Allemagne de l'Est.",p:"Hambourg, Allemagne",a:53.5507,o:9.993},
{n:2,t:"Margaret Thatcher",c:"Première ministre",x:"Surnommée « la Dame de fer », première femme à diriger le gouvernement britannique, de 1979 à 1990.",e:"Fille d'un épicier, elle a grandi au-dessus de la boutique familiale, dans une petite ville du Lincolnshire.",p:"Grantham, Royaume-Uni",a:52.9115,o:-0.6418},
{n:2,t:"Xi Jinping",c:"Président",x:"Secrétaire général du Parti communiste chinois depuis 2012 et président de la République populaire depuis 2013.",e:"Fils d'un dirigeant communiste, il a été envoyé à la campagne pendant la Révolution culturelle.",p:"Pékin, Chine",a:39.9075,o:116.3972},
{n:2,t:"Narendra Modi",c:"Premier ministre",x:"Premier ministre de l'Inde depuis 2014, auparavant chef du gouvernement du Gujarat. Il raconte avoir vendu du thé dans une gare dans sa jeunesse.",e:"Sa petite ville natale est un site ancien où l'on a retrouvé des vestiges bouddhistes.",p:"Vadnagar, Gujarat, Inde",a:23.785,o:72.64},
{n:2,t:"François Mitterrand",c:"Président",x:"Premier président de gauche de la Ve République, élu en 1981 et réélu en 1988. Il fait abolir la peine de mort.",e:"Il est né dans une petite ville de Charente connue pour son cognac, où il est aussi enterré.",p:"Jarnac, France",a:45.6806,o:-0.1747},
{n:2,t:"Jawaharlal Nehru",c:"Premier ministre",x:"Compagnon de Gandhi dans la lutte pour l'indépendance, il devient en 1947 le premier chef du gouvernement de l'Inde indépendante.",e:"Sa ville natale, au confluent du Gange et de la Yamuna, s'appelle aujourd'hui Prayagraj.",p:"Allahabad (Prayagraj), Inde",a:25.4448,o:81.8432},
{n:2,k:"vie",t:"Benazir Bhutto",c:"Première ministre",q:"lieu de son assassinat",x:"Première femme à diriger le gouvernement d'un pays à majorité musulmane. Le 27 décembre 2007, elle est tuée en quittant un meeting électoral dans un parc de la ville-garnison voisine de la capitale de son pays.",e:"Elle est assassinée à la sortie du parc Liaquat Bagh de Rawalpindi, là même où le premier Premier ministre du pays, Liaquat Ali Khan, avait été tué en 1951.",p:"Liaquat Bagh, Rawalpindi, Pakistan",a:33.603,o:73.065},
{n:2,k:"vie",t:"Eva Perón",c:"Figure politique",q:"lieu où elle est enterrée",x:"« Evita », épouse de président adulée des classes populaires, morte à 33 ans en 1952. Après un long périple de son corps embaumé jusqu'en Europe, elle repose depuis 1976 dans le caveau familial de la nécropole la plus chic de la capitale argentine.",e:"Elle repose dans le caveau renforcé de la famille Duarte, au cimetière de la Recoleta, à Buenos Aires, l'un des lieux les plus visités de la ville.",p:"Cimetière de la Recoleta, Buenos Aires, Argentine",a:-34.5875,o:-58.3933},
{n:2,k:"vie",t:"Luiz Inácio Lula da Silva",c:"Président",q:"ville de ses grèves syndicales",x:"Ancien ouvrier métallurgiste, président du Brésil. Il devient célèbre en dirigeant à la fin des années 1970 de grandes grèves dans les usines automobiles de la banlieue industrielle de la plus grande ville du pays.",e:"Il préside le syndicat des métallurgistes de São Bernardo do Campo, dans la région industrielle de l'ABC, au sud-est de São Paulo.",p:"São Bernardo do Campo, Brésil",a:-23.6914,o:-46.5646},
{n:2,t:"Augusto Pinochet",c:"Dictateur",x:"Général arrivé au pouvoir par le coup d'État du 11 septembre 1973, il dirige une dictature militaire jusqu'en 1990.",e:"Il est né dans le grand port du pays, siège de la marine chilienne.",p:"Valparaíso, Chili",a:-33.036,o:-71.6296},
{n:2,t:"Gamal Abdel Nasser",c:"Président",x:"Officier devenu président de son pays en 1956, il nationalise le canal de Suez la même année et devient le héros du panarabisme.",e:"Il est né dans la grande ville fondée par Alexandre le Grand sur la Méditerranée.",p:"Alexandrie, Égypte",a:31.2018,o:29.9158},
{n:2,t:"Yasser Arafat",c:"Dirigeant",x:"Chef de l'Organisation de libération de la Palestine pendant 35 ans, prix Nobel de la paix 1994 avec Yitzhak Rabin et Shimon Peres.",e:"Il est né et a fait ses études d'ingénieur dans une grande capitale arabe, hors de Palestine.",p:"Le Caire, Égypte",a:30.0626,o:31.2497},
{n:2,t:"Rouhollah Khomeini",w:"Rouhollah Khomeini",c:"Guide suprême",x:"Religieux chiite exilé pendant quinze ans, il revient en 1979 pour prendre la tête de la révolution et fonder une république islamique.",e:"Son nom vient de sa ville natale, une petite ville du centre de l'Iran.",p:"Khomeyn, Iran",a:33.6389,o:50.08},
{n:2,t:"Saddam Hussein",c:"Dictateur",x:"Président de l'Irak de 1979 à 2003, il mène la guerre contre l'Iran puis envahit le Koweït en 1990. Il est renversé par l'invasion américaine.",e:"Il est né dans un village au bord du Tigre, près de la ville natale de Saladin.",p:"Al-Awja, près de Tikrit, Irak",a:34.56,o:43.68},
{n:2,t:"Mouammar Kadhafi",c:"Dirigeant",x:"Officier qui prend le pouvoir par un coup d'État en 1969 et dirige son pays pendant 42 ans, jusqu'à sa chute en 2011.",e:"Il est né sous une tente bédouine dans le désert, et c'est près de sa ville natale qu'il a été tué en 2011.",p:"Près de Syrte, Libye",a:31.2089,o:16.5887},
{n:2,t:"Recep Tayyip Erdoğan",c:"Président",x:"Ancien maire de la plus grande ville de son pays, Premier ministre à partir de 2003 puis président de la Turquie à partir de 2014.",e:"Il a grandi dans le quartier populaire de Kasımpaşa, sur la Corne d'Or.",p:"Istanbul, Turquie",a:41.0138,o:28.9497},
{n:2,t:"Volodymyr Zelensky",c:"Président",x:"Comédien qui jouait un président dans une série télévisée, il est élu président de l'Ukraine en 2019.",e:"Sa ville natale est un grand centre minier et sidérurgique du sud-est du pays.",p:"Kryvyï Rih, Ukraine",a:47.9057,o:33.394},
{n:2,t:"Justin Trudeau",c:"Premier ministre",x:"Premier ministre du Canada de 2015 à 2025, fils d'un autre Premier ministre célèbre du pays.",e:"Il est né le jour de Noël 1971 dans la capitale fédérale, pendant le mandat de son père.",p:"Ottawa, Canada",a:45.4112,o:-75.6981},
{n:2,t:"Franklin Delano Roosevelt",c:"Président",x:"Seul président américain élu quatre fois, il lance le New Deal contre la Grande Dépression et dirige son pays pendant la Seconde Guerre mondiale.",e:"Il est né dans le domaine familial de Springwood, dans la vallée de l'Hudson, où il est enterré.",p:"Hyde Park, New York, États-Unis",a:41.7684,o:-73.9343},
{n:2,t:"Aung San Suu Kyi",c:"Dirigeante",x:"Opposante à la junte militaire, assignée à résidence pendant près de quinze ans, prix Nobel de la paix en 1991.",e:"Elle est la fille du général Aung San, héros de l'indépendance birmane, assassiné quand elle avait deux ans.",p:"Rangoun, Birmanie",a:16.8053,o:96.1561},
{n:2,k:"vie",t:"Simone Veil",c:"Ministre",q:"lieu de son discours sur l'IVG",x:"Rescapée d'Auschwitz et ministre de la Santé. Le 26 novembre 1974, face à des députés presque tous masculins, elle défend la légalisation de l'IVG dans l'hémicycle d'un palais au bord de la Seine.",e:"Son discours au Palais Bourbon, siège de l'Assemblée nationale, ouvre trois jours de débats houleux ; la loi entre en vigueur en 1975, et Simone Veil entre au Panthéon en 2018.",p:"Palais Bourbon, Paris, France",a:48.862,o:2.3185},
{n:2,t:"Kamala Harris",c:"Vice-présidente",x:"Première femme vice-présidente des États-Unis, de 2021 à 2025, après avoir été procureure générale de Californie.",e:"Elle est née d'une mère indienne et d'un père jamaïcain, dans une ville de la baie de San Francisco.",p:"Oakland, Californie, États-Unis",a:37.8044,o:-122.2708},
{n:2,t:"Lee Kuan Yew",c:"Premier ministre",x:"Premier chef du gouvernement de sa cité-État à partir de 1959, il en fait l'une des économies les plus prospères d'Asie en trois décennies.",e:"Il est né, a gouverné et est mort dans la même île, colonie britannique à sa naissance.",p:"Singapour",a:1.2897,o:103.8501},
{n:3,k:"vie",t:"Nelson Mandela",c:"Politique",q:"lieu de son investiture",x:"Prisonnier politique pendant 27 ans. Le 10 mai 1994, il prête serment comme premier président noir de son pays sur l'esplanade du siège du gouvernement, dans la capitale administrative, où se dresse aujourd'hui sa statue de 9 mètres.",e:"Il est investi devant les Union Buildings de Pretoria, en présence de dirigeants du monde entier ; sa statue, les bras ouverts, y a été dévoilée en 2013.",p:"Union Buildings, Pretoria, Afrique du Sud",a:-25.7402,o:28.212},
{n:3,t:"Malala Yousafzai",c:"Politique",x:"Militante pour l'éducation des filles, blessée par balle à 15 ans, plus jeune lauréate du prix Nobel de la paix en 2014.",e:"Mingora est la principale ville de la vallée de Swat, dans la province de Khyber Pakhtunkhwa, au nord-ouest du Pakistan.",p:"Mingora, Pakistan",a:34.7717,o:72.36},
{n:3,k:"vie",t:"Fidel Castro",c:"Politique",q:"lieu de sa première attaque",x:"Dirigeant de Cuba de 1959 à 2008. Le 26 juillet 1953, il lance avec plus d'une centaine de rebelles une attaque ratée contre un camp militaire de la deuxième ville de l'île, dans l'est du pays.",e:"L'assaut de la caserne Moncada, à Santiago de Cuba, échoue, mais il donne son nom au Mouvement du 26 juillet ; le bâtiment est devenu une école et un musée.",p:"Caserne Moncada, Santiago de Cuba, Cuba",a:20.0281,o:-75.8175},
{n:3,t:"Mao Zedong",c:"Politique",x:"Proclame la République populaire de Chine en 1949 depuis la place Tian'anmen. Il est né dans un village rural d'une province du centre-sud.",e:"Shaoshan se trouve dans le Hunan, au sud-ouest de Changsha ; sa maison natale est devenue un haut lieu de pèlerinage révolutionnaire.",p:"Shaoshan, Chine",a:27.9175,o:112.5289},
{n:3,k:"vie",t:"Hô Chi Minh",w:"Hô Chi Minh",c:"Politique",q:"lieu où il repose",x:"Dirigeant de l'indépendance vietnamienne. Le 2 septembre 1945, il lit la déclaration d'indépendance sur une grande place de la principale ville du nord du pays, où son corps embaumé repose depuis 1975 dans un monument de granit.",e:"Le mausolée se dresse sur la place Ba Đình, à Hanoï, à l'endroit même de la proclamation ; Hô Chi Minh avait pourtant demandé à être incinéré.",p:"Mausolée de Hô Chi Minh, Hanoï, Viêt Nam",a:21.0368,o:105.8347},
{n:3,t:"Mustafa Kemal Atatürk",c:"Politique",x:"Fondateur de la République de Turquie en 1923. Il est né dans une grande ville portuaire qui appartient aujourd'hui à un autre pays.",e:"Il est né à Thessalonique, deuxième ville de Grèce, alors ottomane ; sa maison natale, devenue musée, jouxte le consulat de Turquie.",p:"Thessalonique, Grèce",a:40.6401,o:22.9444},
{n:3,t:"Léopold Sédar Senghor",c:"Politique",x:"Poète et premier président de son pays, devenu en 1983 le premier Africain à siéger à l'Académie française.",e:"Il est né à Joal, port de pêche de la Petite-Côte au sud de Dakar, qui forme une commune avec Fadiouth, île de coquillages reliée par un pont de bois.",p:"Joal, Sénégal",a:14.1667,o:-16.8333},
{n:3,t:"Thomas Sankara",c:"Politique",x:"Capitaine devenu président en 1983, il rebaptise son pays « pays des hommes intègres ». Il est assassiné en 1987.",e:"Yako est une ville du nord du Burkina Faso, chef-lieu de la province du Passoré, à une centaine de kilomètres au nord-ouest de Ouagadougou.",p:"Yako, Burkina Faso",a:13.0333,o:-2.2667},
{n:3,t:"Golda Meir",c:"Première ministre",x:"Quatrième chef du gouvernement d'Israël, de 1969 à 1974, l'une des premières femmes au monde à diriger un gouvernement.",e:"Elle est née dans l'Empire russe, dans l'actuelle capitale ukrainienne, avant d'émigrer aux États-Unis à huit ans.",p:"Kiev, Ukraine",a:50.4547,o:30.5238},
{n:3,k:"vie",t:"David Ben Gourion",c:"Premier ministre",q:"lieu de la proclamation d'Israël",x:"Premier chef du gouvernement d'Israël. Le 14 mai 1948, il lit la déclaration d'indépendance dans un ancien musée d'art d'une grande ville côtière fondée en 1909.",e:"La maison Dizengoff, boulevard Rothschild à Tel Aviv, ancienne demeure du premier maire de la ville, est aujourd'hui la salle de l'Indépendance.",p:"Maison Dizengoff, Tel Aviv, Israël",a:32.0628,o:34.7707},
{n:3,k:"vie",t:"Kwame Nkrumah",c:"Président",q:"lieu de la proclamation d'indépendance",x:"Père de l'indépendance de la Gold Coast, devenue le Ghana. À minuit, le 6 mars 1957, il proclame l'indépendance sur un ancien terrain de polo de la capitale, où se trouve aujourd'hui son mausolée.",e:"Le parc mémorial Kwame Nkrumah, à Accra, occupe l'ancien terrain de polo où il lança « Le Ghana est libre pour toujours » ; il y repose avec son épouse.",p:"Parc mémorial Kwame Nkrumah, Accra, Ghana",a:5.5446,o:-0.2036},
{n:3,t:"Julius Nyerere",c:"Président",x:"Surnommé « Mwalimu » (l'instituteur), il mène son pays à l'indépendance en 1961 et le dirige jusqu'en 1985.",e:"Il était fils d'un chef du petit peuple Zanaki, près de la rive orientale du lac Victoria.",p:"Butiama, Tanzanie",a:-1.77,o:33.97},
{n:3,t:"Jomo Kenyatta",c:"Président",x:"Emprisonné par les Britanniques pendant la révolte des Mau Mau, il devient le premier président de son pays indépendant en 1964.",e:"Il est né dans les hautes terres du centre du pays, chez les Kikuyus, au nord de l'actuelle capitale.",p:"Gatundu, Kenya",a:-1.01,o:36.9},
{n:3,t:"Ellen Johnson Sirleaf",c:"Présidente",x:"Économiste, elle devient en 2006 la première femme élue à la tête d'un État africain. Prix Nobel de la paix 2011.",e:"Elle est née dans la capitale d'un pays fondé par d'anciens esclaves affranchis venus des États-Unis.",p:"Monrovia, Liberia",a:6.3005,o:-10.7969},
{n:3,k:"vie",t:"Juan Perón",c:"Président",q:"lieu de la manifestation fondatrice",x:"Officier élu trois fois président de l'Argentine. Le 17 octobre 1945, des centaines de milliers d'ouvriers envahissent la grande place historique de la capitale pour exiger sa libération : c'est l'acte de naissance du péronisme.",e:"Ce soir-là, il s'adresse à la foule depuis le balcon de la Casa Rosada, sur la place de Mai de Buenos Aires ; le 17 octobre est resté le « jour de la Loyauté ».",p:"Plaza de Mayo, Buenos Aires, Argentine",a:-34.6083,o:-58.3722},
{n:3,t:"Hugo Chávez",c:"Président",x:"Lieutenant-colonel auteur d'un coup d'État manqué en 1992, élu président en 1998, il lance la « révolution bolivarienne ».",e:"Il est né dans un village des plaines des Llanos, fils de deux instituteurs.",p:"Sabaneta, Barinas, Venezuela",a:8.7522,o:-69.9332},
{n:3,t:"Benito Juárez",c:"Président",x:"Premier président d'origine amérindienne de son pays, il combat l'intervention française et fait fusiller l'empereur Maximilien en 1867.",e:"Zapotèque orphelin, il ne parlait pas espagnol avant l'âge de douze ans.",p:"San Pablo Guelatao, Oaxaca, Mexique",a:17.32,o:-96.49},
{n:3,k:"vie",t:"Sukarno",c:"Président",q:"lieu de la conférence de 1955",x:"Premier président de l'Indonésie. En avril 1955, il accueille dans une ville de Java occidental, où il avait fait ses études d'ingénieur, la première grande conférence des pays d'Asie et d'Afrique, berceau du mouvement des non-alignés.",e:"La conférence de Bandung se tient au Gedung Merdeka (« bâtiment de la Liberté »), devenu le musée de la Conférence Asie-Afrique.",p:"Gedung Merdeka, Bandung, Indonésie",a:-6.9211,o:107.6094},
{n:3,t:"Kim Il-sung",c:"Dirigeant",x:"Fondateur du régime nord-coréen en 1948, il dirige le pays jusqu'à sa mort en 1994 et y fait l'objet d'un culte de la personnalité.",e:"Sa maison natale, à Mangyongdae, est aujourd'hui un lieu de pèlerinage officiel.",p:"Mangyongdae, Pyongyang, Corée du Nord",a:39.01,o:125.66},
{n:3,k:"vie",t:"Shinzo Abe",c:"Premier ministre",q:"lieu de son assassinat",x:"Premier ministre resté le plus longtemps au pouvoir au Japon. Le 8 juillet 2022, il est abattu avec une arme artisanale pendant un discours devant une gare, dans l'ancienne capitale impériale du VIIIe siècle.",e:"Il est tué devant la gare de Yamato-Saidaiji, à Nara, ville célèbre pour ses temples et ses daims en liberté.",p:"Yamato-Saidaiji, Nara, Japon",a:34.6936,o:135.7836},
{n:3,t:"Ronald Reagan",c:"Président",x:"Ancien acteur de Hollywood, gouverneur de Californie puis président des États-Unis de 1981 à 1989.",e:"Il est né dans un appartement au-dessus d'une boulangerie, dans un village de l'Illinois.",p:"Tampico, Illinois, États-Unis",a:41.6306,o:-89.7859},
{n:3,t:"Thomas Jefferson",c:"Président",x:"Principal rédacteur de la Déclaration d'indépendance de 1776, il devient le troisième président des États-Unis et achète la Louisiane à la France.",e:"Il est né dans la plantation de son père, en Virginie, non loin de sa future demeure de Monticello.",p:"Shadwell, Virginie, États-Unis",a:38.0129,o:-78.4176},
{n:3,k:"vie",t:"Kofi Annan",c:"Diplomate",q:"siège de l'organisation qu'il dirige",x:"Diplomate ghanéen, prix Nobel de la paix 2001. De 1997 à 2006, il dirige une organisation mondiale depuis une tour de verre de 39 étages au bord de l'East River, dans la plus grande ville des États-Unis.",e:"Au siège des Nations unies, à Manhattan, Kofi Annan est le premier secrétaire général issu du personnel même de l'organisation.",p:"Siège des Nations unies, New York, États-Unis",a:40.7489,o:-73.968},
{n:3,t:"Habib Bourguiba",c:"Président",x:"Avocat et militant nationaliste, il mène son pays à l'indépendance en 1956 et accorde aux femmes des droits avancés pour l'époque.",e:"Il est né dans une ville côtière du Sahel tunisien, où se trouve son mausolée.",p:"Monastir, Tunisie",a:35.778,o:10.8262},
{n:3,t:"Josip Broz Tito",c:"Dirigeant",x:"Chef des partisans contre l'occupant nazi, il dirige la Yougoslavie de 1945 à 1980 et tient tête à Staline.",e:"Il est né dans un village du nord de l'actuelle Croatie, d'un père croate et d'une mère slovène.",p:"Kumrovec, Croatie",a:46.0767,o:15.6797},
{n:3,t:"Václav Havel",c:"Président",x:"Dramaturge dissident, plusieurs fois emprisonné, il devient président après la révolution de Velours de 1989.",e:"Il est né dans une riche famille de la capitale, propriétaire de studios de cinéma.",p:"Prague, Tchéquie",a:50.088,o:14.4208},
{n:3,t:"Otto von Bismarck",c:"Chancelier",x:"Surnommé « le chancelier de fer », il réalise l'unité allemande en 1871 après une guerre contre la France.",e:"Il est né dans le domaine familial d'un village de l'Altmark, à l'ouest de Berlin.",p:"Schönhausen, Allemagne",a:52.5822,o:12.0379},
{n:3,k:"vie",t:"Deng Xiaoping",c:"Dirigeant",q:"ville symbole de ses réformes",x:"Dirigeant chinois des réformes économiques. En 1980, il fait d'un groupe de villages voisins de Hong Kong l'une des premières zones économiques spéciales du pays, devenue une mégapole de plus de 17 millions d'habitants.",e:"Shenzhen, où il effectue en 1992 sa célèbre « tournée dans le Sud » pour relancer les réformes, lui a élevé une statue géante dans le parc Lianhuashan.",p:"Shenzhen, Chine",a:22.555,o:114.055},
{n:3,k:"vie",t:"Sun Yat-sen",c:"Président",q:"lieu où il est enterré",x:"Père de la Chine moderne, premier président provisoire de la République en 1912. Mort à Pékin en 1925, il repose dans un immense tombeau à flanc de montagne, au-dessus de la ville qui fut ensuite la capitale de la République.",e:"Le mausolée de Sun Yat-sen, sur la montagne Pourpre de Nankin, est accessible par un escalier de 392 marches.",p:"Mausolée de Sun Yat-sen, Nankin, Chine",a:32.064,o:118.8486},
{n:3,k:"vie",t:"Mahathir Mohamad",c:"Premier ministre",q:"ville nouvelle qu'il fait construire",x:"Premier ministre de la Malaisie de 1981 à 2003. Dans les années 1990, il lance la construction d'une capitale administrative nouvelle, à 25 km au sud de la capitale, qui accueille les services du gouvernement à partir de 1999.",e:"Putrajaya, bâtie autour d'un lac artificiel, porte le nom du premier Premier ministre du pays, Tunku Abdul Rahman Putra.",p:"Putrajaya, Malaisie",a:2.9264,o:101.6964},
{n:3,t:"Corazon Aquino",c:"Présidente",x:"Veuve d'un opposant assassiné, elle devient en 1986 présidente des Philippines après la révolution pacifique qui chasse Ferdinand Marcos.",e:"Elle est née dans une riche famille de planteurs de la province de Tarlac, au nord de Manille.",p:"Paniqui, Tarlac, Philippines",a:15.6689,o:120.5806},
{n:3,k:"vie",t:"Rosa Parks",c:"Droits civiques",q:"ville du boycott des bus",x:"Couturière, figure des droits civiques. Le 1er décembre 1955, elle refuse de céder sa place à un passager blanc dans un bus de la capitale de l'Alabama, ce qui déclenche un boycott de 381 jours mené par un jeune pasteur, Martin Luther King.",e:"À Montgomery, un musée consacré à Rosa Parks se dresse à l'endroit où elle a été arrêtée.",p:"Montgomery, Alabama, États-Unis",a:32.3775,o:-86.3105},
{n:3,k:"vie",t:"Malcolm X",c:"Droits civiques",q:"lieu de son assassinat",x:"Militant afro-américain, ancien porte-parole de la Nation of Islam. Le 21 février 1965, il est abattu en pleine conférence dans une salle de bal du nord de Manhattan, dans la plus grande ville américaine.",e:"L'Audubon Ballroom, sur Broadway à hauteur de la 165e rue, abrite aujourd'hui un centre mémorial qui porte son nom et celui de son épouse, Betty Shabazz.",p:"Audubon Ballroom, New York, États-Unis",a:40.8399,o:-73.9397},
{n:3,k:"vie",t:"Desmond Tutu",c:"Droits civiques",q:"lieu où il est inhumé",x:"Archevêque anglican, prix Nobel de la paix 1984. Premier Noir à la tête de l'Église anglicane d'Afrique australe, il prêche contre l'apartheid dans une église de la plus ancienne ville du pays, au pied d'une montagne tabulaire, où ses cendres reposent depuis 2022.",e:"La cathédrale Saint-Georges du Cap, surnommée « la cathédrale du peuple », fut un haut lieu de la lutte contre l'apartheid ; ses cendres y ont été inhumées en janvier 2022.",p:"Cathédrale Saint-Georges, Le Cap, Afrique du Sud",a:-33.9253,o:18.4196},
{n:3,t:"Wangari Maathai",c:"Militante",x:"Biologiste fondatrice du mouvement de la ceinture verte, qui a planté des dizaines de millions d'arbres. Première Africaine prix Nobel de la paix, en 2004.",e:"Elle est née dans les hautes terres, au pied du mont Kenya.",p:"Ihithe, comté de Nyeri, Kenya",a:-0.42,o:36.95}
]);

/* ---- Histoire : rois, reines, empereurs, explorateurs, révolutionnaires, militaires ---- */
ajouter('histoire', 'perso', [
{n:1,t:"Napoléon Bonaparte",c:"Histoire",x:"Général devenu empereur des Français en 1804. Il est né en 1769, un an après le rattachement à la France de l'île où sa famille vivait.",e:"Il est né à Ajaccio, sur la côte ouest de la Corse, dans la maison Bonaparte, aujourd'hui devenue un musée national.",p:"Ajaccio, Corse",a:41.9192,o:8.7386},
{n:1,t:"Cléopâtre",w:"Cléopâtre VII",c:"Histoire",x:"Dernière reine active d'Égypte, d'origine grecque, alliée de Jules César puis de Marc Antoine.",e:"Alexandrie, fondée par Alexandre le Grand sur la Méditerranée, était la capitale de l'Égypte ptolémaïque, célèbre pour son phare et sa bibliothèque.",p:"Alexandrie, Égypte",a:31.2001,o:29.9187},
{n:1,t:"Jules César",c:"Histoire",x:"Général et homme d'État romain, conquérant de la Gaule, assassiné aux ides de mars 44 av. J.-C.",e:"Il est né à Rome dans une vieille famille patricienne, qui vivait dans la Subure, quartier populaire situé au pied de l'Esquilin.",p:"Rome, Italie",a:41.9028,o:12.4964},
{n:1,t:"Marco Polo",c:"Histoire",x:"Marchand du XIIIe siècle dont Le Devisement du monde raconte un voyage jusqu'à la cour de Kubilai Khan.",e:"Il est né à Venise, alors puissante république maritime ; on situe la maison familiale près du Rialto, dans l'actuelle Corte del Milion.",p:"Venise, Italie",a:45.4408,o:12.3155},
{n:1,t:"Louis XIV",c:"Roi",x:"Surnommé « le Roi-Soleil », il règne 72 ans, record pour un monarque européen, et fait de Versailles le siège du pouvoir.",e:"Il est né dans le château neuf d'une ville royale à l'ouest de Paris, aujourd'hui disparu.",p:"Saint-Germain-en-Laye, France",a:48.8964,o:2.0904},
{n:1,k:"vie",t:"Victoria (reine)",w:"Victoria (reine du Royaume-Uni)",c:"Reine",q:"lieu de sa mort",x:"Reine pendant 63 ans et impératrice des Indes. Elle meurt en janvier 1901 dans sa résidence d'été à l'italienne, sur une île de la Manche, qu'elle avait fait construire avec le prince Albert.",e:"Osborne House, sur l'île de Wight, a été dessinée par le prince Albert dans le style d'une villa italienne ; la reine s'y retire souvent après la mort de son époux.",p:"Osborne House, île de Wight, Royaume-Uni",a:50.7505,o:-1.2697},
{n:1,k:"vie",t:"Élisabeth II",c:"Reine",q:"lieu de sa mort",x:"Reine pendant 70 ans. Elle meurt le 8 septembre 2022 dans un château des Highlands acheté par le prince Albert pour la reine Victoria, où la famille royale passe traditionnellement l'été.",e:"Le château de Balmoral, au bord de la Dee dans l'Aberdeenshire, est une propriété privée de la famille royale et non de la Couronne.",p:"Château de Balmoral, Écosse, Royaume-Uni",a:57.0406,o:-3.2302},
{n:1,k:"vie",t:"Marie-Antoinette",c:"Reine",q:"domaine où elle se retire",x:"Dernière reine de l'Ancien Régime, guillotinée en 1793. Lassée de l'étiquette de la cour, elle se réfugie dans un pavillon néoclassique du parc royal, offert par Louis XVI, près duquel elle fait construire un hameau rustique.",e:"Le Petit Trianon, dans le parc du château de Versailles, était son domaine privé ; on lui reproche les dépenses de son hameau, avec sa ferme et son moulin.",p:"Petit Trianon, Versailles, France",a:48.8156,o:2.1099},
{n:1,t:"Ernesto « Che » Guevara",w:"Che Guevara",c:"Révolutionnaire",x:"Médecin devenu guérillero, compagnon de Fidel Castro dans la révolution cubaine, tué en Bolivie en 1967. Son portrait est l'une des images les plus reproduites au monde.",e:"Il n'était pas cubain mais argentin, né dans un grand port sur le fleuve Paraná.",p:"Rosario, Argentine",a:-32.9468,o:-60.6393},
{n:1,k:"vie",t:"Anne Frank",c:"Témoin",q:"cachette où elle écrit son journal",x:"Adolescente juive qui tient un journal pendant deux ans de clandestinité. De 1942 à 1944, sa famille se cache dans l'annexe secrète de l'entreprise de son père, au bord d'un canal de la capitale néerlandaise.",e:"La Maison d'Anne Frank, au 263 Prinsengracht à Amsterdam, est devenue un musée ; la famille y est arrêtée le 4 août 1944.",p:"Maison d'Anne Frank, Amsterdam, Pays-Bas",a:52.3752,o:4.884},
{n:1,t:"Neil Armstrong",c:"Explorateur",x:"Commandant de la mission Apollo 11, premier homme à marcher sur la Lune, le 21 juillet 1969 (heure de Paris).",e:"Il est né dans une petite ville de l'Ohio, qui abrite aujourd'hui un musée de l'air et de l'espace à son nom.",p:"Wapakoneta, Ohio, États-Unis",a:40.5678,o:-84.1936},
{n:1,k:"vie",t:"Youri Gagarine",c:"Explorateur",q:"lieu de son atterrissage",x:"Premier humain dans l'espace, le 12 avril 1961. Après 108 minutes de vol, il s'éjecte de sa capsule et atterrit en parachute dans un champ au bord de la Volga, dans le sud de la Russie, devant une paysanne et sa petite-fille.",e:"Le lieu de l'atterrissage, près d'Engels, dans l'oblast de Saratov, est marqué par un monument ; Gagarine avait étudié et appris à piloter à Saratov, toute proche.",p:"Près d'Engels, oblast de Saratov, Russie",a:51.271,o:45.997},
{n:2,t:"Jeanne d'Arc",c:"Histoire",x:"Jeune paysanne devenue chef de guerre pendant la guerre de Cent Ans, brûlée à Rouen en 1431 à l'âge de 19 ans.",e:"Domrémy, aujourd'hui Domrémy-la-Pucelle, est un village des Vosges au bord de la Meuse, où sa maison natale se visite.",p:"Domrémy, France",a:48.4425,o:5.6729},
{n:2,t:"Alexandre le Grand",c:"Histoire",x:"Roi de Macédoine, il conquiert l'empire perse et pousse jusqu'à l'Indus avant de mourir à 32 ans à Babylone.",e:"Pella était la capitale du royaume de Macédoine ; ses ruines, riches en mosaïques, se trouvent dans le nord de la Grèce, à l'ouest de Thessalonique.",p:"Pella, Grèce",a:40.7611,o:22.5233},
{n:2,t:"Christophe Colomb",c:"Histoire",x:"Navigateur qui atteint les Amériques en 1492 pour le compte de l'Espagne, alors qu'il n'est pas né dans ce pays.",e:"Il est né à Gênes, grand port de Ligurie ; une maison reconstruite près de la Porta Soprana est présentée comme celle de son enfance.",p:"Gênes, Italie",a:44.4056,o:8.9463},
{n:2,k:"vie",t:"Vasco de Gama",c:"Explorateur",q:"ville indienne qu'il atteint",x:"Navigateur qui ouvre la route maritime des Indes en contournant l'Afrique. Le 20 mai 1498, il accoste près d'un grand port de la côte de Malabar, capitale du zamorin, enrichi par le commerce des épices.",e:"Il débarque près de Calicut (aujourd'hui Kozhikode), dans l'actuel Kerala ; il meurt en 1524 à Cochin, plus au sud, lors de son troisième voyage.",p:"Calicut (Kozhikode), Inde",a:11.2588,o:75.7804},
{n:2,k:"vie",t:"James Cook",c:"Explorateur",q:"lieu de sa mort",x:"Navigateur qui cartographie la Nouvelle-Zélande et l'est de l'Australie. Le 14 février 1779, il est tué lors d'une échauffourée avec des habitants dans une baie de la côte ouest de la plus grande île d'un archipel du Pacifique nord.",e:"Un obélisque blanc marque le lieu de sa mort, au bord de la baie de Kealakekua, sur la côte ouest de l'île d'Hawaï.",p:"Baie de Kealakekua, Hawaï, États-Unis",a:19.4811,o:-155.9319},
{n:2,t:"Ibn Battuta",c:"Explorateur",x:"Voyageur du XIVe siècle qui parcourt environ 120 000 km en près de trente ans, de l'Afrique de l'Ouest jusqu'à la Chine.",e:"Il est né dans un port à l'entrée du détroit de Gibraltar, où l'on peut voir un tombeau qui lui est attribué.",p:"Tanger, Maroc",a:35.7673,o:-5.7998},
{n:2,k:"vie",t:"Saladin",c:"Sultan",q:"lieu où il est enterré",x:"Sultan qui reprend Jérusalem aux croisés en 1187. Mort en 1193 dans la grande ville de Syrie où il résidait, il repose dans un petit tombeau à côté de la grande mosquée des Omeyyades.",e:"Son mausolée de Damas contient deux sarcophages : le sien, en bois, et un autre en marbre offert en 1898 par l'empereur allemand Guillaume II.",p:"Mausolée de Saladin, Damas, Syrie",a:33.5124,o:36.3058},
{n:2,t:"Catherine II",w:"Catherine II de Russie",c:"Impératrice",x:"Impératrice de Russie de 1762 à 1796, protectrice de Voltaire et Diderot, surnommée « la Grande ».",e:"Elle était une princesse allemande, née dans un port de la Baltique aujourd'hui polonais.",p:"Stettin (Szczecin), Pologne",a:53.4289,o:14.553},
{n:2,k:"vie",t:"Pierre le Grand",c:"Tsar",q:"lieu où il est enterré",x:"Tsar modernisateur de la Russie. En 1703, il fonde sur une île de l'embouchure de la Neva une citadelle, noyau de sa future capitale, dans la cathédrale de laquelle il est enterré.",e:"La cathédrale de la forteresse Pierre-et-Paul, à Saint-Pétersbourg, abrite les tombeaux de presque tous les tsars depuis Pierre le Grand, dont Nicolas II depuis 1998.",p:"Forteresse Pierre-et-Paul, Saint-Pétersbourg, Russie",a:59.95,o:30.3166},
{n:2,t:"Giuseppe Garibaldi",c:"Révolutionnaire",x:"Héros de l'unité italienne, à la tête de l'expédition des Mille et de ses chemises rouges en 1860.",e:"Sa ville natale passa au royaume de Sardaigne en 1814, puis fut cédée à la France en 1860, à son grand regret.",p:"Nice, France",a:43.7031,o:7.2661},
{n:2,k:"vie",t:"Richard Cœur de Lion",c:"Roi",q:"lieu où il est enterré",x:"Roi d'Angleterre parlant surtout français, mort en 1199 au siège d'un château du Limousin. Il est inhumé aux pieds de son père, dans un grand monastère de l'Anjou où repose aussi sa mère, Aliénor d'Aquitaine.",e:"Les gisants de Richard, de ses parents Henri II et Aliénor, et d'Isabelle d'Angoulême se trouvent dans l'abbaye de Fontevraud, près de Saumur ; son cœur, lui, est à Rouen.",p:"Abbaye de Fontevraud, France",a:47.1813,o:0.0511},
{n:2,k:"vie",t:"Guillaume le Conquérant",c:"Roi",q:"lieu de sa victoire de 1066",x:"Duc de Normandie. Le 14 octobre 1066, il bat le roi Harold sur une colline du sud de l'Angleterre, où il fait ensuite élever une abbaye à l'endroit où Harold serait tombé.",e:"La bataille dite d'Hastings s'est déroulée à une dizaine de kilomètres de la ville d'Hastings, là où s'est développée la ville de Battle, autour de l'abbaye.",p:"Battle, Royaume-Uni",a:50.9145,o:0.4876},
{n:2,t:"Charles Quint",c:"Empereur",x:"Empereur du Saint-Empire et roi d'Espagne au XVIe siècle, à la tête d'un empire « sur lequel le soleil ne se couche jamais ».",e:"Il est né en Flandre, dans une grande ville marchande, où il a passé son enfance.",p:"Gand, Belgique",a:51.05,o:3.7167},
{n:2,t:"Élisabeth Ire",w:"Élisabeth Ire (reine d'Angleterre)",c:"Reine",x:"Fille d'Henri VIII et d'Anne Boleyn, reine d'Angleterre de 1558 à 1603, surnommée « la reine vierge ».",e:"Elle est née au palais de Placentia, résidence royale au bord de la Tamise aujourd'hui détruite.",p:"Greenwich, Londres, Royaume-Uni",a:51.4826,o:-0.0077},
{n:2,k:"vie",t:"Louis XVI",c:"Roi",q:"lieu de son exécution",x:"Dernier roi de l'Ancien Régime. Le 21 janvier 1793, il est guillotiné sur une vaste esplanade de la capitale, alors baptisée « de la Révolution », où se dresse aujourd'hui l'obélisque de Louxor.",e:"La place de la Concorde, à Paris, porte ce nom depuis 1795 ; Marie-Antoinette, Danton et Robespierre y ont aussi été guillotinés.",p:"Place de la Concorde, Paris, France",a:48.8656,o:2.3212},
{n:2,t:"Maximilien de Robespierre",c:"Révolutionnaire",x:"Avocat surnommé « l'Incorruptible », figure de la Terreur pendant la Révolution française, guillotiné en juillet 1794.",e:"Il est né dans le chef-lieu de l'Artois, où il a été avocat avant d'être élu aux États généraux.",p:"Arras, France",a:50.293,o:2.7819},
{n:2,t:"Hannibal Barca",c:"Général",x:"Général qui franchit les Alpes avec des éléphants en 218 av. J.-C. pour attaquer Rome, et remporte la bataille de Cannes.",e:"Il est né dans la grande cité punique fondée par des colons phéniciens en Afrique du Nord.",p:"Carthage, Tunisie",a:36.8528,o:10.3233},
{n:2,t:"Haïlé Sélassié",c:"Empereur",x:"Dernier empereur d'Éthiopie, de 1930 à 1974, figure de la résistance à l'invasion italienne et vénéré par le mouvement rastafari.",e:"Il est né dans un village de la province du Harar, dans l'est du pays.",p:"Ejersa Goro, près de Harar, Éthiopie",a:9.33,o:42.2},
{n:3,t:"Mère Teresa",c:"Religion",x:"Religieuse fondatrice des Missionnaires de la Charité, prix Nobel de la paix 1979. Elle est née dans l'Empire ottoman.",e:"Elle est née à Skopje, capitale de la Macédoine du Nord, dans une famille albanaise ; une maison mémorial lui est consacrée dans le centre-ville.",p:"Skopje, Macédoine du Nord",a:41.9981,o:21.4254},
{n:3,t:"Zheng He",c:"Explorateur",x:"Amiral eunuque de la dynastie Ming qui mène sept grandes expéditions maritimes au début du XVe siècle, jusqu'aux côtes d'Afrique de l'Est.",e:"Il est né dans une famille musulmane du sud-ouest de la Chine, près du lac Dian.",p:"Kunyang, Yunnan, Chine",a:24.67,o:102.6},
{n:3,t:"Roald Amundsen",c:"Explorateur",x:"Premier à atteindre le pôle Sud, le 14 décembre 1911, devant l'expédition britannique de Robert Scott.",e:"Il est né à Borge, près d'une ville portuaire à l'embouchure de la Glomma, dans une famille d'armateurs.",p:"Borge, près de Fredrikstad, Norvège",a:59.2181,o:10.9298},
{n:3,k:"vie",t:"Soliman le Magnifique",c:"Sultan",q:"lieu où il est enterré",x:"Sultan ottoman au plus long règne. Il repose dans un mausolée à côté du grand sanctuaire qui porte son nom, chef-d'œuvre de l'architecte Sinan, sur l'une des collines de sa capitale dominant la Corne d'Or.",e:"La mosquée Süleymaniye d'Istanbul abrite dans son jardin les tombeaux de Soliman et de son épouse Roxelane ; Sinan est enterré juste à côté.",p:"Mosquée Süleymaniye, Istanbul, Turquie",a:41.0162,o:28.9639},
{n:3,t:"Mehmed II",c:"Sultan",x:"Sultan ottoman surnommé « le Conquérant » après la prise de Constantinople en 1453, à 21 ans.",e:"Il est né dans l'ancienne capitale ottomane, en Thrace.",p:"Edirne, Turquie",a:41.6772,o:26.556},
{n:3,k:"vie",t:"Nicolas II",w:"Nicolas II (empereur de Russie)",c:"Tsar",q:"lieu de son exécution",x:"Dernier tsar de Russie, contraint d'abdiquer en 1917. Dans la nuit du 16 au 17 juillet 1918, il est fusillé avec sa famille par les bolcheviks dans le sous-sol d'une maison réquisitionnée d'une grande ville de l'Oural.",e:"La maison Ipatiev a été rasée en 1977 ; l'église sur le Sang-Versé d'Iekaterinbourg, consacrée en 2003, a été construite à son emplacement.",p:"Église sur le Sang-Versé, Iekaterinbourg, Russie",a:56.8444,o:60.6089},
{n:3,k:"vie",t:"Toussaint Louverture",c:"Révolutionnaire",q:"lieu de sa mort",x:"Ancien esclave devenu général de la révolution de Saint-Domingue. Capturé par traîtrise sur ordre de Bonaparte, il meurt en avril 1803 dans le froid d'une forteresse du Haut-Doubs, près de la frontière suisse.",e:"Il meurt au fort de Joux, près de Pontarlier ; ses restes n'ont jamais été identifiés, et une inscription lui rend hommage au Panthéon depuis 1998.",p:"Fort de Joux, La Cluse-et-Mijoux, France",a:46.8717,o:6.375},
{n:3,t:"Hernán Cortés",c:"Conquistador",x:"Conquistador qui renverse l'Empire aztèque entre 1519 et 1521 et s'empare de Tenochtitlan.",e:"Il est né dans une petite ville d'Estrémadure qui a donné son nom à une grande ville de Colombie.",p:"Medellín, Espagne",a:38.9631,o:-5.9581},
{n:3,k:"vie",t:"Francisco Pizarro",c:"Conquistador",q:"lieu où il est enterré",x:"Conquistador qui capture l'empereur inca Atahualpa en 1532. Il fonde en 1535 une nouvelle capitale près de la côte pacifique, où il est assassiné en 1541 et repose dans le grand sanctuaire de la place principale.",e:"Ses restes reposent dans la cathédrale de Lima, sur la place d'Armes, face au palais du gouvernement bâti à l'emplacement de sa maison.",p:"Cathédrale de Lima, Lima, Pérou",a:-12.0464,o:-77.03},
{n:3,k:"vie",t:"José de San Martín",c:"Libérateur",q:"lieu de sa mort en exil",x:"Libérateur de l'Argentine, du Chili et du Pérou. Retiré de la politique, il s'exile en Europe et meurt en 1850 dans un port de la Manche, dans le nord de la France, où sa maison est devenue un musée.",e:"La maison où il meurt, à Boulogne-sur-Mer, appartient à l'Argentine ; ses restes ont été rapatriés en 1880 dans la cathédrale de Buenos Aires.",p:"Boulogne-sur-Mer, France",a:50.7264,o:1.6147},
{n:3,t:"La Fayette",w:"Gilbert du Motier de La Fayette",c:"Général",x:"Aristocrate parti à 19 ans combattre aux côtés des insurgés américains, surnommé « le héros des deux mondes ».",e:"Il est né au château de Chavaniac, en Auvergne, dans un village qui porte aujourd'hui son nom.",p:"Chavaniac-Lafayette, France",a:45.153,o:3.585},
{n:3,t:"Oliver Cromwell",c:"Lord-protecteur",x:"Chef militaire de la révolution anglaise, il fait exécuter le roi Charles Ier en 1649 et gouverne ensuite seul le pays.",e:"Il est né dans une petite ville du Cambridgeshire, dont il fut député.",p:"Huntingdon, Royaume-Uni",a:52.3305,o:-0.1865},
{n:3,t:"Ashoka",c:"Empereur",x:"Empereur maurya du IIIe siècle av. J.-C. qui, après une guerre sanglante, se convertit au bouddhisme et fait graver ses édits sur des piliers.",e:"Il est né dans la capitale de l'empire, Pataliputra, sur le Gange.",p:"Pataliputra (Patna), Inde",a:25.5941,o:85.1356},
{n:3,t:"Akbar",c:"Empereur",x:"Empereur moghol du XVIe siècle, connu pour sa tolérance religieuse et ses débats avec des savants de toutes confessions.",e:"Il est né dans le désert du Sind, pendant l'exil de son père chassé du trône.",p:"Umerkot, Pakistan",a:25.3633,o:69.7418},
{n:3,t:"Shah Jahan",c:"Empereur",x:"Empereur moghol qui fait élever un célèbre mausolée de marbre blanc pour son épouse Mumtaz Mahal, morte en couches en 1631.",e:"Il est né dans une grande ville du Pendjab, aujourd'hui au Pakistan.",p:"Lahore, Pakistan",a:31.558,o:74.3507},
{n:3,k:"vie",t:"Tokugawa Ieyasu",c:"Shogun",q:"sanctuaire où il est enterré",x:"Fondateur du shogunat qui gouverne le Japon pendant plus de 250 ans. Divinisé après sa mort en 1616, il repose dans un somptueux sanctuaire au cœur des montagnes, au nord de la plaine de Tokyo, célèbre pour ses trois singes de la sagesse.",e:"Le Tōshō-gū de Nikkō, couvert de dorures, abrite les sculptures des trois singes « ne rien voir, ne rien entendre, ne rien dire ».",p:"Tōshō-gū, Nikkō, Japon",a:36.758,o:139.5988},
{n:3,t:"Qin Shi Huang",c:"Empereur",x:"Premier empereur de la Chine unifiée en 221 av. J.-C., il unifie l'écriture et les mesures. Son tombeau est gardé par une armée de terre cuite.",e:"Il est né dans la capitale du royaume rival de Zhao, où son père était otage.",p:"Handan, Chine",a:36.61,o:114.4876},
{n:3,k:"vie",t:"Tamerlan",c:"Conquérant",q:"lieu où il est enterré",x:"Conquérant turco-mongol du XIVe siècle. Mort en 1405 alors qu'il partait envahir la Chine, il est enterré sous une coupole côtelée turquoise, dans la capitale d'Asie centrale qu'il a couverte de monuments.",e:"Le Gour-Emir de Samarcande, où repose aussi son petit-fils l'astronome Ulugh Beg, a inspiré les grands tombeaux moghols comme le Taj Mahal.",p:"Gour-Emir, Samarcande, Ouzbékistan",a:39.6487,o:66.969},
{n:3,k:"vie",t:"Isabelle la Catholique",c:"Reine",q:"lieu où elle est enterrée",x:"Reine de Castille qui achève la Reconquista en 1492. Elle repose avec son époux Ferdinand dans un sanctuaire royal de la dernière ville musulmane conquise, au pied d'un palais nasride.",e:"La chapelle royale de Grenade, accolée à la cathédrale, abrite les tombeaux d'Isabelle et de Ferdinand, ainsi que ceux de leur fille Jeanne la Folle et de son époux.",p:"Chapelle royale de Grenade, Grenade, Espagne",a:37.176,o:-3.599},
{n:3,k:"vie",t:"Lawrence d'Arabie",w:"Thomas Edward Lawrence",c:"Officier",q:"ville qu'il prend en 1917",x:"Officier britannique de la révolte arabe. En juillet 1917, après une traversée du désert, il s'empare avec les tribus arabes d'un port ottoman au fond d'un golfe de la mer Rouge, en l'attaquant par la terre.",e:"La prise d'Aqaba, aujourd'hui seul port de la Jordanie, est l'une des grandes scènes du film Lawrence d'Arabie de David Lean.",p:"Aqaba, Jordanie",a:29.53,o:35.005},
{n:3,t:"Dwight D. Eisenhower",c:"Général",x:"Commandant suprême des forces alliées lors du débarquement de juin 1944, puis président des États-Unis de 1953 à 1961.",e:"Il est né au Texas, mais a grandi dans le Kansas.",p:"Denison, Texas, États-Unis",a:33.7557,o:-96.5367},
{n:3,k:"vie",t:"Horatio Nelson",c:"Amiral",q:"lieu où il est enterré",x:"Amiral borgne et manchot, tué en 1805 lors de sa plus grande victoire navale. Son corps, ramené dans un tonneau d'eau-de-vie, repose dans la crypte du grand sanctuaire baroque de la capitale, sous le dôme de Christopher Wren.",e:"Il repose dans la crypte de la cathédrale Saint-Paul de Londres, non loin du duc de Wellington, le vainqueur de Waterloo.",p:"Cathédrale Saint-Paul, Londres, Royaume-Uni",a:51.5138,o:-0.0984},
{n:3,t:"Arthur Wellesley de Wellington",w:"Arthur Wellesley de Wellington",c:"Général",x:"Général britannique qui bat Napoléon à Waterloo en 1815, puis devient Premier ministre.",e:"Ce symbole de l'Angleterre est né en Irlande, dans une famille anglo-irlandaise.",p:"Dublin, Irlande",a:53.3331,o:-6.2489},
{n:3,t:"Marie Stuart",c:"Reine",x:"Reine d'Écosse dès l'âge de six jours, brièvement reine de France, puis exécutée en 1587 sur ordre d'Élisabeth Ire.",e:"Elle est née au palais de Linlithgow, entre Édimbourg et Stirling.",p:"Linlithgow, Royaume-Uni",a:55.9771,o:-3.6005},
{n:3,t:"Emiliano Zapata",c:"Révolutionnaire",x:"Chef paysan de la révolution mexicaine, au cri de « Terre et liberté », assassiné en 1919.",e:"Il est né dans un village de l'État de Morelos, au sud de la capitale.",p:"Anenecuilco, Morelos, Mexique",a:18.77,o:-98.98},
{n:3,k:"vie",t:"Lakshmi Bai",c:"Reine",q:"ville de son royaume",x:"Reine d'un petit royaume du nord de l'Inde, elle prend les armes en 1857 contre la Compagnie britannique des Indes, qui voulait annexer ses terres, et devient une héroïne nationale. Sa forteresse domine une ville du Bundelkhand.",e:"Rani de Jhansi, elle défend le fort de la ville en 1858 avant de mourir au combat près de Gwalior.",p:"Jhansi, Inde",a:25.4484,o:78.5685},
{n:3,k:"vie",t:"Tipu Sultan",c:"Sultan",q:"capitale où il meurt",x:"Souverain du Mysore surnommé « le Tigre ». Il meurt en 1799 en défendant contre les Britanniques sa capitale fortifiée, bâtie sur une île de la rivière Kaveri.",e:"Srirangapatna, près de Mysore, conserve son palais d'été et son mausolée, le Gumbaz, où il repose près de son père Haïdar Ali.",p:"Srirangapatna, Inde",a:12.42,o:76.695},
{n:3,k:"vie",t:"Jean Moulin",c:"Résistant",q:"lieu où il repose",x:"Chef de la Résistance intérieure, mort en 1943 après son arrestation. Ses cendres présumées sont transférées en 1964 dans un monument de la montagne Sainte-Geneviève, lors d'un discours célèbre d'André Malraux.",e:"Au Panthéon, à Paris, Malraux lance : « Entre ici, Jean Moulin, avec ton terrible cortège ».",p:"Panthéon, Paris, France",a:48.8462,o:2.3464},
]);

/* ---- Criminels célèbres : gangsters, escrocs, pirates, grandes affaires (présentés de façon factuelle) ---- */
ajouter('crime', 'perso', [
{n:1,t:"Al Capone",c:"Gangster",x:"Chef de la pègre de Chicago pendant la Prohibition, il est finalement condamné en 1931 non pour ses crimes violents mais pour fraude fiscale.",e:"Fils d'immigrés italiens, il est né et a grandi à New York avant de partir pour Chicago.",p:"Brooklyn, New York, États-Unis",a:40.6782,o:-73.9442},
{n:1,t:"Pablo Escobar",c:"Trafiquant",x:"Chef du cartel de Medellín, responsable d'une vague d'attentats et d'assassinats, tué par la police en 1993.",e:"Il est né dans une ville proche de Medellín, où se trouve aujourd'hui l'aéroport international de la région.",p:"Rionegro, Colombie",a:6.1551,o:-75.3737},
{n:1,k:"evt",t:"Jack l'Éventreur",c:"Affaire non élucidée",q:"lieu des crimes",x:"Surnom d'un tueur jamais identifié qui assassine au moins cinq femmes en 1888 dans un quartier pauvre d'une grande capitale.",e:"Les meurtres ont eu lieu dans le quartier de Whitechapel, dans l'East End, et ont profondément marqué la presse de l'époque.",p:"Whitechapel, Londres, Royaume-Uni",a:51.5165,o:-0.0675},
{n:1,k:"evt",t:"Massacre de la Saint-Valentin",c:"Guerre des gangs",q:"lieu du massacre",x:"Le 14 février 1929, sept hommes d'un gang rival sont abattus dans un garage par des tueurs déguisés en policiers, sur ordre présumé d'Al Capone.",e:"Le massacre a eu lieu dans le quartier de Lincoln Park et a retourné l'opinion contre les gangsters.",p:"Chicago, Illinois, États-Unis",a:41.9213,o:-87.6342},
{n:1,t:"Bonnie Parker",c:"Hors-la-loi",x:"Avec son compagnon Clyde Barrow, elle forme un duo de braqueurs qui sillonne le centre des États-Unis pendant la Grande Dépression, jusqu'à leur mort dans une embuscade en 1934.",e:"Elle est née dans un petit village du Texas, puis a grandi dans la banlieue de Dallas.",p:"Rowena, Texas, États-Unis",a:31.6476,o:-99.8467},
{n:1,t:"Jesse James",c:"Hors-la-loi",x:"Ancien guérillero sudiste devenu pilleur de banques et de trains, abattu en 1882 par un membre de sa propre bande.",e:"Il est né dans une ferme du comté de Clay, dans le Missouri, aujourd'hui transformée en musée.",p:"Kearney, Missouri, États-Unis",a:39.3672,o:-94.3624},
{n:1,k:"evt",t:"Vol des joyaux de la Couronne (2025)",w:"Galerie d'Apollon",c:"Vol d'œuvres d'art",q:"lieu du vol",x:"Le 19 octobre 2025, en plein jour, des voleurs montent par un monte-charge jusqu'à une fenêtre d'un grand musée et emportent en quelques minutes des bijoux historiques.",e:"Le vol a eu lieu dans la galerie d'Apollon du musée du Louvre, à Paris, qui expose les joyaux de la Couronne de France.",p:"Musée du Louvre, Paris, France",a:48.8603,o:2.3388},
{n:2,t:"Charles Ponzi",c:"Escroc",x:"Escroc qui promet en 1920 des rendements de 50 % en 45 jours, payés avec l'argent des nouveaux investisseurs. Son nom désigne depuis ce type de fraude.",e:"Il est né en Émilie-Romagne et a émigré aux États-Unis en 1903.",p:"Lugo, Italie",a:44.4214,o:11.9109},
{n:2,t:"Bernard Madoff",c:"Escroc",x:"Ancien président du Nasdaq, auteur de la plus grande escroquerie financière connue, révélée en 2008, dont les pertes se chiffrent en dizaines de milliards de dollars.",e:"Il est né et a grandi dans l'arrondissement new-yorkais du Queens.",p:"Queens, New York, États-Unis",a:40.7282,o:-73.7949},
{n:2,t:"Ned Kelly",c:"Hors-la-loi",x:"Bushranger qui affronte la police en 1880 vêtu d'une armure de fer artisanale. Il est pendu la même année et devient une figure de légende dans son pays.",e:"Il est né dans un village au nord de Melbourne, fils d'un ancien bagnard irlandais.",p:"Beveridge, Victoria, Australie",a:-37.48,o:144.98},
{n:2,t:"Jacques Mesrine",c:"Braqueur",x:"Braqueur multirécidiviste des années 1960 et 1970, célèbre pour ses évasions, déclaré « ennemi public numéro un » et abattu par la police en 1979.",e:"Il est né dans une commune de la banlieue nord-ouest de Paris.",p:"Clichy, France",a:48.9002,o:2.3095},
{n:2,t:"Joaquín Guzmán",w:"Joaquín Guzmán Loera",c:"Trafiquant",x:"Surnommé « El Chapo », chef du cartel de Sinaloa, évadé deux fois de prisons de haute sécurité, condamné à la prison à perpétuité aux États-Unis en 2019.",e:"Il est né dans un hameau de montagne de la municipalité de Badiraguato, dans la Sierra Madre occidentale.",p:"La Tuna, Badiraguato, Mexique",a:25.3618,o:-107.5507},
{n:2,k:"evt",t:"Attaque du train postal Glasgow-Londres",c:"Braquage",q:"lieu de l'attaque",x:"En août 1963, une bande arrête un train postal de nuit en trafiquant un signal et s'empare de 2,6 millions de livres, un record à l'époque.",e:"L'attaque a eu lieu au pont de Bridego, dans le Buckinghamshire, à environ 60 km de Londres.",p:"Pont de Bridego, Buckinghamshire, Royaume-Uni",a:51.884,o:-0.682},
{n:2,t:"Charles Manson",c:"Chef de secte",x:"Chef d'une secte dont des membres commettent plusieurs meurtres en 1969 en Californie, dont celui de l'actrice Sharon Tate. Il meurt en prison en 2017.",e:"Il est né dans l'Ohio, d'une mère de 16 ans, et a passé une grande partie de sa jeunesse en maison de correction.",p:"Cincinnati, Ohio, États-Unis",a:39.1271,o:-84.5144},
{n:2,k:"evt",t:"Vol au musée Isabella Stewart Gardner",c:"Vol d'œuvres d'art",q:"lieu du vol",x:"En mars 1990, deux hommes déguisés en policiers volent treize œuvres, dont un Vermeer et des Rembrandt. Aucune n'a été retrouvée.",e:"Le musée, à Boston, expose toujours les cadres vides à l'emplacement des tableaux volés.",p:"Boston, Massachusetts, États-Unis",a:42.3382,o:-71.0991},
{n:3,t:"Lucky Luciano",c:"Mafieux",x:"Il organise dans les années 1930 la mafia new-yorkaise en « commission » de familles. Condamné en 1936, il est expulsé vers son pays natal après la guerre.",e:"Il est né dans un village minier de Sicile, au sud de Palerme.",p:"Lercara Friddi, Sicile, Italie",a:37.747,o:13.603},
{n:3,t:"Eugène-François Vidocq",c:"Bagnard devenu policier",x:"Ancien bagnard évadé plusieurs fois, il fonde en 1812 la brigade de sûreté et inspire Victor Hugo et Balzac.",e:"Il est né dans le chef-lieu de l'Artois, comme Robespierre.",p:"Arras, France",a:50.293,o:2.7819},
{n:3,t:"Louis Mandrin",c:"Contrebandier",x:"Contrebandier du XVIIIe siècle qui défie les fermiers généraux chargés de collecter les impôts. Il est roué vif à Valence en 1755.",e:"Il est né dans un bourg du Dauphiné, entre Lyon et Grenoble.",p:"Saint-Étienne-de-Saint-Geoirs, France",a:45.339,o:5.346},
{n:3,t:"Henry Morgan",c:"Pirate",x:"Flibustier gallois qui pille Panama en 1671, puis devient lieutenant-gouverneur de la Jamaïque, chargé de combattre la piraterie.",e:"Il est né à Llanrumney, aujourd'hui un quartier de la capitale galloise.",p:"Llanrumney, Cardiff, Royaume-Uni",a:51.52,o:-3.13},
{n:3,t:"Barberousse",w:"Khayr ad-Din Barberousse",c:"Corsaire",x:"Corsaire devenu grand amiral de la flotte ottomane, il domine la Méditerranée au XVIe siècle et remporte la bataille de Préveza en 1538.",e:"Il est né sur une île de la mer Égée, aujourd'hui grecque.",p:"Lesbos, Grèce",a:39.1077,o:26.5553},
{n:3,t:"Bartholomew Roberts",c:"Pirate",x:"Pirate gallois du début du XVIIIe siècle qui aurait capturé plus de 400 navires, tué au combat au large du Gabon en 1722.",e:"Il est né dans un village du Pembrokeshire, à la pointe ouest du pays de Galles.",p:"Casnewydd-Bach, pays de Galles, Royaume-Uni",a:51.93,o:-4.95},
{n:3,t:"John Dillinger",c:"Braqueur",x:"Braqueur de banques désigné « ennemi public numéro un » par le FBI, abattu en 1934 à la sortie d'un cinéma de Chicago.",e:"Il est né dans la capitale de l'Indiana.",p:"Indianapolis, Indiana, États-Unis",a:39.7684,o:-86.158},
{n:3,t:"Butch Cassidy",c:"Hors-la-loi",x:"Chef de la « Wild Bunch », bande de pilleurs de trains, parti en Amérique du Sud avec le Sundance Kid, où il serait mort en 1908.",e:"Il est né dans une famille mormone d'une petite ville de l'Utah.",p:"Beaver, Utah, États-Unis",a:38.2769,o:-112.6411},
{n:3,t:"Dick Turpin",c:"Bandit de grand chemin",x:"Voleur de chevaux et bandit de grand chemin pendu à York en 1739, dont la légende a fait un héros romantique.",e:"Il est né dans un village de l'Essex, fils d'un aubergiste.",p:"Hempstead, Essex, Royaume-Uni",a:52.006,o:0.391},
{n:3,t:"Victor Lustig",c:"Escroc",x:"Escroc qui aurait réussi à « vendre » la tour Eiffel à un ferrailleur en 1925. Il a aussi écoulé de la fausse monnaie aux États-Unis.",e:"Il est né en Bohême, alors dans l'Empire austro-hongrois.",p:"Hostinné, Tchéquie",a:50.54,o:15.723},
{n:3,t:"Nick Leeson",c:"Trader",x:"Trader dont les pertes cachées, plus de 800 millions de livres, provoquent en 1995 la faillite de la plus vieille banque d'affaires britannique, la Barings.",e:"Il est né dans une ville de la banlieue nord-ouest de Londres, fils d'un plâtrier.",p:"Watford, Royaume-Uni",a:51.6553,o:-0.396},
{n:3,t:"Jérôme Kerviel",c:"Trader",x:"Trader condamné pour des prises de position cachées qui ont fait perdre 4,9 milliards d'euros à sa banque, révélées en 2008.",e:"Il est né dans une petite ville du Finistère, dans le pays bigouden.",p:"Pont-l'Abbé, France",a:47.8667,o:-4.2228},
{n:3,t:"Charles Sobhraj",c:"Tueur en série",x:"Escroc et meurtrier qui s'en prend aux voyageurs de la « route des hippies » dans les années 1970. Il a été emprisonné en Inde puis au Népal.",e:"Il est né d'un père indien et d'une mère vietnamienne, dans une ville alors en Indochine française.",p:"Saïgon (Hô Chi Minh-Ville), Viêt Nam",a:10.823,o:106.6296},
{n:3,k:"evt",t:"Casse du siècle (1976)",w:"Casse de la Société générale de Nice",c:"Braquage",q:"lieu du casse",x:"En juillet 1976, une équipe menée par Albert Spaggiari creuse un tunnel depuis les égouts pour vider la salle des coffres d'une banque.",e:"Le casse a eu lieu à Nice ; les voleurs auraient laissé l'inscription « Sans armes, ni haine, ni violence ».",p:"Nice, France",a:43.6992,o:7.2683},
{n:3,k:"evt",t:"Vol de la Banque centrale du Brésil (2005)",w:"Vol de la Banque centrale du Brésil",c:"Braquage",q:"lieu du casse",x:"En août 2005, des voleurs creusent un tunnel de près de 80 mètres depuis une maison louée pour vider une agence de la banque centrale de 164 millions de reais.",e:"Le vol a eu lieu dans une grande ville côtière du Nordeste, à Fortaleza.",p:"Fortaleza, Brésil",a:-3.727,o:-38.527},
{n:3,k:"evt",t:"Enlèvement du bébé Lindbergh",c:"Affaire criminelle",q:"lieu de l'enlèvement",x:"En mars 1932, le fils de 20 mois de l'aviateur Charles Lindbergh est enlevé dans la maison familiale. L'affaire mène à une loi fédérale sur les enlèvements.",e:"La maison des Lindbergh se trouvait près de Hopewell, dans le New Jersey.",p:"Hopewell, New Jersey, États-Unis",a:40.43,o:-74.8},
{n:3,k:"evt",t:"Affaire du collier de la reine",c:"Escroquerie",q:"lieu de l'escroquerie",x:"En 1785, une aventurière fait acheter par un cardinal un collier de diamants soi-disant destiné à Marie-Antoinette. Le scandale ternit l'image de la reine.",e:"L'affaire a éclaté à la cour de Versailles ; la comtesse de La Motte a été marquée au fer rouge puis s'est évadée.",p:"Versailles, France",a:48.8049,o:2.1204},
{n:3,t:"Pierre-François Lacenaire",c:"Assassin",x:"Assassin et poète, guillotiné en 1836, dont le procès fascine le Paris romantique. Il inspire un personnage des Enfants du paradis.",e:"Il est né dans une commune de l'ouest lyonnais, dans une famille de commerçants.",p:"Francheville, France",a:45.736,o:4.763}
]);

/* ---- Culture et patrimoine : œuvres d'art, fêtes et traditions, mythes, littérature ---- */
ajouter('culture', 'oeuvre', [
{n:1,t:"La Joconde",c:"Peinture",x:"Portrait peint par Léonard de Vinci au début du XVIe siècle, célèbre pour son sourire énigmatique. Il est protégé derrière une vitre blindée.",e:"Le tableau est exposé au musée du Louvre, à Paris ; François Ier l'avait acquis après la mort du peintre en France.",p:"Musée du Louvre, Paris, France",a:48.8606,o:2.3376},
{n:1,t:"David (Michel-Ange)",c:"Sculpture",x:"Statue de marbre de plus de cinq mètres achevée en 1504, représentant le héros biblique avant son combat contre Goliath.",e:"L'original est conservé à la Galleria dell'Accademia de Florence ; une copie le remplace sur la place de la Seigneurie.",p:"Galleria dell'Accademia, Florence, Italie",a:43.7768,o:11.2589},
{n:1,t:"Plafond de la chapelle Sixtine",w:"Plafond de la chapelle Sixtine",c:"Fresque",x:"Michel-Ange le peint entre 1508 et 1512, perché sur un échafaudage ; la scène de la Création d'Adam en est le détail le plus célèbre.",e:"La chapelle se trouve au Vatican ; c'est là que se réunissent les cardinaux pour élire le pape.",p:"Cité du Vatican",a:41.9029,o:12.4545},
{n:1,k:"evt",t:"Oktoberfest",c:"Fête populaire",q:"lieu de la fête",x:"Fête de la bière créée en 1810 pour célébrer un mariage royal, qui attire chaque année environ six millions de visiteurs.",e:"Elle se tient sur la Theresienwiese, à Munich, de la fin septembre au début d'octobre.",p:"Munich, Allemagne",a:48.1316,o:11.5498},
{n:1,k:"evt",t:"Hajj",c:"Pèlerinage",q:"lieu du pèlerinage",x:"Grand pèlerinage annuel de l'islam, que tout musulman qui le peut doit accomplir au moins une fois dans sa vie. Il réunit environ deux millions de fidèles.",e:"Il a lieu à La Mecque et dans ses environs, autour de la Kaaba.",p:"La Mecque, Arabie saoudite",a:21.4225,o:39.8262},
{n:1,k:"recit",t:"Roméo et Juliette",c:"Théâtre",q:"ville où se déroule la pièce",x:"Tragédie de Shakespeare sur deux jeunes amants issus de familles ennemies, les Montaigu et les Capulet.",e:"La pièce se déroule à Vérone, où l'on visite aujourd'hui la « maison de Juliette » et son balcon.",p:"Vérone, Italie",a:45.4384,o:10.9916},
{n:1,k:"recit",t:"Cheval de Troie",c:"Mythologie",q:"lieu associé à la légende",x:"Ruse grecque racontée dans l'Odyssée et l'Énéide : des soldats cachés dans un grand cheval de bois pénètrent dans la cité assiégée.",e:"Le site de Troie, fouillé par Heinrich Schliemann à partir de 1871, se trouve sur la colline d'Hisarlik, en Turquie.",p:"Hisarlik, Turquie",a:39.9575,o:26.2389},
{n:1,k:"recit",t:"Romulus et Rémus",c:"Mythologie",q:"lieu associé à la légende",x:"Jumeaux abandonnés et allaités par une louve ; selon la légende, l'un d'eux fonde une cité en 753 av. J.-C. après avoir tué son frère.",e:"La légende situe la fondation de Rome sur le mont Palatin.",p:"Rome, Italie",a:41.8892,o:12.4875},
{n:1,k:"evt",t:"Palme d'or",c:"Cinéma",q:"ville du festival",x:"Récompense suprême d'un festival de cinéma créé après la Seconde Guerre mondiale, remise chaque année en mai.",e:"Elle est décernée au palais des Festivals de Cannes, sur la Croisette.",p:"Cannes, France",a:43.551,o:7.017},
{n:1,k:"evt",t:"Carnaval des écoles de samba",w:"Carnaval de Rio de Janeiro",c:"Fête populaire",q:"lieu du défilé",x:"Chaque année avant le Carême, des écoles de samba rivalisent dans un défilé géant jugé par un jury, devant des dizaines de milliers de spectateurs.",e:"Le défilé a lieu dans le Sambodrome conçu par Oscar Niemeyer, à Rio de Janeiro.",p:"Sambodrome, Rio de Janeiro, Brésil",a:-22.9118,o:-43.1966},
{n:2,k:"perso",t:"Confucius",c:"Philosophie",x:"Philosophe du VIe siècle av. J.-C. dont les Entretiens ont marqué plus de deux millénaires de pensée.",e:"Qufu, dans la province du Shandong, abrite le temple de Confucius, la demeure de ses descendants et le cimetière familial, classés au patrimoine mondial.",p:"Qufu, Chine",a:35.581,o:116.986},
{n:2,t:"Le Cri",c:"Peinture",x:"Tableau expressionniste d'Edvard Munch montrant une silhouette hurlante sous un ciel rouge. Il en existe plusieurs versions.",e:"La version peinte de 1893 est conservée au Musée national d'Oslo ; d'autres sont au musée Munch, dans la même ville.",p:"Oslo, Norvège",a:59.911,o:10.734},
{n:2,t:"La Nuit étoilée",c:"Peinture",x:"Tableau de Vincent van Gogh peint en 1889 depuis sa chambre d'asile en Provence, avec un ciel tourbillonnant au-dessus d'un village.",e:"Il est exposé au Museum of Modern Art (MoMA) de New York depuis 1941.",p:"MoMA, New York, États-Unis",a:40.7614,o:-73.9776},
{n:2,t:"Guernica (Picasso)",w:"Guernica (tableau)",c:"Peinture",x:"Immense toile en noir et blanc peinte par Picasso en 1937 après le bombardement d'une petite ville basque pendant la guerre civile.",e:"Le tableau n'est revenu en Espagne qu'en 1981, après la fin du franquisme ; il est au musée Reina Sofía de Madrid.",p:"Musée Reina Sofía, Madrid, Espagne",a:40.408,o:-3.6945},
{n:2,t:"La Jeune Fille à la perle",c:"Peinture",x:"Portrait de Vermeer peint vers 1665, montrant une jeune fille au turban bleu qui se retourne vers le spectateur.",e:"Il est conservé au Mauritshuis, à La Haye, aux Pays-Bas.",p:"Mauritshuis, La Haye, Pays-Bas",a:52.0804,o:4.3143},
{n:2,t:"La Naissance de Vénus",c:"Peinture",x:"Tableau de Botticelli peint vers 1485, montrant la déesse debout sur une coquille, poussée vers le rivage par les vents.",e:"Il est exposé à la galerie des Offices, à Florence.",p:"Galerie des Offices, Florence, Italie",a:43.7678,o:11.2553},
{n:2,t:"Le Baiser (Klimt)",w:"Le Baiser (Klimt)",c:"Peinture",x:"Tableau couvert de feuilles d'or peint en 1907-1908, montrant un couple enlacé, emblème de la Sécession viennoise.",e:"Il est conservé au palais du Belvédère, à Vienne.",p:"Palais du Belvédère, Vienne, Autriche",a:48.1915,o:16.3809},
{n:2,t:"La Cène (Léonard de Vinci)",w:"La Cène (Léonard de Vinci)",c:"Peinture murale",x:"Peinture murale de la fin du XVe siècle représentant le dernier repas du Christ avec ses apôtres, peinte sur le mur d'un réfectoire.",e:"Elle se trouve dans le couvent de Santa Maria delle Grazie, à Milan ; les visites sont limitées à quelques minutes.",p:"Santa Maria delle Grazie, Milan, Italie",a:45.4659,o:9.1709},
{n:2,t:"La Ronde de nuit",c:"Peinture",x:"Immense tableau de Rembrandt achevé en 1642, montrant une compagnie de milice bourgeoise en mouvement.",e:"Il est le joyau du Rijksmuseum d'Amsterdam.",p:"Rijksmuseum, Amsterdam, Pays-Bas",a:52.36,o:4.8852},
{n:2,t:"Buste de Néfertiti",c:"Sculpture",x:"Buste en calcaire peint d'une reine égyptienne, vieux d'environ 3 350 ans, découvert en 1912 par une équipe allemande.",e:"Il est exposé au Neues Museum de Berlin ; l'Égypte réclame son retour.",p:"Neues Museum, Berlin, Allemagne",a:52.5205,o:13.3977},
{n:2,t:"Pierre de Rosette",c:"Archéologie",x:"Stèle portant le même décret en trois écritures, dont les hiéroglyphes, découverte en 1799 par des soldats de l'expédition de Bonaparte.",e:"Elle est exposée au British Museum, à Londres, depuis 1802.",p:"British Museum, Londres, Royaume-Uni",a:51.5194,o:-0.127},
{n:2,t:"Tapisserie de la reine Mathilde",w:"Tapisserie de Bayeux",c:"Broderie",x:"Broderie de près de 70 mètres réalisée au XIe siècle, qui raconte la conquête de l'Angleterre par Guillaume le Conquérant.",e:"Elle est conservée à Bayeux, en Normandie, d'où son autre nom.",p:"Bayeux, France",a:49.2747,o:-0.7007},
{n:2,k:"evt",t:"Fêtes de San Fermín",w:"Fêtes de San Fermín",c:"Fête populaire",q:"lieu de la fête",x:"Fêtes de juillet rendues célèbres par Hemingway, où des coureurs vêtus de blanc et rouge courent devant des taureaux dans les rues.",e:"Elles ont lieu à Pampelune, en Navarre, du 6 au 14 juillet.",p:"Pampelune, Espagne",a:42.8169,o:-1.6432},
{n:2,k:"evt",t:"La Tomatina",c:"Fête populaire",q:"lieu de la fête",x:"Chaque dernier mercredi d'août, des milliers de participants se lancent des tonnes de tomates mûres dans les rues d'un village.",e:"Elle a lieu à Buñol, près de Valence, depuis 1945.",p:"Buñol, Espagne",a:39.42,o:-0.79},
{n:2,k:"evt",t:"Fête des Lumières",c:"Fête populaire",q:"lieu de la fête",x:"Fête de décembre où les habitants posent des lumignons à leurs fenêtres, en souvenir de l'inauguration d'une statue de la Vierge en 1852.",e:"Elle a lieu à Lyon autour du 8 décembre, avec des illuminations sur les monuments.",p:"Lyon, France",a:45.764,o:4.8357},
{n:2,k:"evt",t:"Burning Man",c:"Festival",q:"lieu du festival",x:"Rassemblement artistique où une ville éphémère est construite chaque été, et où une grande effigie en bois est brûlée à la fin.",e:"Il se tient dans le désert de Black Rock, au Nevada.",p:"Désert de Black Rock, Nevada, États-Unis",a:40.7864,o:-119.2065},
{n:2,k:"evt",t:"Chemins de Saint-Jacques",w:"Chemins de Compostelle",c:"Pèlerinage",q:"ville d'arrivée",x:"Réseau d'itinéraires de pèlerinage parcourus depuis le Moyen Âge à pied, symbolisés par une coquille, vers le tombeau supposé d'un apôtre.",e:"Ils mènent à la cathédrale de Saint-Jacques-de-Compostelle, en Galice.",p:"Saint-Jacques-de-Compostelle, Espagne",a:42.8806,o:-8.5446},
{n:2,k:"recit",t:"Minotaure",c:"Mythologie",q:"lieu associé à la légende",x:"Créature mi-homme mi-taureau enfermée dans un labyrinthe construit par Dédale, et tuée par Thésée grâce au fil d'Ariane.",e:"La légende est associée au palais de Cnossos, en Crète, dont le plan complexe a pu inspirer le mythe du labyrinthe.",p:"Cnossos, Crète, Grèce",a:35.298,o:25.1631},
{n:2,k:"recit",t:"Tour de Babel",c:"Mythologie",q:"cité associée au récit",x:"Selon la Bible, les hommes voulurent bâtir une tour jusqu'au ciel ; Dieu les punit en confondant leurs langues.",e:"Le récit est associé à la ville antique de Babylone, en Mésopotamie, et peut-être à sa grande ziggourat.",p:"Babylone, Irak",a:32.5363,o:44.4209},
{n:2,k:"recit",t:"Hamlet",c:"Théâtre",q:"château où se déroule la pièce",x:"Tragédie de Shakespeare dans laquelle un prince venge son père assassiné par son oncle. On y entend « Être ou ne pas être ».",e:"La pièce se déroule au château d'Elseneur, le château de Kronborg à Helsingør, au Danemark.",p:"Château de Kronborg, Helsingør, Danemark",a:56.039,o:12.6213},
{n:2,k:"recit",t:"Le Comte de Monte-Cristo",c:"Roman",q:"lieu où le héros est emprisonné",x:"Roman d'Alexandre Dumas : Edmond Dantès, emprisonné à tort pendant quatorze ans, s'évade et se venge sous une nouvelle identité.",e:"Dantès est enfermé au château d'If, une forteresse sur un îlot face au Vieux-Port de Marseille.",p:"Château d'If, Marseille, France",a:43.2799,o:5.3253},
{n:2,k:"recit",t:"Don Quichotte",c:"Roman",q:"région où se déroule l'histoire",x:"Roman de Cervantès dont le héros, un hidalgo nourri de romans de chevalerie, part en quête d'aventures avec Sancho Panza et charge des moulins à vent.",e:"Il se déroule dans la Manche, en Castille, célèbre pour ses moulins comme ceux de Campo de Criptana.",p:"La Manche, Espagne",a:39.4047,o:-3.125},
{n:2,k:"recit",t:"Le Fantôme de l'Opéra",c:"Roman",q:"lieu où se déroule l'histoire",x:"Roman de Gaston Leroux paru en 1910 : un génie défiguré, caché dans les sous-sols d'un théâtre, terrorise la troupe par amour pour une chanteuse.",e:"Il se déroule dans l'opéra Garnier, à Paris, dont les sous-sols abritent réellement un bassin d'eau.",p:"Opéra Garnier, Paris, France",a:48.872,o:2.3316},
{n:3,t:"Les Ménines",c:"Peinture",x:"Tableau de Velázquez peint en 1656, où l'artiste se représente lui-même en train de peindre, autour de l'infante Marguerite.",e:"Il est exposé au musée du Prado, à Madrid.",p:"Musée du Prado, Madrid, Espagne",a:40.4138,o:-3.6921},
{n:3,t:"American Gothic",c:"Peinture",x:"Tableau de Grant Wood peint en 1930, montrant un fermier tenant une fourche à côté d'une femme, devant une maison au pignon néogothique.",e:"Il est conservé à l'Art Institute of Chicago.",p:"Art Institute, Chicago, États-Unis",a:41.8796,o:-87.6237},
{n:3,t:"Masque d'Agamemnon",c:"Archéologie",x:"Masque funéraire en or découvert en 1876 par Heinrich Schliemann, qui crut y voir le visage du roi de l'Iliade.",e:"Il est exposé au musée national archéologique d'Athènes.",p:"Musée national archéologique, Athènes, Grèce",a:37.989,o:23.7322},
{n:3,t:"Vénus de Willendorf",c:"Archéologie",x:"Statuette féminine en calcaire d'environ 11 cm, sculptée il y a quelque 30 000 ans, découverte en 1908 au bord du Danube.",e:"Elle est conservée au musée d'Histoire naturelle de Vienne.",p:"Musée d'Histoire naturelle, Vienne, Autriche",a:48.2052,o:16.36},
{n:3,t:"La Dame à l'hermine",c:"Peinture",x:"Portrait de Léonard de Vinci peint vers 1490, représentant Cecilia Gallerani tenant un petit animal blanc.",e:"Il est exposé au musée Czartoryski, à Cracovie, en Pologne.",p:"Musée Czartoryski, Cracovie, Pologne",a:50.0647,o:19.9415},
{n:3,t:"Bronzes de Riace",c:"Sculpture",x:"Deux statues grecques de guerriers du Ve siècle av. J.-C., retrouvées en 1972 par un plongeur au fond de la mer.",e:"Elles sont exposées au musée archéologique national de Reggio de Calabre.",p:"Reggio de Calabre, Italie",a:38.113,o:15.649},
{n:3,t:"Bouddha d'émeraude",c:"Sculpture",x:"Statuette de pierre verte vêtue d'habits en or changés trois fois par an par le roi, selon les saisons. Elle est l'objet de culte le plus vénéré de son pays.",e:"Elle est conservée au Wat Phra Kaeo, dans l'enceinte du Grand Palais de Bangkok.",p:"Wat Phra Kaeo, Bangkok, Thaïlande",a:13.7516,o:100.4927},
{n:3,k:"evt",t:"Palio",w:"Palio de Sienne",c:"Fête populaire",q:"lieu de la fête",x:"Course de chevaux montés à cru, disputée deux fois par été entre les quartiers (contrade) d'une ville, sur une place en forme de coquille.",e:"Il se court sur la Piazza del Campo, à Sienne, en Toscane.",p:"Sienne, Italie",a:43.3184,o:11.3316},
{n:3,k:"evt",t:"Gion Matsuri",c:"Fête populaire",q:"lieu de la fête",x:"Grande fête de juillet née au IXe siècle pour apaiser une épidémie, célèbre pour son défilé de chars géants décorés.",e:"Elle a lieu à Kyoto, organisée par le sanctuaire Yasaka.",p:"Kyoto, Japon",a:35.0037,o:135.7788},
{n:3,k:"evt",t:"Inti Raymi",c:"Fête traditionnelle",q:"lieu de la fête",x:"Fête du Soleil célébrée par les Incas au solstice de juin, reconstituée chaque année depuis 1944.",e:"Elle a lieu à Cuzco, l'ancienne capitale inca, et sur l'esplanade de Sacsayhuamán.",p:"Sacsayhuamán, Cuzco, Pérou",a:-13.5097,o:-71.9822},
{n:3,k:"evt",t:"Hogmanay",c:"Fête traditionnelle",q:"lieu de la fête",x:"Nom écossais du réveillon du Nouvel An, célébré avec des processions aux flambeaux et le chant « Auld Lang Syne ».",e:"Les plus grandes festivités ont lieu à Édimbourg, au pied du château.",p:"Édimbourg, Royaume-Uni",a:55.9533,o:-3.1883},
{n:3,k:"evt",t:"Festival international de sculpture sur glace",w:"Festival international de sculpture sur glace et neige de Harbin",c:"Festival",q:"lieu du festival",x:"Chaque hiver, des palais et sculptures géantes sont taillés dans des blocs de glace d'un fleuve, illuminés la nuit par des températures de −20 °C.",e:"Il a lieu à Harbin, dans le nord-est de la Chine, sur les rives du Songhua.",p:"Harbin, Chine",a:45.78,o:126.57},
{n:3,k:"recit",t:"Golem",c:"Légende",q:"lieu associé à la légende",x:"Selon une légende juive, un rabbin du XVIe siècle façonne une créature d'argile pour protéger sa communauté.",e:"La légende est associée au rabbin Loew et à la synagogue Vieille-Nouvelle de Prague.",p:"Prague, Tchéquie",a:50.0903,o:14.4185},
{n:3,k:"recit",t:"Épopée de Gilgamesh",c:"Mythologie",q:"cité dont le héros est roi",x:"L'un des plus anciens récits écrits connus, sur des tablettes d'argile, racontant la quête d'immortalité d'un roi après la mort de son ami Enkidu.",e:"Gilgamesh est présenté comme le roi d'Uruk, en Mésopotamie, dans l'actuel Irak.",p:"Uruk, Irak",a:31.3226,o:45.6375},
{n:3,k:"recit",t:"Mahabharata",c:"Mythologie",q:"lieu associé au récit",x:"Immense épopée sanskrite racontant la guerre entre deux branches d'une même famille, les Pandava et les Kaurava. Elle contient la Bhagavad-Gita.",e:"La grande bataille finale est située à Kurukshetra, au nord de Delhi.",p:"Kurukshetra, Inde",a:29.9695,o:76.8783},
{n:3,k:"recit",t:"Frankenstein",c:"Roman",q:"ville où l'on crée la créature",x:"Roman de Mary Shelley paru en 1818 : un jeune savant donne vie à une créature assemblée à partir de cadavres, puis l'abandonne.",e:"Victor Frankenstein crée sa créature pendant ses études à l'université d'Ingolstadt, en Bavière.",p:"Ingolstadt, Allemagne",a:48.7665,o:11.4258},
{n:3,k:"recit",t:"Le Vieil Homme et la Mer",c:"Roman",q:"lieu où se déroule l'histoire",x:"Court roman d'Hemingway, prix Pulitzer 1953 : un vieux pêcheur lutte seul pendant trois jours contre un marlin géant.",e:"L'histoire se déroule près de La Havane ; Hemingway s'est inspiré des pêcheurs du village de Cojímar.",p:"Cojímar, près de La Havane, Cuba",a:23.166,o:-82.295},
{n:3,k:"recit",t:"Ulysse (roman)",c:"Roman",q:"ville où se déroule le roman",x:"Roman de James Joyce paru en 1922, qui suit la journée du 16 juin 1904 de Leopold Bloom. Cette date est fêtée chaque année sous le nom de Bloomsday.",e:"Le roman se déroule entièrement à Dublin, en Irlande.",p:"Dublin, Irlande",a:53.3498,o:-6.2603},
{n:3,k:"recit",t:"L'Odyssée",c:"Mythologie",q:"île du héros",x:"Poème attribué à Homère qui raconte le retour d'Ulysse après la guerre de Troie, un voyage de dix ans semé d'embûches.",e:"Ulysse est roi d'Ithaque, île de la mer Ionienne identifiée à l'actuelle Ithaque.",p:"Ithaque, Grèce",a:38.43,o:20.67}
]);

/* ---- Événements historiques : guerres, révolutions, catastrophes, tournants politiques ---- */
ajouter('evt', 'evt', [
{n:1,t:"Prise de la Bastille",c:"Révolution",x:"Le 14 juillet 1789, des émeutiers s'emparent d'une forteresse-prison royale, symbole de l'arbitraire. La date deviendra fête nationale.",e:"La forteresse a été démolie dans les mois suivants ; une colonne se dresse aujourd'hui sur la place qui porte son nom, à Paris.",p:"Paris, France",a:48.8532,o:2.3692},
{n:1,t:"Opération Overlord",c:"Seconde Guerre mondiale",q:"lieu du débarquement",x:"Le 6 juin 1944, plus de 150 000 soldats alliés débarquent sur cinq plages pour ouvrir un front à l'ouest de l'Europe.",e:"Le débarquement a eu lieu en Normandie, sur les plages baptisées Utah, Omaha, Gold, Juno et Sword.",p:"Plage d'Omaha, Normandie, France",a:49.37,o:-0.87},
{n:1,t:"Attaque de Pearl Harbor",c:"Seconde Guerre mondiale",x:"Le 7 décembre 1941, l'aviation japonaise attaque par surprise une base navale américaine, ce qui fait entrer les États-Unis dans la guerre.",e:"La base se trouve sur l'île d'Oahu, à Hawaï, à près de 4 000 km de la Californie.",p:"Oahu, Hawaï, États-Unis",a:21.3649,o:-157.95},
{n:1,t:"Assassinat de John F. Kennedy",c:"Assassinat",x:"Le 22 novembre 1963, le président des États-Unis est tué par balle alors qu'il traverse une ville en voiture décapotable.",e:"Il a été tué sur Dealey Plaza, à Dallas, au Texas.",p:"Dallas, Texas, États-Unis",a:32.779,o:-96.8085},
{n:1,t:"Naufrage du Titanic",c:"Catastrophe",q:"lieu du naufrage",x:"Dans la nuit du 14 au 15 avril 1912, un paquebot réputé insubmersible heurte un iceberg lors de son voyage inaugural ; plus de 1 500 personnes périssent.",e:"L'épave repose par environ 3 800 mètres de fond, au sud-est de Terre-Neuve.",p:"Atlantique Nord, au large de Terre-Neuve",a:41.726,o:-49.948},
{n:1,t:"Accident nucléaire de 1986",w:"Catastrophe nucléaire de Tchernobyl",c:"Catastrophe",x:"Le 26 avril 1986, le réacteur n° 4 d'une centrale soviétique explose : c'est le pire accident nucléaire civil de l'histoire.",e:"La centrale de Tchernobyl se trouve en Ukraine, près de la frontière biélorusse ; la ville voisine de Pripiat a été abandonnée.",p:"Tchernobyl, Ukraine",a:51.3893,o:30.0989},
{n:1,t:"Déclaration d'indépendance des États-Unis",c:"Indépendance",x:"Le 4 juillet 1776, les représentants de treize colonies adoptent un texte qui proclame leur séparation de la Grande-Bretagne.",e:"Elle a été adoptée à l'Independence Hall de Philadelphie, alors la plus grande ville des colonies.",p:"Philadelphie, États-Unis",a:39.9489,o:-75.15},
{n:1,t:"Révolution d'Octobre",c:"Révolution",x:"En novembre 1917 (octobre selon l'ancien calendrier russe), les bolcheviks s'emparent du palais d'Hiver et prennent le pouvoir.",e:"Elle a eu lieu dans la capitale de l'époque, Petrograd, aujourd'hui Saint-Pétersbourg.",p:"Saint-Pétersbourg, Russie",a:59.9399,o:30.3146},
{n:1,t:"Attentats du 11 septembre 2001",c:"Terrorisme",x:"Quatre avions de ligne sont détournés ; deux d'entre eux frappent les tours jumelles du World Trade Center, qui s'effondrent.",e:"Les tours se dressaient dans le sud de Manhattan, à New York ; près de 3 000 personnes ont été tuées ce jour-là.",p:"New York, États-Unis",a:40.7115,o:-74.0134},
{n:1,t:"Chute de Constantinople",c:"Moyen Âge",x:"En 1453, les troupes ottomanes de Mehmed II prennent la capitale de l'Empire byzantin, ce qui marque traditionnellement la fin du Moyen Âge.",e:"La ville, rebaptisée Istanbul, est à cheval sur l'Europe et l'Asie, de part et d'autre du Bosphore.",p:"Istanbul, Turquie",a:41.0122,o:28.976},
{n:1,t:"Couronnement de Charlemagne",c:"Moyen Âge",x:"Le jour de Noël de l'an 800, le pape Léon III couronne le roi des Francs empereur d'Occident.",e:"La cérémonie a eu lieu dans l'ancienne basilique Saint-Pierre, à Rome.",p:"Rome, Italie",a:41.9022,o:12.4539},
{n:1,t:"Chute du Mur",w:"Chute du mur de Berlin",c:"Guerre froide",x:"Dans la nuit du 9 novembre 1989, après une annonce confuse, des milliers d'habitants de l'Est franchissent librement le mur qui coupait leur ville en deux depuis 1961.",e:"Le premier point de passage ouvert ce soir-là fut celui de la Bornholmer Straße, à Berlin.",p:"Berlin, Allemagne",a:52.5548,o:13.3978},
{n:2,t:"Bataille de Waterloo",c:"Bataille",x:"Le 18 juin 1815, Napoléon est vaincu par les armées de Wellington et de Blücher, ce qui met fin aux Cent-Jours.",e:"Le champ de bataille se trouve au sud de Bruxelles ; une butte surmontée d'un lion y a été élevée.",p:"Waterloo, Belgique",a:50.68,o:4.412},
{n:2,t:"Assassinat de l'archiduc François-Ferdinand",w:"Attentat de Sarajevo",c:"Assassinat",x:"Le 28 juin 1914, l'héritier du trône d'Autriche-Hongrie est abattu par un jeune nationaliste, Gavrilo Princip. C'est l'étincelle de la Première Guerre mondiale.",e:"L'attentat a eu lieu près du pont Latin, à Sarajevo, alors en Bosnie austro-hongroise.",p:"Sarajevo, Bosnie-Herzégovine",a:43.8578,o:18.429},
{n:2,t:"Armistice du 11 novembre 1918",w:"Armistice de 1918",c:"Première Guerre mondiale",x:"Il est signé à 5 h 15 dans un wagon-restaurant transformé en bureau, et entre en vigueur à 11 heures, mettant fin aux combats.",e:"Le wagon stationnait dans la forêt de Compiègne, à Rethondes ; Hitler y fit signer l'armistice de 1940 par revanche.",p:"Clairière de Rethondes, Compiègne, France",a:49.4275,o:2.9061},
{n:2,t:"Marche du sel",c:"Indépendance",q:"point d'arrivée de la marche",x:"En 1930, Gandhi et ses compagnons marchent 24 jours pour aller récolter du sel sur la côte, en défiant le monopole britannique.",e:"Partis de l'ashram de Sabarmati, à Ahmedabad, ils ont atteint la plage de Dandi, au Gujarat.",p:"Dandi, Gujarat, Inde",a:20.889,o:72.802},
{n:2,t:"Révolution des Œillets",c:"Révolution",x:"Le 25 avril 1974, un coup d'État militaire presque sans violence renverse la plus vieille dictature d'Europe occidentale. Des fleurs ornent les fusils.",e:"Elle a eu lieu à Lisbonne et a mis fin à l'Estado Novo et aux guerres coloniales du Portugal.",p:"Lisbonne, Portugal",a:38.7223,o:-9.1393},
{n:2,t:"Proclamation de la République populaire de Chine",c:"Révolution",x:"Le 1er octobre 1949, Mao Zedong proclame la naissance d'un nouveau régime du haut d'une porte monumentale.",e:"La proclamation a eu lieu à la porte Tian'anmen, à Pékin, où son portrait est toujours accroché.",p:"Pékin, Chine",a:39.9087,o:116.3975},
{n:2,t:"Séisme et tsunami de 2004",w:"Séisme de 2004 dans l'océan Indien",c:"Catastrophe",q:"épicentre du séisme",x:"Le 26 décembre 2004, un séisme de magnitude 9,1 provoque des vagues géantes qui frappent une douzaine de pays et font environ 230 000 morts.",e:"L'épicentre se trouvait au large de la côte ouest de Sumatra, en Indonésie, la région la plus touchée.",p:"Au large de Sumatra, Indonésie",a:3.316,o:95.854},
{n:2,t:"Accident nucléaire de 2011",w:"Accident nucléaire de Fukushima",c:"Catastrophe",x:"Le 11 mars 2011, un tsunami provoqué par un séisme majeur noie les systèmes de refroidissement d'une centrale, entraînant la fusion de trois cœurs.",e:"La centrale de Fukushima Daiichi est située sur la côte Pacifique, à environ 220 km au nord-est de Tokyo.",p:"Fukushima, Japon",a:37.4214,o:141.0325},
{n:2,t:"Festival de Woodstock",c:"Musique",x:"En août 1969, environ 400 000 personnes assistent à trois jours de concerts de rock, avec Jimi Hendrix et Janis Joplin. C'est le symbole de la contre-culture.",e:"Le festival n'a pas eu lieu à Woodstock mais à Bethel, dans une ferme laitière à environ 70 km de là.",p:"Bethel, New York, États-Unis",a:41.7011,o:-74.88},
{n:2,t:"Libération de Nelson Mandela",c:"Fin de l'apartheid",q:"prison d'où il sort",x:"Le 11 février 1990, après 27 ans de détention, le leader de l'ANC sort de prison à pied, le poing levé.",e:"Il est sorti de la prison Victor-Verster, près de Paarl, avant de prononcer son discours au Cap.",p:"Prison Victor-Verster, près de Paarl, Afrique du Sud",a:-33.78,o:18.95},
{n:2,t:"Bataille des Thermopyles",c:"Antiquité",x:"En 480 av. J.-C., le roi spartiate Léonidas et quelques milliers de Grecs retardent l'immense armée perse de Xerxès dans un étroit défilé.",e:"Le défilé se trouve en Grèce centrale, entre les montagnes et la mer ; son nom signifie « portes chaudes ».",p:"Thermopyles, Grèce",a:38.796,o:22.536},
{n:2,t:"Bataille de Trafalgar",c:"Bataille",x:"Le 21 octobre 1805, la flotte britannique de Nelson anéantit la flotte franco-espagnole. Nelson y est tué.",e:"La bataille a eu lieu au large d'un cap de la côte andalouse, entre Cadix et le détroit de Gibraltar.",p:"Au large du cap Trafalgar, Espagne",a:36.2,o:-6.2},
{n:2,t:"Bataille de Stalingrad",c:"Seconde Guerre mondiale",x:"De l'été 1942 à février 1943, l'Armée rouge résiste puis encercle la 6e armée allemande, dans l'une des batailles les plus meurtrières de l'histoire.",e:"La ville, sur la Volga, s'appelle aujourd'hui Volgograd.",p:"Volgograd, Russie",a:48.708,o:44.5133},
{n:2,t:"Capitulation du Japon",c:"Seconde Guerre mondiale",x:"Le 2 septembre 1945, les représentants japonais signent l'acte de capitulation à bord du cuirassé USS Missouri, ce qui met fin à la Seconde Guerre mondiale.",e:"Le cuirassé était ancré dans la baie de Tokyo.",p:"Baie de Tokyo, Japon",a:35.35,o:139.76},
{n:3,t:"Bataille d'Austerlitz",c:"Bataille",x:"Le 2 décembre 1805, Napoléon bat les armées russe et autrichienne, un an jour pour jour après son sacre. On l'appelle aussi « bataille des Trois Empereurs ».",e:"Le champ de bataille se trouve en Moravie, près de Brno ; la ville s'appelle aujourd'hui Slavkov u Brna.",p:"Slavkov u Brna, Tchéquie",a:49.13,o:16.76},
{n:3,t:"Bataille d'Adoua",c:"Bataille",x:"Le 1er mars 1896, l'armée de l'empereur Ménélik II écrase un corps expéditionnaire italien, garantissant l'indépendance de son pays.",e:"La bataille a eu lieu dans le nord de l'Éthiopie, dans la région du Tigré.",p:"Adoua, Éthiopie",a:14.1667,o:38.9},
{n:3,t:"Immolation de Mohamed Bouazizi",w:"Mohamed Bouazizi",c:"Printemps arabe",q:"lieu du déclenchement",x:"Le 17 décembre 2010, un jeune vendeur ambulant s'immole par le feu après la confiscation de sa marchandise. Son geste déclenche une révolution puis le Printemps arabe.",e:"Cela s'est passé à Sidi Bouzid, une ville du centre de la Tunisie.",p:"Sidi Bouzid, Tunisie",a:35.0382,o:9.4849},
{n:3,t:"Coup d'État du 11 septembre 1973",w:"Coup d'État de 1973 au Chili",c:"Coup d'État",x:"L'armée bombarde le palais présidentiel ; le président Salvador Allende s'y donne la mort. Commence une dictature de dix-sept ans.",e:"Le palais de La Moneda se trouve au centre de Santiago du Chili.",p:"Santiago, Chili",a:-33.4429,o:-70.6539},
{n:3,t:"Révolution de Velours",c:"Révolution",x:"En novembre 1989, des manifestations pacifiques massives mettent fin en quelques semaines au régime communiste ; un dramaturge dissident devient président.",e:"Le mouvement est parti d'une manifestation étudiante à Prague, en Tchécoslovaquie.",p:"Prague, Tchéquie",a:50.081,o:14.428},
{n:3,t:"Révolte des cipayes",c:"Révolte",q:"lieu du déclenchement",x:"En mai 1857, des soldats indiens au service de la Compagnie britannique se soulèvent, notamment à cause de cartouches graissées au suif de vache et de porc.",e:"La révolte a éclaté dans la garnison de Meerut, au nord-est de Delhi.",p:"Meerut, Inde",a:28.9845,o:77.7064},
{n:3,t:"Cri de Dolores",c:"Indépendance",x:"Dans la nuit du 15 au 16 septembre 1810, le prêtre Miguel Hidalgo appelle ses paroissiens à se soulever contre l'Espagne. La date est devenue fête nationale.",e:"L'appel a été lancé depuis l'église d'un petit bourg du Guanajuato, aujourd'hui appelé Dolores Hidalgo.",p:"Dolores Hidalgo, Mexique",a:21.1561,o:-100.9319},
{n:3,t:"Cri d'Ipiranga",c:"Indépendance",x:"Le 7 septembre 1822, le prince portugais Pierre proclame l'indépendance de la colonie dont il était régent, au bord d'un ruisseau.",e:"La scène se déroule au bord du ruisseau Ipiranga, aujourd'hui un quartier de São Paulo.",p:"São Paulo, Brésil",a:-23.585,o:-46.61},
{n:3,t:"Signature de la Charte des Nations unies",w:"Charte des Nations unies",c:"Diplomatie",x:"Le 26 juin 1945, les délégués de 50 pays signent le texte fondateur d'une organisation chargée de maintenir la paix mondiale.",e:"La Charte a été signée à San Francisco, à l'issue d'une conférence de deux mois.",p:"San Francisco, États-Unis",a:37.7793,o:-122.4193},
{n:3,t:"Déclaration universelle des droits de l'homme",c:"Diplomatie",x:"Le 10 décembre 1948, l'Assemblée générale de l'ONU adopte un texte rédigé notamment par René Cassin et Eleanor Roosevelt.",e:"Elle a été adoptée au palais de Chaillot, à Paris, face à la tour Eiffel.",p:"Paris, France",a:48.8625,o:2.2875},
{n:3,t:"Magna Carta",c:"Moyen Âge",x:"En juin 1215, le roi Jean sans Terre accepte, sous la pression de ses barons, une charte qui limite son pouvoir. C'est un texte fondateur des libertés anglaises.",e:"Elle a été scellée dans la prairie de Runnymede, au bord de la Tamise, à l'ouest de Londres.",p:"Runnymede, Royaume-Uni",a:51.444,o:-0.565},
{n:3,t:"Incident du pont Marco-Polo",c:"Seconde Guerre mondiale",x:"En juillet 1937, un accrochage entre troupes chinoises et japonaises près d'un pont du XIIe siècle déclenche la guerre sino-japonaise.",e:"Le pont se trouve au sud-ouest de Pékin, à Wanping.",p:"Pont Marco-Polo, Pékin, Chine",a:39.8494,o:116.2133},
{n:3,t:"Massacre de Jallianwala Bagh",w:"Massacre d'Amritsar",c:"Colonisation",x:"Le 13 avril 1919, des soldats britanniques tirent sans sommation sur une foule désarmée réunie dans un jardin clos, faisant des centaines de morts.",e:"Le jardin de Jallianwala Bagh se trouve à Amritsar, près du Temple d'or, au Pendjab.",p:"Amritsar, Inde",a:31.6206,o:74.8801},
{n:3,t:"Révolution haïtienne",c:"Révolution",q:"lieu du soulèvement",x:"En août 1791, des esclaves se soulèvent dans le nord d'une riche colonie sucrière ; l'insurrection aboutit en 1804 au premier État noir indépendant.",e:"Le soulèvement a été préparé lors de la cérémonie du Bois-Caïman, dans la plaine du Nord, près du Cap-Français.",p:"Plaine du Nord, Haïti",a:19.68,o:-72.27}
]);

/* ---- Sciences et inventions : savants, inventeurs, découvertes ---- */
ajouter('science', 'perso', [
{n:1,t:"Marie Curie",c:"Science",x:"Physicienne et chimiste, première personne à recevoir deux prix Nobel dans deux disciplines différentes. Elle a découvert le polonium et le radium.",e:"Elle est née à Varsovie, alors dans l'Empire russe, rue Freta, dans la Nouvelle Ville, où sa maison natale abrite aujourd'hui un musée.",p:"Varsovie, Pologne",a:52.2297,o:21.0122},
{n:1,k:"vie",t:"Albert Einstein",c:"Science",q:"ville de son « année miraculeuse »",x:"Physicien de la relativité, prix Nobel 1921. En 1905, simple employé de l'Office fédéral des brevets de la capitale suisse, il publie quatre articles qui révolutionnent la physique.",e:"Il vit alors avec sa femme et son fils dans un appartement de la Kramgasse, au cœur de la vieille ville de Berne, aujourd'hui transformé en musée, la maison d'Einstein.",p:"Maison d'Einstein, Berne, Suisse",a:46.9479,o:7.4508},
{n:1,k:"vie",t:"Bill Gates",c:"Entreprise",q:"ville où il fonde Microsoft",x:"Cofondateur de Microsoft. En 1975, il quitte Harvard et fonde avec Paul Allen sa société dans une ville du Nouveau-Mexique, pour être près du fabricant du micro-ordinateur Altair 8800.",e:"Microsoft naît à Albuquerque, où se trouvait l'entreprise MITS, puis s'installe en 1979 près de Seattle, la ville natale de Bill Gates.",p:"Albuquerque, Nouveau-Mexique, États-Unis",a:35.0844,o:-106.6504},
{n:1,t:"Léonard de Vinci",c:"Inventeur",x:"Peintre, ingénieur et inventeur de la Renaissance, auteur de carnets remplis de machines volantes et d'études anatomiques. Il meurt en France en 1519.",e:"Son nom signifie « de Vinci », le bourg de Toscane où il est né.",p:"Vinci, Italie",a:43.786,o:10.926},
{n:1,k:"vie",t:"Steve Jobs",c:"Entrepreneur",q:"garage où naît Apple",x:"Cofondateur d'Apple. En 1976, avec Steve Wozniak, il assemble les premiers ordinateurs Apple I dans le garage de la maison de ses parents adoptifs, dans une petite ville de la Silicon Valley.",e:"Le garage du 2066 Crist Drive, à Los Altos, a été classé site historique par la ville en 2013.",p:"Los Altos, Californie, États-Unis",a:37.3403,o:-122.0963},
{n:1,k:"vie",t:"Thomas Edison",c:"Inventeur",q:"lieu de son laboratoire",x:"Inventeur aux plus de mille brevets. En 1876, il ouvre dans un hameau du New Jersey un laboratoire de recherche où il invente le phonographe et une ampoule durable, ce qui lui vaut le surnom de « sorcier » de l'endroit.",e:"Le hameau de Menlo Park fait aujourd'hui partie d'une commune du New Jersey rebaptisée Edison en son honneur ; une tour surmontée d'une ampoule géante marque le site.",p:"Menlo Park, Edison, New Jersey, États-Unis",a:40.5583,o:-74.3367},
{n:1,k:"evt",t:"Apollo 11",c:"Conquête spatiale",q:"lieu du lancement",x:"Le 16 juillet 1969, une fusée Saturn V emporte trois astronautes vers la Lune ; deux d'entre eux y marchent quatre jours plus tard.",e:"La fusée a décollé du centre spatial Kennedy, en Floride.",p:"Centre spatial Kennedy, Floride, États-Unis",a:28.5729,o:-80.649},
{n:1,k:"vie",t:"Alexander Graham Bell",c:"Inventeur",q:"ville où il invente le téléphone",x:"Professeur pour sourds d'origine écossaise. Le 10 mars 1876, dans son laboratoire d'une grande ville de Nouvelle-Angleterre, il transmet la première phrase par téléphone : « Monsieur Watson, venez ici, je veux vous voir ».",e:"Bell enseigne alors à l'université de Boston ; c'est dans cette ville qu'il fonde en 1877 la compagnie dont naîtra AT&T.",p:"Boston, Massachusetts, États-Unis",a:42.3601,o:-71.0589},
{n:1,t:"Johannes Gutenberg",c:"Inventeur",x:"Orfèvre qui met au point vers 1450 l'imprimerie à caractères mobiles en métal en Europe, et imprime une célèbre Bible.",e:"Il est né dans une ville rhénane, où un musée de l'imprimerie porte son nom.",p:"Mayence, Allemagne",a:49.9819,o:8.2801},
{n:1,t:"Alfred Nobel",c:"Inventeur",x:"Chimiste inventeur de la dynamite en 1867, qui lègue sa fortune pour créer des prix récompensant les bienfaiteurs de l'humanité.",e:"Il est né dans la capitale de son pays, où les prix sont remis chaque année, sauf celui de la paix.",p:"Stockholm, Suède",a:59.3294,o:18.0687},
{n:2,k:"vie",t:"Charles Darwin",c:"Science",q:"maison où il a vécu",x:"Naturaliste du voyage du Beagle. De 1842 à sa mort en 1882, il vit dans une maison de campagne du Kent, au sud-est de Londres, où il écrit L'Origine des espèces.",e:"Down House, dans le village de Downe, est devenue un musée ; on peut y voir son bureau et le « chemin de réflexion » qu'il parcourait chaque jour.",p:"Down House, Downe, Royaume-Uni",a:51.3313,o:0.0532},
{n:2,t:"Galilée",w:"Galilée (savant)",c:"Science",x:"Astronome qui observe les lunes de Jupiter en 1610, puis est jugé par l'Inquisition pour avoir défendu l'héliocentrisme.",e:"Il est né à Pise, en Toscane, dont il fréquenta l'université ; la légende le montre lâchant des objets du haut de la tour penchée.",p:"Pise, Italie",a:43.7228,o:10.4017},
{n:2,t:"Elon Musk",c:"Entreprise",x:"Entrepreneur dirigeant Tesla et SpaceX. Il a grandi dans un pays d'Afrique avant de partir étudier en Amérique du Nord.",e:"Il est né à Pretoria, capitale administrative de l'Afrique du Sud, surnommée la « ville des jacarandas » pour ses arbres aux fleurs violettes.",p:"Pretoria, Afrique du Sud",a:-25.7479,o:28.2293},
{n:2,t:"Archimède",c:"Mathématicien",x:"Savant grec du IIIe siècle av. J.-C. connu pour son principe sur la poussée des fluides et son cri « Eurêka ! ». Il meurt lors du siège de sa ville par les Romains.",e:"Il est né et mort dans une grande cité grecque de Sicile.",p:"Syracuse, Italie",a:37.0754,o:15.2866},
{n:2,t:"Pythagore",c:"Mathématicien",x:"Philosophe et mathématicien grec du VIe siècle av. J.-C., dont le théorème sur le triangle rectangle est appris par tous les écoliers.",e:"Il est né sur une île de la mer Égée, proche de la côte de l'actuelle Turquie, avant de s'installer en Italie du Sud.",p:"Samos, Grèce",a:37.69,o:26.94},
{n:2,k:"vie",t:"Nicolas Copernic",c:"Astronome",q:"lieu où il travaille et est enterré",x:"Astronome qui place le Soleil au centre du monde. Chanoine d'un chapitre dont l'église fortifiée domine la lagune de la Vistule, en Varmie, il y observe le ciel pendant trente ans et y est enterré en 1543.",e:"Ses restes, identifiés en 2008 grâce à l'ADN de cheveux retrouvés dans l'un de ses livres, reposent dans la cathédrale de Frombork.",p:"Cathédrale de Frombork, Pologne",a:54.3577,o:19.6815},
{n:2,t:"Louis Braille",c:"Inventeur",x:"Devenu aveugle après un accident à trois ans, il invente à 15 ans un système d'écriture en points saillants.",e:"Il s'est blessé à l'œil dans l'atelier de bourrellerie de son père, dans un village de Seine-et-Marne.",p:"Coupvray, France",a:48.893,o:2.798},
{n:2,k:"vie",t:"Auguste et Louis Lumière",w:"Frères Lumière",c:"Inventeurs",q:"lieu de leur premier film",x:"Inventeurs du Cinématographe en 1895. Leur premier film montre les ouvriers sortant de l'usine familiale de plaques photographiques, dans le quartier de Monplaisir d'une grande ville au confluent du Rhône et de la Saône.",e:"Le hangar du premier film et la villa familiale abritent aujourd'hui l'Institut Lumière, rue du Premier-Film, à Lyon.",p:"Institut Lumière, Lyon, France",a:45.7451,o:4.8706},
{n:2,k:"vie",t:"Alan Turing",c:"Mathématicien",q:"lieu où il casse Enigma",x:"Mathématicien, père de l'informatique. Pendant la Seconde Guerre mondiale, il travaille dans un manoir secret du Buckinghamshire, à mi-chemin entre Oxford et Cambridge, où il conçoit une machine qui aide à déchiffrer les messages d'Enigma.",e:"Bletchley Park, aujourd'hui musée, employait près de 10 000 personnes à la fin de la guerre, dont une large majorité de femmes.",p:"Bletchley Park, Royaume-Uni",a:51.9977,o:-0.7407},
{n:2,k:"vie",t:"Robert Oppenheimer",c:"Physicien",q:"lieu de son laboratoire secret",x:"Physicien qui dirige la conception de la première bombe atomique. En 1943, il installe un laboratoire secret à la place d'une école de garçons, sur une mesa isolée du Nouveau-Mexique.",e:"Le laboratoire national de Los Alamos, né du projet Manhattan, est toujours l'un des grands centres de recherche nucléaire des États-Unis.",p:"Los Alamos, Nouveau-Mexique, États-Unis",a:35.88,o:-106.3031},
{n:2,k:"vie",t:"Alexander Fleming",c:"Biologiste",q:"lieu de sa découverte",x:"Médecin écossais, prix Nobel 1945. En septembre 1928, de retour de vacances, il remarque une moisissure dans une boîte de culture de son laboratoire, dans un hôpital de la capitale britannique.",e:"Son laboratoire de St Mary's Hospital, à Paddington, a été reconstitué en musée, l'Alexander Fleming Laboratory Museum.",p:"St Mary's Hospital, Londres, Royaume-Uni",a:51.5171,o:-0.1729},
{n:2,k:"vie",t:"Jacques-Yves Cousteau",c:"Océanographe",q:"musée qu'il dirige",x:"Inventeur du scaphandre autonome et commandant de la Calypso. De 1957 à 1988, il dirige un célèbre musée de la mer bâti à flanc de falaise par le prince Albert Ier, dans une petite principauté de la Méditerranée.",e:"Le Musée océanographique de Monaco, inauguré en 1910, surplombe la mer du haut du Rocher.",p:"Musée océanographique, Monaco",a:43.7308,o:7.4253},
{n:2,k:"vie",t:"Mark Zuckerberg",c:"Entrepreneur",q:"lieu où naît Facebook",x:"Fondateur de Facebook. En février 2004, il lance le site depuis sa chambre d'étudiant, dans le plus ancien établissement d'enseignement supérieur des États-Unis, près de Boston, qu'il quitte bientôt pour la Californie.",e:"Facebook, d'abord réservé aux étudiants de Harvard, à Cambridge (Massachusetts), s'ouvre à tous en 2006 ; Zuckerberg y reçoit un diplôme honoraire en 2017.",p:"Université Harvard, Cambridge, États-Unis",a:42.3744,o:-71.1169},
{n:2,t:"Jean-François Champollion",c:"Égyptologue",x:"Linguiste qui annonce en 1822 avoir déchiffré les hiéroglyphes égyptiens grâce à la pierre de Rosette.",e:"Il est né dans une ville du Quercy, où un musée des écritures du monde porte son nom.",p:"Figeac, France",a:44.6086,o:2.0317},
{n:2,k:"evt",t:"Invention du World Wide Web",w:"World Wide Web",c:"Informatique",q:"lieu de l'invention",x:"En 1989, un informaticien britannique propose un système de documents reliés par des liens hypertextes, pour partager l'information entre chercheurs.",e:"Tim Berners-Lee l'a inventé au CERN, le laboratoire de physique des particules situé à la frontière franco-suisse.",p:"CERN, Meyrin, près de Genève, Suisse",a:46.2338,o:6.0557},
{n:2,k:"evt",t:"Premier vol des frères Wright",w:"Wright Flyer",c:"Aviation",q:"lieu du premier vol",x:"Le 17 décembre 1903, Orville Wright vole 12 secondes et 37 mètres à bord d'un avion à moteur, une première pour un appareil plus lourd que l'air contrôlé.",e:"Le vol a eu lieu sur les dunes de Kill Devil Hills, près de Kitty Hawk, en Caroline du Nord.",p:"Kill Devil Hills, Caroline du Nord, États-Unis",a:36.014,o:-75.668},
{n:2,k:"evt",t:"Spoutnik 1",c:"Conquête spatiale",q:"lieu du lancement",x:"Le 4 octobre 1957, l'URSS met en orbite le premier satellite artificiel, une sphère de 58 cm qui émet un « bip-bip ».",e:"Il a été lancé depuis le cosmodrome de Baïkonour, dans la steppe du Kazakhstan.",p:"Baïkonour, Kazakhstan",a:45.92,o:63.342},
{n:2,k:"evt",t:"Première greffe du cœur",w:"Transplantation cardiaque",c:"Médecine",q:"lieu de l'opération",x:"Le 3 décembre 1967, le chirurgien Christiaan Barnard réalise la première transplantation cardiaque d'humain à humain.",e:"L'opération a eu lieu à l'hôpital Groote Schuur, au Cap, en Afrique du Sud.",p:"Le Cap, Afrique du Sud",a:-33.9411,o:18.463},
{n:2,k:"evt",t:"Brebis Dolly",c:"Biologie",q:"lieu de la naissance",x:"Née en 1996, c'est le premier mammifère cloné à partir d'une cellule adulte. Elle meurt en 2003.",e:"Elle est née à l'institut Roslin, près d'Édimbourg, en Écosse.",p:"Institut Roslin, près d'Édimbourg, Royaume-Uni",a:55.864,o:-3.2},
{n:2,k:"evt",t:"Lucy (australopithèque)",w:"Lucy (Australopithecus)",c:"Paléontologie",q:"lieu de la découverte",x:"En 1974, une équipe internationale découvre le squelette d'une australopithèque vieille d'environ 3,2 millions d'années, complet à environ 40 %.",e:"Elle a été découverte à Hadar, dans la dépression de l'Afar, en Éthiopie ; elle doit son nom à une chanson des Beatles.",p:"Hadar, Éthiopie",a:11.1,o:40.58},
{n:3,t:"Isaac Newton",c:"Science",x:"Mathématicien et physicien, auteur de la loi de la gravitation universelle. La légende de la pomme est liée au manoir où il est né.",e:"Le manoir de Woolsthorpe se trouve dans le Lincolnshire, près de Grantham, où Newton alla à l'école ; il appartient aujourd'hui au National Trust.",p:"Woolsthorpe, Royaume-Uni",a:52.8083,o:-0.6264},
{n:3,k:"vie",t:"Stephen Hawking",c:"Science",q:"université où il enseigne",x:"Cosmologiste d'Une brève histoire du temps. Atteint de la maladie de Charcot, il occupe pendant trente ans la chaire de mathématiques autrefois tenue par Newton, dans la ville universitaire anglaise rivale de sa ville natale.",e:"Il passe presque toute sa carrière à l'université de Cambridge ; ses cendres reposent depuis 2018 à l'abbaye de Westminster, près des tombes de Newton et de Darwin.",p:"Université de Cambridge, Royaume-Uni",a:52.2059,o:0.1177},
{n:3,t:"Nikola Tesla",c:"Science",x:"Inventeur du moteur à induction et du courant alternatif polyphasé. L'unité de champ magnétique porte son nom. Il est né dans l'Empire d'Autriche.",e:"Smiljan est un village de la Lika, près de Gospić, en Croatie ; sa maison natale, devenue centre commémoratif, se visite.",p:"Smiljan, Croatie",a:44.5667,o:15.3167},
{n:3,k:"vie",t:"Sigmund Freud",c:"Science",q:"adresse de son cabinet",x:"Père de la psychanalyse. Pendant 47 ans, il reçoit ses patients sur un divan au numéro 19 d'une rue de la capitale autrichienne, jusqu'à sa fuite à Londres en 1938.",e:"Le musée Sigmund Freud occupe son ancien appartement de la Berggasse, à Vienne ; son célèbre divan, lui, est resté à Londres.",p:"Berggasse 19, Vienne, Autriche",a:48.2186,o:16.3631},
{n:3,k:"vie",t:"Louis Pasteur",c:"Science",q:"lieu où il est enterré",x:"Inventeur de la pasteurisation et du vaccin contre la rage. Il repose dans une crypte décorée de mosaïques, au sous-sol de l'établissement de recherche qu'il a fondé en 1887 dans le sud-ouest de la capitale.",e:"L'Institut Pasteur, à Paris, a été financé par une souscription internationale ; Pasteur y est inhumé en 1896, un an après sa mort.",p:"Institut Pasteur, Paris, France",a:48.8404,o:2.311},
{n:3,t:"Johannes Kepler",c:"Astronome",x:"Astronome qui découvre au début du XVIIe siècle que les planètes décrivent des ellipses autour du Soleil.",e:"Il est né dans une petite ville du Wurtemberg, à l'ouest de Stuttgart.",p:"Weil der Stadt, Allemagne",a:48.7495,o:8.8718},
{n:3,t:"Ada Lovelace",c:"Mathématicienne",x:"Mathématicienne qui écrit dès 1843 ce que l'on considère comme le premier programme informatique, pour la machine analytique de Charles Babbage.",e:"Fille du poète Lord Byron, elle est née à Londres et n'a jamais connu son père.",p:"Londres, Royaume-Uni",a:51.5085,o:-0.1257},
{n:3,t:"Dmitri Mendeleïev",c:"Chimiste",x:"Chimiste qui publie en 1869 un tableau périodique des éléments, en laissant des cases vides pour des éléments encore inconnus.",e:"Il est né en Sibérie occidentale, dernier d'une très grande fratrie.",p:"Tobolsk, Russie",a:58.1981,o:68.2546},
{n:3,k:"vie",t:"Avicenne",c:"Médecin",q:"lieu où il est enterré",x:"Savant persan du Canon de la médecine. Après une vie d'errance entre les cours d'Iran, il meurt en 1037 dans une ville de l'ouest de l'Iran, l'ancienne Ecbatane, où un mausolée moderne à la tour élancée lui est dédié.",e:"Le mausolée d'Avicenne, à Hamadan, a été construit au début des années 1950 pour le millénaire de sa naissance.",p:"Hamadan, Iran",a:34.7983,o:48.5148},
{n:3,t:"Omar Khayyam",c:"Mathématicien",x:"Mathématicien, astronome et poète persan du XIe siècle, auteur de quatrains célèbres et d'un calendrier d'une grande précision.",e:"Il est né et enterré dans une ville du Khorassan, dans le nord-est de l'Iran.",p:"Nichapour, Iran",a:36.2133,o:58.7957},
{n:3,t:"Ibn al-Haytham",c:"Physicien",x:"Savant arabe du XIe siècle, surnommé le père de l'optique, qui explique la vision par la lumière entrant dans l'œil.",e:"Il est né dans un port du sud de la Mésopotamie avant de travailler au Caire.",p:"Bassora, Irak",a:30.5085,o:47.7804},
{n:3,t:"Srinivasa Ramanujan",c:"Mathématicien",x:"Mathématicien autodidacte qui envoie ses formules à un professeur de Cambridge en 1913 et devient l'un des plus grands spécialistes de la théorie des nombres.",e:"Il est né dans le Tamil Nadu, dans la maison de ses grands-parents.",p:"Erode, Inde",a:11.3428,o:77.7274},
{n:3,k:"vie",t:"C. V. Raman",w:"Chandrashekhara Venkata Râman",c:"Physicien",q:"ville de sa découverte",x:"Physicien, premier Asiatique prix Nobel de physique, en 1930. En 1928, dans le laboratoire de l'Association indienne pour la culture de la science, dans la grande ville du Bengale, il découvre l'effet qui porte son nom.",e:"La découverte, annoncée à Calcutta (Kolkata) le 28 février 1928, est célébrée chaque année à cette date par la Journée nationale de la science en Inde.",p:"Calcutta (Kolkata), Inde",a:22.5726,o:88.3639},
{n:3,t:"Hideyo Noguchi",c:"Bactériologiste",x:"Bactériologiste qui étudie la syphilis et la fièvre jaune, dont il meurt en 1928 au Ghana. Son portrait figure sur un billet de banque de son pays.",e:"Il est né dans un village au bord du lac Inawashiro, dans la préfecture de Fukushima.",p:"Inawashiro, Japon",a:37.56,o:140.1},
{n:3,t:"Cai Lun",c:"Inventeur",x:"Fonctionnaire de la cour impériale des Han à qui la tradition attribue l'invention du papier, vers l'an 105.",e:"Il est né dans le Hunan, au sud du Yangzi.",p:"Leiyang, Hunan, Chine",a:26.4024,o:112.8591},
{n:3,t:"James Watt",c:"Ingénieur",x:"Ingénieur qui perfectionne la machine à vapeur à la fin du XVIIIe siècle ; l'unité de puissance porte son nom.",e:"Il est né dans un port de l'estuaire de la Clyde, à l'ouest de Glasgow.",p:"Greenock, Royaume-Uni",a:55.9484,o:-4.7612},
{n:3,k:"vie",t:"Ernest Rutherford",c:"Physicien",q:"ville où il découvre le noyau",x:"Physicien néo-zélandais, père de la physique nucléaire. En 1911, professeur dans une grande ville industrielle du nord de l'Angleterre, il déduit d'une expérience sur une feuille d'or que l'atome possède un noyau.",e:"À l'université de Manchester, il réalise aussi la première transmutation artificielle d'un élément, avant de prendre en 1919 la direction du laboratoire Cavendish de Cambridge.",p:"Université de Manchester, Manchester, Royaume-Uni",a:53.4668,o:-2.2339},
{n:3,t:"Niels Bohr",c:"Physicien",x:"Physicien qui propose en 1913 un modèle de l'atome où les électrons occupent des orbites précises. Prix Nobel en 1922.",e:"Il est né, a fondé son institut et est mort dans la capitale de son pays.",p:"Copenhague, Danemark",a:55.6759,o:12.5655},
{n:3,t:"Max Planck",c:"Physicien",x:"Physicien père de la théorie des quanta en 1900. Une constante fondamentale et un grand réseau d'instituts portent son nom.",e:"Il est né dans un port de la Baltique, dans le Schleswig-Holstein.",p:"Kiel, Allemagne",a:54.3213,o:10.1349},
{n:3,t:"Edward Jenner",c:"Médecin",x:"Médecin de campagne qui met au point en 1796 la première vaccination, contre la variole, à partir de la vaccine des vaches.",e:"Il est né, a exercé et est mort dans un village du Gloucestershire.",p:"Berkeley, Gloucestershire, Royaume-Uni",a:51.691,o:-2.458},
{n:3,t:"Hedy Lamarr",c:"Inventrice",x:"Star de Hollywood qui dépose en 1942 un brevet de transmission par sauts de fréquence, ancêtre de technologies utilisées par le Wi-Fi.",e:"Elle est née dans la capitale autrichienne sous le nom de Hedwig Kiesler.",p:"Vienne, Autriche",a:48.2085,o:16.3721},
{n:3,k:"vie",t:"Katherine Johnson",c:"Mathématicienne",q:"centre de la NASA où elle travaille",x:"Mathématicienne des Figures de l'ombre. De 1953 à 1986, elle calcule des trajectoires spatiales dans un centre aéronautique de la côte de Virginie, où travaillaient des « calculatrices » noires.",e:"Le centre de recherche Langley, à Hampton, a donné son nom en 2017 à un bâtiment, le Katherine G. Johnson Computational Research Facility.",p:"Centre de recherche Langley, Hampton, Virginie, États-Unis",a:37.0857,o:-76.3806},
{n:3,k:"vie",t:"Ahmed Zewail",c:"Chimiste",q:"université de ses travaux",x:"Chimiste égyptien, prix Nobel 1999. Installé aux États-Unis, il mène ses recherches sur la femtochimie dans un célèbre institut de technologie de la banlieue de Los Angeles, au pied des monts San Gabriel.",e:"Il est professeur au California Institute of Technology (Caltech), à Pasadena, de 1976 à sa mort en 2016.",p:"Caltech, Pasadena, Californie, États-Unis",a:34.1377,o:-118.1253},
{n:3,t:"Tu Youyou",c:"Pharmacologue",x:"Pharmacologue qui découvre l'artémisinine, un traitement contre le paludisme inspiré de la médecine traditionnelle. Prix Nobel de médecine 2015.",e:"Elle est née dans un grand port du Zhejiang, au sud de Shanghai.",p:"Ningbo, Chine",a:29.8782,o:121.5494},
{n:3,k:"vie",t:"Jeff Bezos",c:"Entrepreneur",q:"ville où il fonde Amazon",x:"Fondateur d'Amazon. En 1994, il quitte la finance new-yorkaise, traverse le pays en voiture et lance une librairie en ligne dans le garage de sa maison louée, dans la banlieue est de Seattle.",e:"Amazon naît dans un garage de Bellevue, de l'autre côté du lac Washington par rapport à Seattle, où l'entreprise installe ensuite son siège.",p:"Bellevue, Washington, États-Unis",a:47.6101,o:-122.2015},
{n:3,k:"evt",t:"Essai Trinity",c:"Physique nucléaire",q:"lieu de l'essai",x:"Le 16 juillet 1945, l'armée américaine fait exploser la première bombe atomique de l'histoire, dans le désert.",e:"L'essai a eu lieu dans le désert de la Jornada del Muerto, au Nouveau-Mexique.",p:"Jornada del Muerto, Nouveau-Mexique, États-Unis",a:33.6773,o:-106.4754},
{n:3,k:"evt",t:"Structure de l'ADN",w:"Acide désoxyribonucléique",c:"Biologie",q:"lieu de la découverte",x:"En 1953, James Watson et Francis Crick publient le modèle en double hélice de l'ADN, en s'appuyant sur les clichés de Rosalind Franklin.",e:"La découverte a été faite au laboratoire Cavendish de l'université de Cambridge.",p:"Cambridge, Royaume-Uni",a:52.2043,o:0.1149},
{n:3,k:"evt",t:"Point de vue du Gras",c:"Photographie",q:"lieu de la prise de vue",x:"Vers 1827, Nicéphore Niépce réalise depuis sa fenêtre la plus ancienne photographie connue prise d'après nature, avec une pose de plusieurs heures.",e:"Elle a été prise dans sa propriété de Saint-Loup-de-Varennes, près de Chalon-sur-Saône.",p:"Saint-Loup-de-Varennes, France",a:46.723,o:4.855},
{n:3,k:"evt",t:"Premier vol de Concorde",w:"Concorde (avion)",c:"Aviation",q:"lieu du premier vol",x:"Le 2 mars 1969, le premier avion de ligne supersonique franco-britannique effectue son vol inaugural de 27 minutes.",e:"Il a décollé de l'aéroport de Toulouse-Blagnac, où il avait été assemblé.",p:"Toulouse, France",a:43.629,o:1.364}
]);

/* ---- Culture populaire : fiction, cinéma, séries, jeux vidéo, bande dessinée ---- */
ajouter('pop', 'recit', [
{n:1,t:"Sherlock Holmes",c:"Personnage de fiction",q:"adresse du détective",x:"Détective créé par Arthur Conan Doyle en 1887, célèbre pour ses déductions, sa pipe et son fidèle ami le docteur Watson.",e:"Il habite au 221B Baker Street, à Londres ; un musée occupe aujourd'hui une maison de la rue.",p:"Baker Street, Londres, Royaume-Uni",a:51.5238,o:-0.1586},
{n:1,t:"Friends",c:"Série",q:"ville où se déroule la série",x:"Série culte de 1994 à 2004 qui suit six amis trentenaires et leurs rendez-vous au café Central Perk.",e:"La série se déroule à New York, dans le quartier de Greenwich Village, mais a été tournée en studio à Los Angeles.",p:"Greenwich Village, New York, États-Unis",a:40.7323,o:-74.0054},
{n:1,t:"Le Fabuleux Destin d'Amélie Poulain",c:"Film",q:"quartier où se déroule le film",x:"Film de Jean-Pierre Jeunet sorti en 2001 : une jeune serveuse timide décide de faire le bonheur des gens qui l'entourent.",e:"Le film se déroule à Montmartre ; le café des Deux Moulins, où travaille Amélie, existe vraiment.",p:"Montmartre, Paris, France",a:48.8848,o:2.3335},
{n:1,t:"Rocky Balboa",w:"Rocky Balboa (personnage)",c:"Personnage de fiction",q:"ville où se déroule le film",x:"Boxeur de seconde zone incarné par Sylvester Stallone à partir de 1976, qui monte les marches d'un musée en courant lors de son entraînement.",e:"Les « Rocky Steps » sont les marches du musée d'art de Philadelphie, où se dresse une statue du boxeur.",p:"Philadelphie, États-Unis",a:39.9656,o:-75.181},
{n:1,t:"Pokémon",c:"Jeu vidéo",q:"ville du studio créateur",x:"Série de jeux lancée en 1996 où l'on capture et entraîne des créatures, devenue la franchise de divertissement la plus lucrative au monde.",e:"Elle a été créée par le studio Game Freak, à Tokyo, et éditée par Nintendo.",p:"Tokyo, Japon",a:35.6762,o:139.6503},
{n:1,t:"Robin des Bois",c:"Légende",q:"forêt associée à la légende",x:"Hors-la-loi légendaire, archer hors pair qui vole aux riches pour donner aux pauvres et défie le shérif de Nottingham.",e:"La légende le fait vivre dans la forêt de Sherwood, où un très vieux chêne, le Major Oak, lui est associé.",p:"Forêt de Sherwood, Royaume-Uni",a:53.2047,o:-1.0717},
{n:1,t:"Spider-Man",c:"Personnage de fiction",q:"quartier où vit le héros",x:"Super-héros créé en 1962 par Stan Lee et Steve Ditko : un adolescent orphelin, mordu par une araignée, vit chez sa tante May.",e:"Peter Parker habite Forest Hills, dans le Queens, à New York.",p:"Forest Hills, Queens, New York, États-Unis",a:40.7181,o:-73.8448},
{n:1,t:"Super Mario Bros.",c:"Jeu vidéo",q:"ville de l'éditeur",x:"Jeu de plateforme sorti en 1985 où un plombier moustachu saute sur des champignons pour sauver une princesse.",e:"Il a été créé par Nintendo, dont le siège se trouve à Kyoto, au Japon.",p:"Kyoto, Japon",a:34.9697,o:135.7562},
{n:1,t:"Astérix",c:"Bande dessinée",q:"région où se trouve le village",x:"Petit guerrier gaulois créé en 1959 par Goscinny et Uderzo, dont le village résiste encore et toujours à l'envahisseur romain grâce à une potion magique.",e:"Le village se trouve en Armorique, l'actuelle Bretagne, au bord de la Manche.",p:"Armorique (Bretagne), France",a:48.5,o:-3},
{n:2,t:"Breaking Bad",c:"Série",q:"ville où se déroule la série",x:"Série de 2008 à 2013 où un professeur de chimie atteint d'un cancer se lance dans la fabrication de méthamphétamine.",e:"Elle se déroule et a été tournée à Albuquerque, au Nouveau-Mexique.",p:"Albuquerque, Nouveau-Mexique, États-Unis",a:35.0844,o:-106.6504},
{n:2,t:"Tetris",c:"Jeu vidéo",q:"ville du studio créateur",x:"Jeu de puzzle créé en 1984 par l'ingénieur Alekseï Pajitnov, où l'on empile des pièces formées de quatre carrés.",e:"Il a été conçu au centre de calcul de l'Académie des sciences, à Moscou, en Union soviétique.",p:"Moscou, Russie",a:55.7558,o:37.6173},
{n:2,t:"Minecraft",c:"Jeu vidéo",q:"ville du studio créateur",x:"Jeu de construction en cubes sorti en 2011, devenu le jeu vidéo le plus vendu de l'histoire.",e:"Il a été créé par Markus « Notch » Persson et le studio Mojang, à Stockholm, en Suède.",p:"Stockholm, Suède",a:59.3293,o:18.0686},
{n:2,t:"Assassin's Creed",c:"Jeu vidéo",q:"ville du studio créateur",x:"Série de jeux lancée en 2007 où l'on incarne des membres d'une confrérie secrète à différentes époques historiques.",e:"Le premier jeu a été développé par Ubisoft Montréal, au Québec.",p:"Montréal, Canada",a:45.5017,o:-73.5673},
{n:2,t:"Poudlard Express",c:"Cinéma",q:"lieu de tournage du viaduc",x:"Train à vapeur rouge qui emmène les élèves vers l'école de sorcellerie dans les films Harry Potter, en traversant un célèbre viaduc courbe.",e:"Le viaduc de Glenfinnan, dans les Highlands écossais, apparaît dans plusieurs films de la saga.",p:"Viaduc de Glenfinnan, Écosse, Royaume-Uni",a:56.8761,o:-5.4317},
{n:2,t:"Game of Thrones",c:"Série",q:"ville de tournage de Port-Réal",x:"Série de 2011 à 2019 adaptée des romans de George R. R. Martin, où des familles nobles se disputent le Trône de fer.",e:"La capitale Port-Réal a été tournée en grande partie dans la vieille ville de Dubrovnik, en Croatie.",p:"Dubrovnik, Croatie",a:42.6507,o:18.0944},
{n:2,t:"Le Seigneur des anneaux (série de films)",w:"Le Seigneur des anneaux (série de films)",c:"Cinéma",q:"lieu de tournage de la Comté",x:"Trilogie de Peter Jackson sortie de 2001 à 2003, d'après Tolkien ; le dernier volet remporte onze Oscars.",e:"Le village des Hobbits a été construit près de Matamata, en Nouvelle-Zélande, et se visite toujours.",p:"Hobbiton, Matamata, Nouvelle-Zélande",a:-37.8721,o:175.6829},
{n:2,t:"Star Wars, épisode IV : Un nouvel espoir",c:"Cinéma",q:"lieu de tournage de la maison de Luke",x:"Film de George Lucas sorti en 1977, où un jeune fermier d'une planète désertique rejoint la rébellion contre l'Empire.",e:"La maison troglodyte de Luke sur Tatooine a été tournée dans un hôtel de Matmata, dans le sud de la Tunisie.",p:"Matmata, Tunisie",a:33.5427,o:9.9675},
{n:2,t:"La casa de papel",c:"Série",q:"ville où se déroule la série",x:"Série de 2017 à 2021 : une bande de braqueurs aux masques de Dalí, dirigée par « le Professeur », s'enferme dans la fabrique nationale de monnaie.",e:"Elle se déroule à Madrid ; la série est devenue la plus regardée de Netflix parmi les productions non anglophones à l'époque.",p:"Madrid, Espagne",a:40.4168,o:-3.7038},
{n:2,t:"Slumdog Millionaire",c:"Film",q:"ville où se déroule le film",x:"Film de Danny Boyle sorti en 2008, huit fois oscarisé : un jeune homme des bidonvilles participe à un jeu télévisé de culture générale.",e:"Le film se déroule à Mumbai, notamment dans le bidonville de Dharavi.",p:"Mumbai, Inde",a:19.038,o:72.8538},
{n:2,t:"Vito Corleone",c:"Personnage de fiction",q:"village natal du personnage",x:"Parrain d'une famille mafieuse de New York dans le roman de Mario Puzo et le film de Coppola, incarné par Marlon Brando puis Robert De Niro.",e:"Son nom de famille vient de son village natal, Corleone, en Sicile, où commence le deuxième film.",p:"Corleone, Sicile, Italie",a:37.8139,o:13.3013},
{n:2,t:"Dracula",c:"Personnage de fiction",q:"région d'origine du personnage",x:"Vampire aristocrate du roman de Bram Stoker paru en 1897, qui quitte son château pour l'Angleterre.",e:"Il vit en Transylvanie ; le héros Jonathan Harker passe par la ville de Bistritz (Bistrița) avant d'atteindre le château.",p:"Transylvanie, Roumanie",a:47.133,o:24.49},
{n:2,k:"perso",t:"Hergé",c:"Auteur de bande dessinée",x:"Auteur des Aventures de Tintin, dont le premier album paraît en 1930, et maître de la « ligne claire ».",e:"Il est né à Etterbeek, une commune de la région bruxelloise.",p:"Etterbeek, Bruxelles, Belgique",a:50.8333,o:4.3833},
{n:2,k:"vie",t:"Walt Disney",c:"Producteur",q:"parc d'attractions qu'il crée",x:"Créateur de Mickey Mouse. En 1955, il ouvre dans la banlieue sud-est de Los Angeles le premier parc à thème de son empire, avec un château de conte de fées en son centre.",e:"Disneyland, à Anaheim en Californie, est le seul parc dont Walt Disney a vu l'ouverture ; il meurt en 1966, avant celle de Walt Disney World en Floride.",p:"Disneyland, Anaheim, Californie, États-Unis",a:33.8121,o:-117.919},
{n:2,k:"perso",t:"Hayao Miyazaki",c:"Réalisateur",x:"Cofondateur du studio Ghibli, réalisateur de Mon voisin Totoro et du Voyage de Chihiro, Oscar du meilleur film d'animation en 2003.",e:"Il est né dans l'arrondissement de Bunkyō, à Tokyo.",p:"Tokyo, Japon",a:35.7081,o:139.7523},
{n:3,t:"The Witcher 3",w:"The Witcher 3: Wild Hunt",c:"Jeu vidéo",q:"ville du studio créateur",x:"Jeu de rôle sorti en 2015 où l'on incarne Geralt de Riv, un chasseur de monstres aux cheveux blancs, d'après les romans d'Andrzej Sapkowski.",e:"Il a été développé par CD Projekt Red, à Varsovie, en Pologne.",p:"Varsovie, Pologne",a:52.2297,o:21.0122},
{n:3,t:"Angry Birds",c:"Jeu vidéo",q:"ville du studio créateur",x:"Jeu pour téléphone sorti en 2009, où l'on catapulte des oiseaux sur des cochons verts qui leur ont volé leurs œufs.",e:"Il a été créé par le studio Rovio, à Espoo, près d'Helsinki, en Finlande.",p:"Espoo, Finlande",a:60.2055,o:24.6559},
{n:3,t:"Grand Theft Auto",c:"Jeu vidéo",q:"ville du studio créateur",x:"Série de jeux lancée en 1997 où l'on évolue librement dans une ville en commettant des délits, l'une des plus vendues de l'histoire.",e:"Le premier jeu a été développé par DMA Design, à Dundee, en Écosse.",p:"Dundee, Royaume-Uni",a:56.462,o:-2.9707},
{n:3,t:"Fortnite",c:"Jeu vidéo",q:"ville du studio créateur",x:"Jeu de survie sorti en 2017 dont le mode « battle royale » réunit cent joueurs sur une île qui rétrécit.",e:"Il a été développé par Epic Games, dont le siège est à Cary, en Caroline du Nord.",p:"Cary, Caroline du Nord, États-Unis",a:35.7915,o:-78.7811},
{n:3,t:"Squid Game",c:"Série",q:"ville où se déroule la série",x:"Série de 2021 où 456 personnes endettées s'affrontent dans des jeux d'enfants mortels pour remporter une fortune.",e:"Le héros, Seong Gi-hun, vit à Séoul, dans le quartier de Ssangmun-dong.",p:"Séoul, Corée du Sud",a:37.648,o:127.034},
{n:3,t:"Heidi",c:"Personnage de fiction",q:"village où se déroule l'histoire",x:"Petite orpheline envoyée vivre chez son grand-père dans les alpages, héroïne du roman de Johanna Spyri paru en 1880.",e:"L'histoire se déroule près de Maienfeld, dans les Grisons, où l'on visite un « village de Heidi ».",p:"Maienfeld, Suisse",a:47.008,o:9.53},
{n:3,t:"Zorro",c:"Personnage de fiction",q:"ville où se déroule l'histoire",x:"Justicier masqué créé en 1919 par Johnston McCulley, qui signe ses exploits d'un Z tracé à la pointe de l'épée.",e:"Don Diego de la Vega vit dans le pueblo de Los Angeles, en Californie alors espagnole puis mexicaine.",p:"Los Angeles, Californie, États-Unis",a:34.0522,o:-118.2437},
{n:3,t:"Downton Abbey",c:"Série",q:"château de tournage",x:"Série britannique de 2010 à 2015 qui suit une famille aristocrate et ses domestiques au début du XXe siècle.",e:"Le château de Highclere, dans le Hampshire, a servi de décor au manoir de Downton.",p:"Château de Highclere, Royaume-Uni",a:51.3267,o:-1.3605},
{n:3,t:"La Mélodie du bonheur",c:"Film",q:"ville où se déroule le film",x:"Comédie musicale de 1965 avec Julie Andrews : une novice devient gouvernante des sept enfants d'un capitaine veuf, à la veille de l'Anschluss.",e:"Le film se déroule et a été tourné à Salzbourg et dans ses environs.",p:"Salzbourg, Autriche",a:47.8095,o:13.055},
{n:3,k:"perso",t:"Eiichirō Oda",c:"Mangaka",x:"Auteur de One Piece, manga de pirates commencé en 1997, l'une des bandes dessinées les plus vendues de l'histoire.",e:"Il est né dans la ville de Kumamoto, sur l'île de Kyūshū, où des statues de ses personnages ont été installées.",p:"Kumamoto, Japon",a:32.8059,o:130.6918},
{n:3,k:"perso",t:"Akira Toriyama",c:"Mangaka",x:"Auteur de Dragon Ball et du dessin des personnages de Dragon Quest, mort en 2024.",e:"Il est né et a vécu toute sa vie dans la région de Nagoya.",p:"Nagoya, Japon",a:35.1815,o:136.9064},
{n:3,k:"perso",t:"Shigeru Miyamoto",c:"Concepteur de jeux vidéo",x:"Concepteur de Donkey Kong, Super Mario Bros. et The Legend of Zelda chez Nintendo.",e:"Il est né dans un petit bourg rural au nord-ouest de Kyoto, dont les collines ont inspiré les explorations de Zelda.",p:"Sonobe, préfecture de Kyoto, Japon",a:35.1,o:135.47},
{n:3,k:"perso",t:"Matt Groening",c:"Dessinateur",x:"Créateur des Simpson, la série d'animation la plus longue de l'histoire de la télévision américaine, et de Futurama.",e:"Il est né à Portland, dans l'Oregon ; plusieurs personnages des Simpson portent des noms de rues de sa ville.",p:"Portland, Oregon, États-Unis",a:45.5234,o:-122.6762},
{n:3,k:"perso",t:"Stan Lee",c:"Scénariste",x:"Scénariste et éditeur de Marvel, cocréateur de Spider-Man, des Quatre Fantastiques, de Hulk et des X-Men.",e:"Il est né à Manhattan, à New York, dans une famille d'immigrés roumains.",p:"New York, États-Unis",a:40.7143,o:-74.006}
]);
